'use strict';

var T = window.DASH_I18N || {};
function t(path, fallback) {
  var parts = path.split('.');
  var cur = T;
  for (var i = 0; i < parts.length; i++) {
    if (cur == null || typeof cur !== 'object') return fallback;
    cur = cur[parts[i]];
  }
  return (cur == null) ? fallback : cur;
}

