/* ============================================================
   PLAN GATING
   Plan resolution order:
     1. ?plan= query param        (highest priority, validated)
     2. client-bot-config.plan    (or legacy hostingType string)
     3. 'ai-agent'               (this template's home plan)
   Plan ids: 'ai-agent' | 'all-in-one' | 'professional-website'.
   Gating is declarative: elements carry data-plans="a b c" and are
   hidden unless the active plan is listed (see applyPlanGating).
   ============================================================ */
var PLAN_IDS = ['ai-agent', 'all-in-one', 'professional-website'];
/* Display names for the subtle plan chip near the sidebar user card.
   Plan names are product names - identical in EN and ID. */
var PLAN_LABELS = {
  'ai-agent': 'AI Agent',
  'all-in-one': 'All-in-One',
  'professional-website': 'Professional Website'
};
var planQueryParam = new URLSearchParams(window.location.search).get('plan');

function normalizePlan(p) {
  p = String(p == null ? '' : p).trim().toLowerCase();
  if (PLAN_IDS.indexOf(p) !== -1) return p;
  if (p === 'pro-web' || p === 'proweb') return 'professional-website';
  // Tolerate legacy hostingType strings (engine may pass them through later).
  // Legacy 'pro-ai-agent' / managed ids are unified into the home plan (2026-08-24).
  if (p === 'pro ai agent' || p === 'pro-ai' || p === 'proai' || p === 'ai agent pro' || p === 'standalone ai agent' || p === 'pro-ai-agent') return 'ai-agent';
  if (p === 'managed ai agent' || p === 'managed ai' || p === 'ai agent') return 'ai-agent';
  if (p === 'all-in-one suite' || p === 'all in one' || p === 'allinone' || p === 'all-in-one') return 'all-in-one';
  if (p === 'professional website' || p === 'pro-website' || p === 'website' || p === 'managed website') return 'professional-website';
  return null;
}
function getCurrentPlan() {
  var fromQuery = normalizePlan(planQueryParam);
  if (fromQuery) return fromQuery;
  var cfg = (typeof waAiConfig !== 'undefined') ? waAiConfig : null;
  var fromConfig = cfg && (normalizePlan(cfg.plan) || normalizePlan(cfg.hostingType));
  if (fromConfig) return fromConfig;
  return 'ai-agent';
}
/* WA-AI surface (live chat, AI config, escalation, WA sends) exists on
   every plan EXCEPT professional-website (website + dashboard, no AI). */
function planHasWaAi() {
  var cfg = (typeof waAiConfig !== 'undefined') ? waAiConfig : null;
  if (cfg && cfg.aiBotEnabled === false) return false;
  return getCurrentPlan() !== 'professional-website';
}

