var SELLING_PRIMITIVES = ['product', 'booking', 'pass'];
var SELLING_TYPE_IDS = ['product', 'booking', 'pass', 'package'];
var SELLING_MODIFIER_IDS = ['quote'];
var ALL_SELLING_TAXONOMY = ['product', 'booking', 'pass', 'package', 'quote'];

function sanitizeSellingModes(list) {
  if (!Array.isArray(list)) return [];
  var out = [];
  var legacyMap = {
    service: 'booking', booking: 'booking',
    rental: 'booking', package: 'package', membership: 'pass', voucher: 'pass',
    product: 'product', pass: 'pass'
  };
  list.forEach(function (m) {
    m = String(m == null ? '' : m).trim().toLowerCase();
    var canonical = legacyMap[m] || m;
    if (ALL_SELLING_TAXONOMY.indexOf(canonical) !== -1 && out.indexOf(canonical) === -1) out.push(canonical);
  });
  // canonical taxonomy order
  return ALL_SELLING_TAXONOMY.filter(function (id) { return out.indexOf(id) !== -1; });
}

