function $(id) { return document.getElementById(id); }
function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function fmtTime(iso) {
  if (!iso) return '-';
  var d = new Date(iso);
  return isNaN(d) ? '-' : d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}
function fmtDate(iso) {
  if (!iso) return '-';
  var d = new Date(iso);
  return isNaN(d) ? '-' : d.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' });
}
function fmtDateTime(iso) {
  if (!iso) return '-';
  var d = new Date(iso);
  return isNaN(d) ? '-' : d.toLocaleDateString(undefined, { day: 'numeric', month: 'short' }) + ' ' + d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}
function relTime(iso) {
  var d = new Date(iso);
  if (isNaN(d)) return '-';
  var diff = Date.now() - d.getTime();
  var m = Math.floor(diff / 60000);
  if (m < 1) return t('time.justNow', 'just now');
  if (m < 60) return m + ' ' + t('time.minAgo', 'min ago');
  var h = Math.floor(m / 60);
  if (h < 24) return h + ' ' + t('time.hrAgo', 'hr ago');
  var days = Math.floor(h / 24);
  return days + ' ' + t('time.dayAgo', 'd ago');
}

function showToast(msg, kind) {
  if (typeof msg === 'string') {
    msg = msg.replace(/<[^>]*>?/gm, '').trim();
  }
  if (!msg) return;
  var wrap = $('toast-wrap');
  if (!wrap) { wrap = document.createElement('div'); wrap.id = 'toast-wrap'; wrap.className = 'toast-wrap'; document.body.appendChild(wrap); }
  var el = document.createElement('div');
  var variant = kind || 'info';
  el.className = 'toast ' + variant;

  var iconClass = 'fa-solid fa-circle-info';
  if (variant === 'success') iconClass = 'fa-solid fa-circle-check';
  else if (variant === 'error') iconClass = 'fa-solid fa-circle-exclamation';
  else if (variant === 'amber' || variant === 'warning') iconClass = 'fa-solid fa-triangle-exclamation';

  var iconEl = document.createElement('i');
  iconEl.className = 'toast-icon ' + iconClass;
  var msgEl = document.createElement('span');
  msgEl.className = 'toast-msg';
  msgEl.textContent = msg;

  el.appendChild(iconEl);
  el.appendChild(msgEl);
  wrap.appendChild(el);
  setTimeout(function () {
    el.classList.add('out');
    setTimeout(function () { if (el.parentNode) el.parentNode.removeChild(el); }, 300);
  }, 3200);
}

function emptyState(icon, title, desc, ctaHtml) {
  return '<div class="empty-state">' +
    '<div class="empty-state-icon">' + icon + '</div>' +
    '<div class="empty-state-title">' + esc(title) + '</div>' +
    '<div class="empty-state-desc">' + esc(desc) + '</div>' +
    (ctaHtml || '') +
    '</div>';
}

