/* ============================================================
   THEME SYSTEM
   Theme = full CSS custom-property palette swap via
   [data-theme] on <html>. Resolution order:
     1. localStorage 'codaxiom-dash-theme'  (explicit user choice)
     2. client-bot-config.dashboardTheme    (per-client default)
     3. 'dark'                              (product default)
   ============================================================ */
var THEME_KEY = 'codaxiom-dash-theme';

function applyTheme(theme, persist) {
  if (theme !== 'light' && theme !== 'dark') theme = 'dark';
  document.documentElement.setAttribute('data-theme', theme);
  if (document.body) {
    document.body.setAttribute('data-theme', theme);
    document.documentElement.classList.toggle('light-theme', theme === 'light');
    document.body.classList.toggle('light-theme', theme === 'light');
  }
  if (persist) {
    try {
      localStorage.setItem(THEME_KEY, theme);
      sessionStorage.setItem(THEME_KEY, theme);
    } catch (e) {}
  }
  if (window.Chart) applyChartTheme();
  // Always re-render custom SVG analytics charts on theme toggle
  if (analyticsLoaded && typeof renderAnalyticsCharts === 'function') {
    renderAnalyticsCharts(analyticsCache);
  }
  // Always re-render catalog insights on theme toggle if initialized
  var catPane = $('cat-pane-analytics');
  if (catPane && typeof renderCatalogAnalytics === 'function') {
    renderCatalogAnalytics();
  }
  // Re-render Overview ApexCharts sparklines on theme toggle
  if (typeof renderOverviewApexSparklines === 'function') {
    renderOverviewApexSparklines(null, true);
  }
  if (window.__ov_modal_metric && typeof renderOverviewModalContent === 'function') {
    renderOverviewModalContent(true);
  }
  // Niche modules receive theme via ctx - re-render so their scoped
  // [data-theme] root attribute tracks the shell (contract Section 6).
  if (typeof rerenderActiveNicheModule === 'function') rerenderActiveNicheModule(activeModuleId);
}
function toggleTheme() {
  var current = document.documentElement.getAttribute('data-theme') === 'light' ? 'light' : 'dark';
  applyTheme(current === 'dark' ? 'light' : 'dark', true);
}
function getStoredTheme() {
  try { return localStorage.getItem(THEME_KEY) || sessionStorage.getItem(THEME_KEY); } catch (e) { return null; }
}

function applyChartTheme() {
  if (!window.Chart) return;
  var cs = getComputedStyle(document.documentElement);
  Chart.defaults.color = cs.getPropertyValue('--chart-tick').trim() || '#888';
  Chart.defaults.borderColor = cs.getPropertyValue('--chart-grid').trim() || 'rgba(128,128,128,0.1)';
  Chart.defaults.font.family = 'Inter';
  // Re-render analytics if that panel has been built
  if (analyticsLoaded) renderAnalyticsCharts(analyticsCache);
}

/* ============================================================
   DEMO COCKPIT ISOLATION HELPER
   ============================================================ */
function isClientCapsuleHost(host) {
  host = host || window.location.hostname;
  if (host === 'localhost' || host === '127.0.0.1') return false;
  if (host === 'codaxiom.com' || host === 'www.codaxiom.com') return false;
  return true;
}
window.isClientCapsuleHost = isClientCapsuleHost;

function isSandboxedDemoCockpit() {
  if (isClientCapsuleHost()) return false;
  if (window.__SANDBOXED_DEMO__ === true) return true;
  var params = new URLSearchParams(window.location.search);
  var path = window.location.pathname || '';
  if (params.get('demo') === 'true' || path.indexOf('/demo') !== -1 || path.endsWith('/demo')) return true;
  if (/^\/[a-z0-9-]+\/(?:ai-agent|standalone)\//.test(path)) return true;
  if (params.has('niche') && params.get('niche') !== 'master') return true;
  return false;
}
window.isSandboxedDemoCockpit = isSandboxedDemoCockpit;

/* ============================================================
   HOST MODEL (law 2026-08-26, PRD-ai-agent-dashboard.md §3)
   - MASTER cockpit hosts: localhost (dev), codaxiom.com/ai-agent/* (production).
   - CLIENT cockpit hosts: {slug}.codaxiom.com or a client custom domain —
     the first hostname label is the tenant subdomain.
   - dashBase(): local dev serves under /ai-agent/* (next dev rewrites);
     every deployed surface serves at ROOT (/login, /admin).
   ============================================================ */
function isMasterDashboardHost(host) {
  host = host || window.location.hostname;
  if (host === 'localhost' || host === '127.0.0.1') return true;
  var p = window.location.pathname;
  return /^\/(ai-agent|standalone)(\/|$)/.test(p); // codaxiom.com/ai-agent/* or /standalone/* (flat base, no niche)
}
window.isMasterDashboardHost = isMasterDashboardHost;
function dashBase() {
  var host = window.location.hostname;
  var p = window.location.pathname;
  var m = p.match(/^\/((?:[a-z0-9-]+\/)?(?:ai-agent|standalone))(?:\/|$)/);
  if (m) return '/' + m[1];
  return (host === 'localhost' || host === '127.0.0.1') ? '/ai-agent' : '';
}
window.dashBase = dashBase;

/* ============================================================
   SUBDOMAIN / API HELPER
   ============================================================ */
function waAiGetSubdomain() {
  var host = window.location.hostname;
  if (isClientCapsuleHost(host)) {
    if (host.indexOf('.codaxiom.com') !== -1) {
      return host.split('.')[0];
    }
    if (window.CLIENT_CONFIG && window.CLIENT_CONFIG.subdomain) return window.CLIENT_CONFIG.subdomain;
    try {
      var sessRaw = sessionStorage.getItem('dash_session') || localStorage.getItem('dash_session');
      if (sessRaw) {
        var sessObj = JSON.parse(sessRaw);
        if (sessObj && sessObj.subdomain && sessObj.subdomain !== 'demo' && sessObj.subdomain !== 'codaxiom') {
          return sessObj.subdomain;
        }
      }
    } catch (e) {}
    var storedClient = null;
    try { storedClient = localStorage.getItem('clientSubdomain'); } catch (e) {}
    if (storedClient && storedClient !== 'demo' && storedClient !== 'codaxiom') return storedClient;
    var elClient = document.querySelector('[data-subdomain]');
    if (elClient && elClient.getAttribute('data-subdomain')) return elClient.getAttribute('data-subdomain');
    return host.split('.')[0];
  }

  if (isSandboxedDemoCockpit()) return 'demo';

  var params = new URLSearchParams(window.location.search);
  var overrideSub = (params.get('subdomain') || '').trim().toLowerCase();
  if (/^[a-z0-9-]{1,60}$/.test(overrideSub) && overrideSub !== 'demo') {
    return overrideSub;
  }

  if (host.indexOf('.codaxiom.com') !== -1 && host !== 'codaxiom.com' && host !== 'www.codaxiom.com') {
    return host.split('.')[0];
  }

  var el = document.querySelector('[data-subdomain]');
  if (el && el.getAttribute('data-subdomain')) return el.getAttribute('data-subdomain');

  var isDemoUrl = params.get('demo') === 'true' || window.location.pathname.indexOf('/demo') !== -1 || (params.has('niche') && params.get('niche') !== 'master');
  return isDemoUrl ? 'demo' : 'client-template';
}
window.waAiGetSubdomain = waAiGetSubdomain;
function getClientSubdomain() { return waAiGetSubdomain(); }
window.getClientSubdomain = getClientSubdomain;

/* Niche resolution for payment URLs (law 2026-08-19: was undefined — the
   payment-link picker crashed with a ReferenceError on every catalog item
   without a pre-minted gateway URL). */
function waAiGetNiche() {
  if (waAiConfig && waAiConfig.niche) return waAiConfig.niche;
  if (window.CLIENT_CONFIG && window.CLIENT_CONFIG.niche) return window.CLIENT_CONFIG.niche;
  var el = document.querySelector('[data-niche]');
  if (el && el.getAttribute('data-niche')) return el.getAttribute('data-niche');
  return '';
}

function dashAuthHeaders() {
  var t = null;
  try {
    t = localStorage.getItem('dash_token') || sessionStorage.getItem('dash_token');
    if (!t) {
      var sessStr = localStorage.getItem('dash_session') || sessionStorage.getItem('dash_session');
      if (sessStr) {
        var sessObj = JSON.parse(sessStr);
        if (sessObj && sessObj.token) {
          t = sessObj.token;
          try { localStorage.setItem('dash_token', t); } catch (e) {}
        }
      }
    }
  } catch (e) {}
  return t ? { 'Authorization': 'Bearer ' + t } : {};
}

/* A 401 means the session was revoked or expired (offboarding / tokenVersion bump).
   Clear the local session and bounce to the login screen for THIS shell:
   deployed surfaces (master subdomain + client capsules) serve /login at the
   root; local dev serves /ai-agent/login. */
function handleAuthFailure(r) {
  if (r && r.status === 401) {
    var isLocal = (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');
    if (isLocal) return r;
    if (window.__SANDBOXED_DEMO__ || (typeof isDemoMode === 'function' && isDemoMode()) || DEMO_MODE) return r;
    try {
      var sess = window.__dash_session_data;
      if (isLocal && sess && sess.token && sess.token.startsWith('master_dev_token_')) return r;
    } catch (e) {}
    try { localStorage.removeItem('dash_token'); } catch (e) {}
    try { localStorage.removeItem('dash_session'); } catch (e) {}
    try { sessionStorage.removeItem('dash_session'); } catch (e) {}
    try { sessionStorage.removeItem('dash_token'); } catch (e) {}
    var path = window.location.pathname || '';
    var target = dashBase() + '/login?reason=expired';
    if (path.includes('/templates/')) target = 'login.html?reason=expired';
    window.location.replace(target);
  }
  return r;
}

function apiGet(path) {
  var sub = waAiGetSubdomain();
  if (path.indexOf('subdomain=') === -1) {
    var sep = path.indexOf('?') === -1 ? '?' : '&';
    path = path + sep + 'subdomain=' + encodeURIComponent(sub);
  }
  var isLocal = (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');
  return fetch(path, { headers: dashAuthHeaders() })
    .then(function (r) {
      handleAuthFailure(r);
      if (!r.ok) {
        if (isLocal || window.__SANDBOXED_DEMO__ || DEMO_MODE) {
          return { success: true, localFallback: true };
        }
        return { success: false, status: r.status };
      }
      return r.json().catch(function () { return { success: false }; });
    })
    .catch(function (err) {
      if (isLocal || window.__SANDBOXED_DEMO__ || DEMO_MODE) {
        return { success: true, localFallback: true };
      }
      return { success: false, error: err && err.message };
    });
}
function apiPost(path, body, method) {
  body = body || {};
  if (!body.subdomain) body.subdomain = waAiGetSubdomain();
  var headers = dashAuthHeaders();
  headers['Content-Type'] = 'application/json';
  var isLocal = (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');
  return fetch(path, {
    method: method || 'POST',
    headers: headers,
    body: JSON.stringify(body)
  })
    .then(function (r) {
      handleAuthFailure(r);
      if (!r.ok) return { success: isLocal || window.__SANDBOXED_DEMO__ || DEMO_MODE, status: r.status };
      return r.json().catch(function () { return { success: true }; });
    })
    .catch(function (err) {
      return { success: isLocal || window.__SANDBOXED_DEMO__ || DEMO_MODE, error: err && err.message };
    });
}

/* ============================================================
   PANEL SWITCHING + SIDEBAR
   ============================================================ */
var currentPanel = 'overview';
function switchPanel(id, navEl, keepSidebarOpen) {
  currentPanel = id;
  if (id === 'stations') {
    switchPanel('bookings', null, keepSidebarOpen);
    if (typeof switchBookingsSubTab === 'function') switchBookingsSubTab('stations');
    return;
  }
  if (id === 'inbox') id = 'live-chat';
  if (id === 'receptionist') id = 'ai-receptionist';
  if (id === 'employees') id = 'staff';
  if (id === 'invoices') id = 'payments';
  if (id === 'website') id = 'studio';
  if (id === 'customers') id = 'passes';

  // AI Agent Dashboard guard: if Website Studio was sliced out, fallback cleanly to overview
  if (id === 'studio' && !$('panel-studio')) {
    id = 'overview';
    navEl = $('nav-overview');
  }

  // Cybersecurity: RBAC & Forced Browsing Defense (Anthropic Cybersecurity Skills & PayloadsAllTheThings)
  var currentRole = typeof getCurrentRole === 'function' ? getCurrentRole() : 'owner';
  var isOwner = (currentRole === 'owner');

  if (id === 'staff' && !isOwner) {
    if (typeof showToast === 'function') {
      showToast('Access Denied: Team Access is restricted to Primary Owner.', 'error');
    }
    id = 'overview';
    navEl = $('nav-overview');
  } else if (!isOwner && typeof getRoleAllowedSections === 'function') {
    if (id === 'settings' || id === 'studio') {
      if (typeof showToast === 'function') {
        showToast('Access Denied: Restricted section.', 'error');
      }
      id = 'overview';
      navEl = $('nav-overview');
    } else {
      var allowedSecs = getRoleAllowedSections(currentRole);
      if (allowedSecs.indexOf(id) === -1 && id !== 'overview') {
        if (typeof showToast === 'function') {
          showToast('Access Denied: You do not have permission for this section.', 'error');
        }
        id = 'overview';
        navEl = $('nav-overview');
      }
    }
  }
  // AI Agent Dashboard law: AI Receptionist is native and unconditional.
  // Leaving the business slot -> give the active niche module its teardown
  // hook (contract Section 7.5) before the container is hidden/reused.
  var current = document.querySelector('.panel.active');
  var currentId = current && current.id ? current.id.replace(/^panel-/, '') : null;
  if (currentId === 'business-module' && id !== 'business-module') {
    var prevMod = DASH_MODULE_REGISTRY[activeModuleId];
    if (prevMod && typeof prevMod.destroy === 'function') {
      try { prevMod.destroy(); } catch (e) { console.warn('[Module] destroy() failed:', e); }
    }
  }
  document.querySelectorAll('.panel').forEach(function (p) { p.classList.remove('active'); });
  document.querySelectorAll('.nav-item').forEach(function (n) { n.classList.remove('active'); });

  // Accordion sub-navigation handling (law 2026-09-04)
  var targetGroup = $('nav-group-' + id) || (navEl ? navEl.closest('.nav-group') : null);
  document.querySelectorAll('.nav-group').forEach(function (g) {
    if (g === targetGroup) {
      g.classList.add('expanded');
    } else {
      g.classList.remove('expanded');
    }
  });

  var panel = $('panel-' + id) || $('view-' + id) || document.querySelector('.panel[id="view-' + id + '"]') || document.querySelector('.panel[data-panel="' + id + '"]');
  if (panel) panel.classList.add('active');
  if (id === 'bookings' && typeof updateBookingCapacityState === 'function') {
    try {
      updateBookingCapacityState();
    } catch (e) {
      console.warn('[Dashboard] updateBookingCapacityState error:', e);
    }
  }
  if (id === 'settings' && typeof loadCourierSettings === 'function') {
    try {
      loadCourierSettings();
    } catch (e) {
      console.warn('[Dashboard] loadCourierSettings error:', e);
    }
  }
  if (id === 'live-chat') {
    document.body.classList.add('panel-live-chat-active');
  } else {
    document.body.classList.remove('panel-live-chat-active');
  }
  var contentEl = document.querySelector('.content');
  if (contentEl) {
    contentEl.classList.toggle('overview-active', id === 'overview');
  }
  if (id === 'overview') {
    document.body.classList.add('panel-overview-active');
    if (typeof renderOverviewApexSparklines === 'function') {
      setTimeout(function () { renderOverviewApexSparklines(); }, 60);
    }
  } else {
    document.body.classList.remove('panel-overview-active');
  }
  if (navEl) {
    navEl.classList.add('active');
  } else {
    var auto = document.querySelector('.nav-item[data-panel="' + id + '"]');
    if (auto) auto.classList.add('active');
  }
  var titleEl = $('topbar-title');
  if (titleEl) {
    if (id === 'bookings') {
      var savedSubTab = 'stations';
      try { savedSubTab = sessionStorage.getItem('codaxiom-dash-bk-subtab') || 'stations'; } catch(e) {}
      titleEl.textContent = (savedSubTab === 'stations') ? 'Stations' : 'Schedule';
    } else {
      var nav = document.querySelector('.nav-item[data-panel="' + id + '"] .nav-label');
      titleEl.textContent = nav ? nav.textContent.trim() : id;
    }
  }
  if (!keepSidebarOpen) {
    closeSidebar();
  }
  try {
    onPanelActivated(id);
  } catch (e) {
    console.warn('[Dashboard] onPanelActivated error:', e);
  }
}
window.switchPanel = switchPanel;

function toggleNavGroup(panelId, el, evt) {
  if (evt) evt.stopPropagation();
  var group = $('nav-group-' + panelId) || (el ? el.closest('.nav-group') : null);
  var isExpanded = group && group.classList.contains('expanded');
  var isCurrentPanelActive = el && el.classList.contains('active');

  // Accordion rule: collapse all other groups
  document.querySelectorAll('.nav-group').forEach(function (g) {
    if (g !== group) g.classList.remove('expanded');
  });

  if (group) {
    if (isCurrentPanelActive && isExpanded) {
      group.classList.remove('expanded');
    } else {
      group.classList.add('expanded');
    }
  }
  switchPanel(panelId, el, true);
}
window.toggleNavGroup = toggleNavGroup;

function updateSubNavActive(activeEl) {
  if (!activeEl) return;
  var parentGroup = activeEl.closest('.nav-group');
  if (parentGroup) {
    parentGroup.querySelectorAll('.nav-sub-item').forEach(function (s) {
      s.classList.remove('active');
    });
  } else {
    document.querySelectorAll('.nav-sub-item').forEach(function (s) {
      s.classList.remove('active');
    });
  }
  activeEl.classList.add('active');
}
