/* Prompt Presets & Character Counter */
var PROMPT_PRESETS = {
  friendly_receptionist: "You are a warm, empathetic, and professional AI Receptionist. Greet customers politely, answer inquiries accurately using our catalog pricing, and assist them with booking appointments smoothly.",
  high_end_concierge: "You are an elite, polished customer concierge. Provide sophisticated, high-touch responses. Emphasize quality, premium offerings, and tailored service options without rushing the customer.",
  strict_booking: "You are a conversion-focused booking assistant. Respond directly to customer questions with concise details, then prompt them to schedule an appointment or complete their order using our payment links.",
  faq_direct: "You are a direct customer care specialist. Answer questions strictly according to our published FAQs and catalog list prices. Do not speculate or offer unauthorized custom discounts."
};

function injectPromptPreset(templateKey) {
  var promptEl = $('ai-prompt');
  if (!promptEl) return;
  var presetText = PROMPT_PRESETS[templateKey];
  if (!presetText) return;
  promptEl.value = presetText;
  updatePromptCharCounter();
  if (typeof showToast === 'function') {
    showToast(t('persona.presetInjected', 'Prompt preset applied successfully'), 'info');
  }
}
window.injectPromptPreset = injectPromptPreset;

function updatePromptCharCounter() {
  var promptEl = $('ai-prompt');
  var counterEl = $('prompt-char-count');
  if (!promptEl || !counterEl) return;
  var len = promptEl.value.length;
  var max = 2000;
  counterEl.textContent = len + ' / ' + max;
  if (len > 1900) {
    counterEl.style.color = 'var(--status-red)';
  } else if (len > 1500) {
    counterEl.style.color = 'var(--status-amber)';
  } else {
    counterEl.style.color = 'var(--text-muted)';
  }
}
window.updatePromptCharCounter = updatePromptCharCounter;

function updateTemperatureLabel() {
  var slider = $('ai-temperature-slider');
  var label = $('ai-temperature-val') || $('ai-temp-val') || $('ai-temp-display');
  if (!slider) return;
  var val = parseFloat(slider.value).toFixed(2);
  var text = '';
  var badgeClass = '';
  if (val < 0.30) {
    text = val + ' (Precise & Factual)';
    badgeClass = 'text-teal';
  } else if (val < 0.70) {
    text = val + ' (Balanced & Natural)';
    badgeClass = 'text-green';
  } else {
    text = val + ' (Creative & Expressive)';
    badgeClass = 'text-amber';
  }
  var labelPrimary = $('ai-temperature-val');
  if (labelPrimary) {
    labelPrimary.innerHTML = '<span class="' + badgeClass + '" style="font-weight:600;"><i class="fa-solid fa-sliders"></i> ' + text + '</span>';
  }
  var labelAlt = $('ai-temp-val') || $('ai-temp-display');
  if (labelAlt && labelAlt !== labelPrimary) {
    labelAlt.textContent = val;
  }
  if (waAiConfig && waAiConfig.aiPersona) {
    waAiConfig.aiPersona.temperature = parseFloat(val);
  }
}
window.updateTemperatureLabel = updateTemperatureLabel;

