function getCurrencySymbol(cur) {
  var c = (cur || (typeof defaultCurrency === 'function' ? defaultCurrency() : 'IDR') || 'IDR').toUpperCase();
  if (c === 'IDR') return 'Rp';
  if (c === 'USD') return '$';
  if (c === 'EUR') return '€';
  if (c === 'GBP') return '£';
  if (c === 'SGD') return 'S$';
  if (c === 'AUD') return 'A$';
  if (c === 'MYR') return 'RM';
  if (c === 'CAD') return 'C$';
  if (c === 'JPY') return '¥';
  if (c === 'NZD') return 'NZ$';
  if (c === 'CHF') return 'CHF';
  if (c === 'HKD') return 'HK$';
  if (c === 'AED') return 'AED';
  if (c === 'THB') return '฿';
  if (c === 'BRL') return 'R$';
  if (c === 'MXN') return 'MX$';
  if (c === 'PLN') return 'zł';
  if (c === 'SEK' || c === 'NOK' || c === 'DKK') return 'kr';
  if (c === 'INR') return '₹';
  if (c === 'ZAR') return 'R';
  return c;
}
window.getCurrencySymbol = getCurrencySymbol;

function parsePromoDiscountValue(val, type, currency) {
  if (val == null || String(val).trim() === '') return 0;
  var s = String(val).trim();
  if (type === 'percent') {
    var num = parseFloat(s.replace(/[^0-9.]/g, ''));
    if (isNaN(num)) return 0;
    return Math.min(100, Math.max(0, Math.round(num)));
  }
  var cur = (currency || (typeof defaultCurrency === 'function' ? defaultCurrency() : 'IDR') || 'IDR').toUpperCase();
  if (cur === 'IDR') {
    var clean = s.replace(/[^0-9]/g, '');
    var n = parseInt(clean, 10);
    return isNaN(n) ? 0 : n;
  } else {
    var num = parseFloat(s.replace(/[^0-9.]/g, ''));
    return isNaN(num) ? 0 : num;
  }
}
window.parsePromoDiscountValue = parsePromoDiscountValue;

function updatePromoDiscountTypeUI() {
  var cur = typeof defaultCurrency === 'function' ? defaultCurrency() : 'IDR';
  var sym = getCurrencySymbol(cur);
  var optFixed = $('promo-opt-fixed');
  if (optFixed) {
    optFixed.textContent = 'Fixed Amount (' + sym + ')';
  }
  var typeSel = $('promo-discount-type');
  var type = typeSel ? typeSel.value : 'percent';
  var addonEl = $('promo-discount-addon');
  var suffixEl = $('promo-discount-suffix');
  var inputEl = $('promo-discount-input');

  if (addonEl) {
    addonEl.textContent = sym;
    addonEl.style.display = type === 'fixed' ? 'inline' : 'none';
  }
  if (suffixEl) {
    suffixEl.style.display = type === 'percent' ? 'inline' : 'none';
  }
  if (inputEl) {
    if (type === 'percent') {
      inputEl.placeholder = '20';
      inputEl.style.paddingLeft = '0.75rem';
      inputEl.style.paddingRight = '2rem';
    } else {
      inputEl.placeholder = cur === 'IDR' ? '50.000' : '15.00';
      inputEl.style.paddingLeft = '2.25rem';
      inputEl.style.paddingRight = '0.75rem';
    }
  }
  updatePromoCalcPreview();
}
window.updatePromoDiscountTypeUI = updatePromoDiscountTypeUI;

function onPromoDiscountTypeChange() {
  updatePromoDiscountTypeUI();
}
window.onPromoDiscountTypeChange = onPromoDiscountTypeChange;

function onPromoDiscountInput() {
  updatePromoCalcPreview();
}
window.onPromoDiscountInput = onPromoDiscountInput;

function updatePromoCalcPreview() {
  var previewEl = $('promo-calc-result');
  if (!previewEl) return;
  var cur = typeof defaultCurrency === 'function' ? defaultCurrency() : 'IDR';
  var typeSel = $('promo-discount-type');
  var type = typeSel ? typeSel.value : 'percent';
  var discInput = $('promo-discount-input');
  var rawDisc = discInput ? discInput.value : '';
  var discVal = parsePromoDiscountValue(rawDisc, type, cur);

  var targetSel = $('promo-target-item-select');
  var targetVal = targetSel ? targetSel.value : 'all';

  var basePrice = 0;
  var label = 'Storewide Benchmark';

  if (targetVal === 'all_bundles') {
    label = 'Bundle Combos';
    var sampleBundle = (typeof catalogState !== 'undefined' && Array.isArray(catalogState))
      ? catalogState.find(function (it) { return it.type === 'package' && (typeof isNumericPrice === 'function' ? isNumericPrice(it.price) : it.price > 0); })
      : null;
    if (sampleBundle) {
      basePrice = (typeof numericPrice === 'function' ? numericPrice(sampleBundle.price) : parseFloat(sampleBundle.price)) || 0;
      label = (typeof catItemName === 'function') ? catItemName(sampleBundle) : (sampleBundle.name || 'Bundle Combo');
    } else {
      basePrice = cur === 'IDR' ? 100000 : 50;
    }
  } else if (targetVal && targetVal !== 'all' && typeof catalogState !== 'undefined' && Array.isArray(catalogState)) {
    var matched = catalogState.find(function (it) { return it.id === targetVal; });
    if (matched) {
      var mName = (typeof catItemName === 'function') ? catItemName(matched) : (matched.name || 'Catalog Item');
      label = (matched.type === 'package' ? '[Bundle] ' : '') + mName;
      if (typeof isNumericPrice === 'function' ? isNumericPrice(matched.price) : matched.price > 0) {
        basePrice = (typeof numericPrice === 'function' ? numericPrice(matched.price) : parseFloat(matched.price)) || 0;
      }
    }
  }

  if (basePrice <= 0) {
    basePrice = cur === 'IDR' ? 100000 : 50;
  }

  var finalPrice = basePrice;
  if (type === 'percent') {
    finalPrice = Math.max(1, Math.round(basePrice * (1 - (discVal / 100))));
  } else {
    finalPrice = Math.max(1, Math.round(basePrice - discVal));
  }
  var savings = Math.max(0, basePrice - finalPrice);

  var fmt = typeof fmtPrice === 'function' ? fmtPrice : function(p, c) { return c + ' ' + p; };
  previewEl.textContent = label + ': ' + fmt(basePrice, cur) + ' -> ' + fmt(finalPrice, cur) + ' (Saves ' + fmt(savings, cur) + ')';
}
window.updatePromoCalcPreview = updatePromoCalcPreview;

function addPromoDirectivePreset(presetType) {
  var textarea = $('wa-promo-rules');
  if (!textarea) return;
  var cur = typeof defaultCurrency === 'function' ? defaultCurrency() : 'IDR';
  var fmt = typeof fmtPrice === 'function' ? fmtPrice : function(p, c) { return c + ' ' + p; };
  var snippet = '';
  if (presetType === 'min_spend') {
    var minAmt = fmt(cur === 'IDR' ? 100000 : 50, cur);
    snippet = 'Minimum spend of ' + minAmt + ' required to qualify.';
  } else if (presetType === 'first_time') {
    snippet = 'Valid exclusively for first-time customers on their first purchase.';
  } else if (presetType === 'weekend') {
    snippet = 'Available exclusively for weekend bookings and orders (Saturday & Sunday).';
  }
  if (!snippet) return;
  var curr = textarea.value.trim();
  if (curr && !curr.endsWith('.')) curr += '.';
  textarea.value = (curr ? curr + ' ' : '') + snippet;
  textarea.focus();
}
window.addPromoDirectivePreset = addPromoDirectivePreset;

