function renderPromoList() {
  var container = $('promo-list-container');
  if (!container) return;
  var c = waAiConfig || {};
  var promos = Array.isArray(c.promosList) ? c.promosList : [];

  var promoStat = $('cat-stat-promos');
  if (promoStat) promoStat.textContent = promos.length;

  var countBadge = $('cat-promo-count-badge');
  if (countBadge) {
    countBadge.textContent = promos.length + (promos.length === 1 ? ' Campaign' : ' Campaigns');
  }

  if (promos.length === 0) {
    container.innerHTML = emptyState(
      '<i class="fa-solid fa-tags"></i>',
      t('catalog.noPromoTitle', 'No Promotional Campaigns Active'),
      t('catalog.noPromoDesc', 'Set up percentage or fixed-amount discount campaigns for your catalog using the "Add Promo" button above.')
    );
    return;
  }

  var filteredPromos = promos;
  if (currentPromoSearchQuery) {
    filteredPromos = filteredPromos.filter(function (p) {
      var codeMatch = (p.code || '').toLowerCase().indexOf(currentPromoSearchQuery) !== -1;
      var discMatch = String(p.discount || '').toLowerCase().indexOf(currentPromoSearchQuery) !== -1;
      var rulesMatch = (p.rules || '').toLowerCase().indexOf(currentPromoSearchQuery) !== -1;
      return codeMatch || discMatch || rulesMatch;
    });
  }

  if (filteredPromos.length === 0) {
    container.innerHTML = emptyState(
      '<i class="fa-solid fa-magnifying-glass"></i>',
      'No Promo Codes Found',
      'No promotional campaigns matching "' + esc(currentPromoSearchQuery) + '" were found.'
    );
    return;
  }

  var cur = typeof defaultCurrency === 'function' ? defaultCurrency() : 'IDR';
  var fmt = typeof fmtPrice === 'function' ? fmtPrice : function(p, c) { return c + ' ' + p; };

  var html = '';
  filteredPromos.forEach(function (item) {
    var targetLabel = 'All Catalog Items (Storewide)';
    if (item.targetItem === 'all_bundles') {
      targetLabel = 'All Bundles &amp; Combos Only';
    } else if (item.targetItem && item.targetItem !== 'all' && typeof catalogState !== 'undefined') {
      var matched = catalogState.find(function (it) { return it.id === item.targetItem; });
      if (matched) {
        var mName = (typeof catItemName === 'function')
          ? catItemName(matched)
          : (typeof matched.name === 'string' ? matched.name : ((matched.name && (matched.name.en || matched.name.id)) || matched.id || 'Untitled item'));
        var mSku = (matched.sku && String(matched.sku).trim() !== '') ? ' [' + String(matched.sku).trim() + ']' : '';
        targetLabel = (matched.type === 'package' ? '[Bundle] ' : '') + mName + mSku;
      }
    }

    var isPaused = item.active === false;
    var expiryPill = '<span class="pill pill-green"><i class="fa-solid fa-circle-check"></i> Active</span>';

    if (isPaused) {
      expiryPill = '<span class="pill pill-neutral" style="opacity:0.75;"><i class="fa-solid fa-pause"></i> Paused</span>';
    } else if (item.expiryDate) {
      var expTime = new Date(item.expiryDate).getTime();
      var now = Date.now();
      if (!isNaN(expTime) && expTime < now) {
        expiryPill = '<span class="pill pill-red"><i class="fa-solid fa-triangle-exclamation"></i> Expired (' + esc(item.expiryDate) + ')</span>';
      } else {
        expiryPill = '<span class="pill pill-green"><i class="fa-solid fa-calendar-check"></i> Valid until ' + esc(item.expiryDate) + '</span>';
      }
    }

    var discDisplay = '';
    if (item.type === 'percent') {
      var pNum = parseFloat(String(item.discount || '').replace(/[^0-9.]/g, '')) || 0;
      discDisplay = pNum + '% OFF';
    } else {
      var fNum = parsePromoDiscountValue(item.discount, 'fixed', cur);
      discDisplay = fmt(fNum, cur) + ' OFF';
    }

    html += 
      '<div class="dash-card promo-card" style="' + (isPaused ? 'opacity:0.65;' : '') + '">' +
        '<div class="promo-card-top">' +
          '<div class="promo-card-badges">' +
            '<button type="button" class="promo-code-btn" onclick="copyPromoCode(\'' + esc(item.code || 'PROMO') + '\')" title="Click to copy promo code">' +
              '<i class="fa-solid fa-ticket text-teal"></i> <span>' + esc(item.code || 'PROMO') + '</span> ' +
              '<i class="fa-solid fa-copy" style="font-size:0.75rem;opacity:0.6;margin-left:0.25rem;"></i>' +
            '</button>' +
            '<span class="pill pill-green font-mono promo-discount-pill">' + esc(discDisplay) + '</span>' +
          '</div>' +
          '<div class="promo-card-meta">' +
            expiryPill +
            '<button type="button" class="btn-dash btn-outline btn-xs" onclick="togglePromoActive(\'' + esc(item.id) + '\')" title="' + (isPaused ? 'Resume Promo' : 'Pause Promo') + '" aria-label="Toggle promo active state"><i class="fa-solid ' + (isPaused ? 'fa-play' : 'fa-pause') + '"></i></button>' +
            '<button type="button" class="btn-dash btn-outline btn-xs promo-edit-btn" onclick="showPromoEditForm(\'' + esc(item.id) + '\')" title="Edit Promo" aria-label="Edit promo ' + esc(item.code || 'PROMO') + '"><i class="fa-solid fa-pen-to-square"></i></button>' +
            '<button type="button" class="btn-dash btn-outline btn-xs btn-danger-soft promo-delete-btn" onclick="deletePromoCode(\'' + esc(item.id) + '\')" title="Delete Promo" aria-label="Delete promo ' + esc(item.code || 'PROMO') + '"><i class="fa-solid fa-trash"></i></button>' +
          '</div>' +
        '</div>' +
        '<div class="promo-card-target">' +
          '<i class="fa-solid fa-bullseye text-teal"></i> Applies to: <strong>' + esc(targetLabel) + '</strong>' +
        '</div>' +
        (item.rules ? '<div class="promo-card-rules"><i class="fa-solid fa-robot text-teal"></i> ' + esc(item.rules) + '</div>' : '') +
      '</div>';
  });
  container.innerHTML = html;
}
window.renderPromoList = renderPromoList;

function savePromoCode() {
  var codeEl = $('promo-code-input');
  var discEl = $('promo-discount-input');
  var typeEl = $('promo-discount-type');
  var targetEl = $('promo-target-item-select');
  var startEl = $('promo-start-date-input');
  var expEl = $('promo-expiry-date-input');
  var rulesEl = $('wa-promo-rules');

  var code = codeEl ? codeEl.value.trim().toUpperCase() : '';
  var rawDisc = discEl ? discEl.value.trim() : '';
  var type = typeEl ? typeEl.value : 'percent';
  var cur = typeof defaultCurrency === 'function' ? defaultCurrency() : 'IDR';

  if (!code) {
    if (typeof showToast === 'function') showToast('Please enter a promo code', 'error');
    return;
  }

  var discVal = parsePromoDiscountValue(rawDisc, type, cur);
  if (discVal <= 0) {
    if (typeof showToast === 'function') showToast('Please enter a valid discount value greater than zero', 'error');
    return;
  }

  var discSaved = String(discVal);

  if (!waAiConfig) waAiConfig = {};
  if (!waAiConfig.promosList) waAiConfig.promosList = [];

  var promoRecord = {
    id: activeEditingPromoId || ('promo-' + Date.now()),
    code: code,
    discount: discSaved,
    type: type,
    targetItem: targetEl ? targetEl.value : 'all',
    startDate: startEl ? startEl.value : '',
    expiryDate: expEl ? expEl.value : '',
    rules: rulesEl ? rulesEl.value.trim() : '',
    active: true
  };

  if (activeEditingPromoId) {
    var existing = waAiConfig.promosList.find(function (p) { return p.id === activeEditingPromoId; });
    if (existing && existing.active !== undefined) promoRecord.active = existing.active;
    var idx = waAiConfig.promosList.findIndex(function (p) { return p.id === activeEditingPromoId; });
    if (idx !== -1) waAiConfig.promosList[idx] = promoRecord;
    else waAiConfig.promosList.unshift(promoRecord);
  } else {
    waAiConfig.promosList.unshift(promoRecord);
  }

  waAiConfig.promoCode = code;
  waAiConfig.promoDiscount = discSaved;
  waAiConfig.promoRules = promoRecord.rules;

  if (typeof waAiSaveConfig === 'function') waAiSaveConfig(true);
  hidePromoEditorDrawer();
  renderPromoList();
  if (typeof showToast === 'function') showToast('Promo code saved successfully', 'success');
}
window.savePromoCode = savePromoCode;

function deletePromoCode(promoId) {
  if (!waAiConfig || !waAiConfig.promosList) return;
  waAiConfig.promosList = waAiConfig.promosList.filter(function (p) { return p.id !== promoId; });
  if (waAiConfig.promosList.length === 0) {
    waAiConfig.promoCode = '';
    waAiConfig.promoDiscount = '';
    waAiConfig.promoRules = '';
  }
  if (typeof waAiSaveConfig === 'function') waAiSaveConfig(true);
  renderPromoList();
  if (typeof showToast === 'function') showToast('Promo code deleted', 'info');
}
window.deletePromoCode = deletePromoCode;

/* Structured Visual FAQ Cards CRUD & Markdown Mirror Sync */
var currentFaqCategoryFilter = 'All';
var currentFaqSearchQuery = '';

function getFaqCategoryIcon(category) {
  var c = (category || '').toLowerCase();
  if (c === 'pricing') return '<i class="fa-solid fa-tag text-teal"></i>';
  if (c === 'hours') return '<i class="fa-solid fa-clock text-teal"></i>';
  if (c === 'location') return '<i class="fa-solid fa-location-dot text-teal"></i>';
  if (c === 'services') return '<i class="fa-solid fa-concierge-bell text-teal"></i>';
  if (c === 'cancellation') return '<i class="fa-solid fa-ban text-amber"></i>';
  return '<i class="fa-solid fa-folder text-teal"></i>';
}
window.getFaqCategoryIcon = getFaqCategoryIcon;

function parseFaqsFromMarkdown(mdText) {
  if (!mdText || !mdText.trim()) return [];
  var blocks = mdText.split(/###\s+/).filter(Boolean);
  return blocks.map(function (block, idx) {
    var lines = block.trim().split('\n');
    var qLine = lines[0] ? lines[0].replace(/^Q:\s*/, '').trim() : '';
    var aLines = lines.slice(1).map(function (l) { return l.replace(/^A:\s*/, ''); }).join('\n').trim();
    var catMatch = qLine.match(/^\[(.*?)\]\s*(.*)$/);
    var category = catMatch ? catMatch[1] : 'General';
    var question = catMatch ? catMatch[2] : qLine;
    return {
      id: 'faq-' + (idx + 1),
      category: category,
      question: question,
      answer: aLines
    };
  });
}

function serializeFaqsToMarkdown(faqArray) {
  if (!faqArray || !faqArray.length) return '';
  return faqArray.map(function (item) {
    var prefix = item.category && item.category !== 'General' ? '[' + item.category + '] ' : '';
    return '### Q: ' + prefix + item.question + '\nA: ' + item.answer;
  }).join('\n\n');
}

function renderFaqsList(categoryFilter, searchQuery) {
  var container = $('faq-list-container');
  if (!container) return;
  var rawFaqs = $('wa-ai-faqs') ? $('wa-ai-faqs').value : (waAiConfig ? waAiConfig.faqs : '');
  var faqs = parseFaqsFromMarkdown(rawFaqs);

  var q = searchQuery !== undefined ? searchQuery : (currentFaqSearchQuery || '');
  var filtered = faqs.filter(function (item) {
    if (!q) return true;
    var query = q.toLowerCase();
    return item.question.toLowerCase().indexOf(query) !== -1 || item.answer.toLowerCase().indexOf(query) !== -1;
  });

  if (!filtered.length) {
    container.innerHTML = 
      '<div class="faq-empty-state">' +
        '<div class="faq-empty-icon"><i class="fa-solid fa-circle-question text-teal"></i></div>' +
        '<div class="faq-empty-title">' + (q ? 'No FAQs Match Search' : 'No Business FAQs Added Yet') + '</div>' +
        '<div class="faq-empty-desc">' + (q ? 'No FAQs match the search query "' + esc(q) + '".' : 'Add common customer questions (refunds, cancellations, parking, policies) so your AI Receptionist answers with exact facts instead of guessing.') + '</div>' +
        (q ? '' : '<button type="button" class="btn-dash btn-accent btn-sm" onclick="showFaqAddForm()"><i class="fa-solid fa-plus"></i> Add First FAQ</button>') +
      '</div>';
    return;
  }

  var html = '<div class="faq-cards-grid">';
  filtered.forEach(function (item) {
    html += 
      '<div class="faq-bento-card">' +
        '<div class="faq-card-head">' +
          '<div class="faq-q-badge"><i class="fa-solid fa-question"></i></div>' +
          '<div class="faq-q-text">' + esc(item.question) + '</div>' +
          '<div class="faq-card-actions">' +
            '<button type="button" class="btn-icon-ghost" onclick="editFaqCard(\'' + item.id + '\')" title="Edit FAQ"><i class="fa-solid fa-pen-to-square"></i></button>' +
            '<button type="button" class="btn-icon-ghost btn-delete" onclick="deleteFaqCard(\'' + item.id + '\')" title="Delete FAQ"><i class="fa-solid fa-trash"></i></button>' +
          '</div>' +
        '</div>' +
        '<div class="faq-card-body">' +
          '<div class="faq-a-badge"><i class="fa-solid fa-reply text-teal"></i></div>' +
          '<div class="faq-a-text">' + esc(item.answer) + '</div>' +
        '</div>' +
      '</div>';
  });
  html += '</div>';
  container.innerHTML = html;
}
window.renderFaqsList = renderFaqsList;

var activeEditingFaqId = null;

function showFaqAddForm() {
  activeEditingFaqId = null;
  var drawer = $('faq-editor-drawer');
  if (drawer) drawer.style.display = 'block';
  if ($('faq-editor-title')) $('faq-editor-title').textContent = 'Add Question & Answer';
  if ($('faq-question-input')) $('faq-question-input').value = '';
  if ($('faq-answer-input')) $('faq-answer-input').value = '';
  if ($('faq-question-input')) $('faq-question-input').focus();
}
window.showFaqAddForm = showFaqAddForm;
window.showFaqEditorDrawer = showFaqAddForm;

function hideFaqEditorDrawer() {
  activeEditingFaqId = null;
  var drawer = $('faq-editor-drawer');
  if (drawer) drawer.style.display = 'none';
}
window.hideFaqEditorDrawer = hideFaqEditorDrawer;

function saveFaqCard() {
  var qInput = $('faq-question-input');
  var aInput = $('faq-answer-input');

  if (!qInput || !aInput) return;
  var q = qInput.value.trim();
  var a = aInput.value.trim();

  if (!q || !a) {
    if (typeof showToast === 'function') showToast(t('faqs.emptyFields', 'Please enter both a question and an answer'), 'error');
    return;
  }

  var rawFaqs = $('wa-ai-faqs') ? $('wa-ai-faqs').value : '';
  var faqs = parseFaqsFromMarkdown(rawFaqs);

  if (activeEditingFaqId) {
    var existingIdx = faqs.findIndex(function (item) { return item.id === activeEditingFaqId; });
    if (existingIdx !== -1) {
      faqs[existingIdx].question = q;
      faqs[existingIdx].answer = a;
    } else {
      faqs.unshift({
        id: 'faq-' + Date.now(),
        question: q,
        answer: a
      });
    }
  } else {
    faqs.unshift({
      id: 'faq-' + Date.now(),
      question: q,
      answer: a
    });
  }

  var newMarkdown = serializeFaqsToMarkdown(faqs);
  if ($('wa-ai-faqs')) $('wa-ai-faqs').value = newMarkdown;
  if (waAiConfig) waAiConfig.faqs = newMarkdown;

  qInput.value = '';
  aInput.value = '';
  hideFaqEditorDrawer();

  renderFaqsList();
  if (typeof waAiSaveConfig === 'function') waAiSaveConfig();
  if (typeof showToast === 'function') showToast(t('faqs.added', 'FAQ saved successfully'), 'success');
}
window.saveFaqCard = saveFaqCard;

function deleteFaqCard(faqId) {
  var rawFaqs = $('wa-ai-faqs') ? $('wa-ai-faqs').value : '';
  var faqs = parseFaqsFromMarkdown(rawFaqs);
  
  var updated = faqs.filter(function (item) { return item.id !== faqId; });
  var newMarkdown = serializeFaqsToMarkdown(updated);
  
  if ($('wa-ai-faqs')) $('wa-ai-faqs').value = newMarkdown;
  if (waAiConfig) waAiConfig.faqs = newMarkdown;
  renderFaqsList();
  if (typeof waAiSaveConfig === 'function') waAiSaveConfig();
  if (typeof showToast === 'function') showToast(t('faqs.deleted', 'FAQ removed'), 'info');
}
window.deleteFaqCard = deleteFaqCard;

function editFaqCard(faqId) {
  var rawFaqs = $('wa-ai-faqs') ? $('wa-ai-faqs').value : '';
  var faqs = parseFaqsFromMarkdown(rawFaqs);
  var target = faqs.find(function (item) { return item.id === faqId; });
  if (!target) return;

  activeEditingFaqId = faqId;
  var drawer = $('faq-editor-drawer');
  if (drawer) drawer.style.display = 'block';
  if ($('faq-editor-title')) $('faq-editor-title').textContent = 'Edit Question & Answer';
  if ($('faq-question-input')) {
    $('faq-question-input').value = target.question;
    $('faq-question-input').focus();
  }
  if ($('faq-answer-input')) $('faq-answer-input').value = target.answer;
}
window.editFaqCard = editFaqCard;

function filterFaqsList(query) {
  renderFaqsList(null, query);
}
window.filterFaqsList = filterFaqsList;

function toggleFaqMarkdownMirror() {}
window.toggleFaqMarkdownMirror = toggleFaqMarkdownMirror;

function syncMarkdownToFaqCards() {
  renderFaqsList();
}
window.syncMarkdownToFaqCards = syncMarkdownToFaqCards;

function formatFileSize(bytes) {
  if (bytes < 1024) return bytes + ' B';
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

function initDocDropzone() {
  var dz = $('doc-dropzone');
  if (!dz || dz.hasAttribute('data-dz-bound')) return;
  dz.setAttribute('data-dz-bound', 'true');
  dz.addEventListener('dragover', function (e) {
    e.preventDefault();
    dz.style.borderColor = 'var(--accent)';
    dz.style.background = 'var(--accent-soft)';
  });
  dz.addEventListener('dragleave', function (e) {
    e.preventDefault();
    dz.style.borderColor = 'var(--border-color)';
    dz.style.background = 'var(--bg-input)';
  });
  dz.addEventListener('drop', function (e) {
    e.preventDefault();
    dz.style.borderColor = 'var(--border-color)';
    dz.style.background = 'var(--bg-input)';
    if (e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files.length) {
      handleDocFileUpload({ target: { files: e.dataTransfer.files } });
    }
  });
}
window.initDocDropzone = initDocDropzone;

var _isDocUploading = false;

function handleDocFileUpload(ev) {
  var files = ev.target && ev.target.files;
  if (!files || !files.length) return;
  if (_isDocUploading) return;

  if (waAiConfig && Array.isArray(waAiConfig.docList) && waAiConfig.docList.length >= 25) {
    if (typeof showToast === 'function') showToast('Maximum limit of 25 PDF documents reached. Please delete an older document before uploading a new one.', 'error');
    if (ev.target) ev.target.value = '';
    return;
  }

  var file = files[0];
  var name = file.name;
  var ext = name.split('.').pop().toLowerCase();
  var sizeFormatted = formatFileSize(file.size);

  if (file.size > 30 * 1024 * 1024) {
    if (typeof showToast === 'function') showToast('File size exceeds 30MB limit (' + sizeFormatted + '). Please choose a smaller PDF.', 'error');
    if (ev.target) ev.target.value = '';
    return;
  }

  if (ext !== 'pdf') {
    if (typeof showToast === 'function') showToast('Only PDF documents (.pdf) are supported', 'error');
    if (ev.target) ev.target.value = '';
    return;
  }

  _isDocUploading = true;
  if (typeof showToast === 'function') showToast('Uploading PDF document...', 'info');

  var reader = new FileReader();
  reader.onload = function (e) {
    var dataUrl = e.target.result || '';
    var base64Data = dataUrl.split(',')[1] || dataUrl;
    var sub = waAiGetSubdomain();
    var isFirstBrochure = !(waAiConfig && waAiConfig.pdfBrochureUrl);

    apiPost('/api/admin/client-assets/upload-pdf', {
      subdomain: sub,
      fileName: name,
      base64Data: base64Data,
      setPrimaryBrochure: isFirstBrochure
    }).then(function (res) {
      _isDocUploading = false;
      if (res && res.success) {
        addDocCardItem(
          res.name || name.replace(/\.pdf$/i, '').replace(/[_-]+/g, ' ').trim(),
          file.size,
          res.sizeFormatted || sizeFormatted,
          'pdf',
          'Price List',
          res.url,
          res.fileName || name
        );
      } else {
        // Fallback for sandboxed demo mode
        addDocCardItem(name.replace(/\.pdf$/i, '').replace(/[_-]+/g, ' ').trim(), file.size, sizeFormatted, 'pdf', 'Price List', '/assets/' + name, name);
      }
    }).catch(function () {
      _isDocUploading = false;
      addDocCardItem(name.replace(/\.pdf$/i, '').replace(/[_-]+/g, ' ').trim(), file.size, sizeFormatted, 'pdf', 'Price List', '/assets/' + name, name);
    }).then(function () {
      if (ev.target) ev.target.value = '';
    });
  };
  reader.readAsDataURL(file);
}
window.handleDocFileUpload = handleDocFileUpload;

function addDocCardItem(name, rawSize, formattedSize, fileType, category, url, fileName) {
  var c = waAiConfig || {};
  if (!Array.isArray(c.docList)) c.docList = [];

  var docId = 'doc-' + Date.now();
  var assetUrl = url || ('/assets/' + (fileName || name));
  var cleanFileName = fileName || (name.endsWith('.pdf') ? name : (name.replace(/[^a-zA-Z0-9._-]/g, '_') + '.pdf'));

  var isPrimary = c.docList.length === 0 || !c.pdfBrochureUrl;
  var newDoc = {
    id: docId,
    name: name,
    fileName: cleanFileName,
    url: assetUrl,
    size: formattedSize,
    rawSize: rawSize,
    uploadDate: new Date().toISOString().split('T')[0],
    fileType: fileType || 'pdf',
    category: category || (c.docList.length === 0 ? 'Menu' : 'Brochure'),
    description: 'Official business document. Send when customers ask for menu, pricing, or catalog.',
    isPrimary: isPrimary
  };

  if (isPrimary) {
    c.pdfBrochureUrl = assetUrl;
  }

  c.docList.push(newDoc);
  renderDocList();

  if (typeof waAiSaveConfig === 'function') waAiSaveConfig(true);
  if (typeof updateCockpitTabBadges === 'function') updateCockpitTabBadges();
  if (typeof showToast === 'function') showToast('PDF "' + name + '" uploaded & ready for WhatsApp auto-delivery!', 'success');
}
window.addDocCardItem = addDocCardItem;

function updateDocField(docId, field, value) {
  var c = waAiConfig || {};
  var list = c.docList || [];
  var doc = list.find(function (d) { return d.id === docId; });
  if (!doc) return;

  var val = (value || '').trim();
  doc[field] = val;
  if (field === 'name') doc.title = val;
  if (field === 'title') doc.name = val;
  if (typeof waAiSaveConfig === 'function') waAiSaveConfig(true);
}
window.updateDocField = updateDocField;

function setPrimaryBrochure(docId) {
  var c = waAiConfig || {};
  var list = c.docList || [];
  var target = list.find(function (d) { return d.id === docId; });
  if (!target) return;

  list.forEach(function (d) { d.isPrimary = (d.id === docId); });
  c.pdfBrochureUrl = target.url;

  renderDocList();
  if (typeof waAiSaveConfig === 'function') waAiSaveConfig(true);
  if (typeof showToast === 'function') showToast('"' + target.name + '" set as Primary WhatsApp Brochure!', 'success');
}
window.setPrimaryBrochure = setPrimaryBrochure;

function cleanDocDirectives() {
  // Backwards-compatible no-op
}
window.cleanDocDirectives = cleanDocDirectives;

function deleteDocCard(docId) {
  var c = waAiConfig || {};
  var list = c.docList || [];
  var target = list.find(function (d) { return d.id === docId; });
  var targetName = target ? target.name : 'Document';

  // Zero-Bloat Asset Garbage Collection:
  // Trigger physical deletion of PDF file from disk (assetsDir and vault resources)
  var targetFileName = (target && (target.fileName || (target.url && target.url.replace(/^\/?assets\//, '')))) || '';
  if (targetFileName && !targetFileName.startsWith('http://') && !targetFileName.startsWith('https://')) {
    var subdomain = (typeof waAiGetSubdomain === 'function' ? waAiGetSubdomain() : '') || '';
    if (subdomain && !demoActionBlocked()) {
      apiPost('/api/admin/client-assets/delete-pdf', {
        subdomain: subdomain,
        fileName: targetFileName,
        docId: docId
      }).catch(function (err) {
        console.warn('[Doc PDF Deletion] Non-blocking disk cleanup warning:', err);
      });
    }
  }

  c.docList = list.filter(function (d) { return d.id !== docId; });
  if (c.docList.length > 0 && (!c.pdfBrochureUrl || (target && target.url === c.pdfBrochureUrl))) {
    c.docList[0].isPrimary = true;
    c.pdfBrochureUrl = c.docList[0].url;
  } else if (c.docList.length === 0) {
    c.pdfBrochureUrl = '';
  }

  renderDocList();
  if (typeof waAiSaveConfig === 'function') waAiSaveConfig(true);
  if (typeof updateCockpitTabBadges === 'function') updateCockpitTabBadges();
  if (typeof showToast === 'function') showToast('Document "' + targetName + '" removed and deleted from disk', 'info');
}
window.deleteDocCard = deleteDocCard;

var currentDocSearchQuery = '';
var currentDocCategoryFilter = 'all';

function filterDocSearch(q) {
  currentDocSearchQuery = (q || '').trim().toLowerCase();
  renderDocList();
}
window.filterDocSearch = filterDocSearch;

function filterDocCategory(cat) {
  currentDocCategoryFilter = cat || 'all';
  renderDocList();
}
window.filterDocCategory = filterDocCategory;

function copyDocRawText() {
  var c = waAiConfig || {};
  var text = (c.docList || []).map(function (d) {
    return '• [' + (d.category || 'Document') + '] ' + d.name + ': ' + (d.description || '');
  }).join('\n');
  if (!text) {
    if (typeof showToast === 'function') showToast('No document directives to copy.', 'info');
    return;
  }
  navigator.clipboard.writeText(text).then(function () {
    if (typeof showToast === 'function') showToast('Document directives copied to clipboard!', 'success');
  }).catch(function () {
    if (typeof showToast === 'function') showToast('Failed to copy text', 'error');
  });
}
window.copyDocRawText = copyDocRawText;

function resyncDocMemory() {
  renderDocList();
  if (typeof waAiSaveConfig === 'function') waAiSaveConfig(true);
  if (typeof showToast === 'function') showToast('AI Catalog Knowledge Base re-synced', 'success');
}
window.resyncDocMemory = resyncDocMemory;

var activeViewingDocId = null;

function openDocViewModal(docId) {
  var c = waAiConfig || {};
  var list = c.docList || [];
  var matched = list.find(function (d) { return d.id === docId; });
  if (!matched) return;

  activeViewingDocId = docId;
  if ($('doc-view-modal-id')) $('doc-view-modal-id').value = docId;
  if ($('doc-view-modal-title')) $('doc-view-modal-title').textContent = matched.name;
  if ($('doc-view-modal-name')) $('doc-view-modal-name').value = matched.name;
  if ($('doc-view-modal-category')) $('doc-view-modal-category').value = matched.category || 'Price List';
  if ($('doc-view-modal-desc')) $('doc-view-modal-desc').value = matched.description || '';
  if ($('doc-view-modal-primary')) $('doc-view-modal-primary').value = matched.isPrimary ? 'true' : 'false';
  if ($('doc-view-modal-file-info')) {
    $('doc-view-modal-file-info').innerHTML = '<span class="font-mono">' + esc(matched.fileName || '') + ' (' + esc(matched.size || '') + ')</span>';
  }

  var modal = $('doc-view-modal');
  if (modal) modal.classList.add('open');
}
window.openDocViewModal = openDocViewModal;

function closeDocViewModal() {
  activeViewingDocId = null;
  var modal = $('doc-view-modal');
  if (modal) modal.classList.remove('open');
}
window.closeDocViewModal = closeDocViewModal;

function saveDocModalDetails() {
  if (!activeViewingDocId) return;
  var c = waAiConfig || {};
  var list = c.docList || [];
  var matched = list.find(function (d) { return d.id === activeViewingDocId; });
  if (!matched) return;

  var nameEl = $('doc-view-modal-name');
  var catEl = $('doc-view-modal-category');
  var descEl = $('doc-view-modal-desc');
  var primaryEl = $('doc-view-modal-primary');

  matched.name = nameEl && nameEl.value.trim() ? nameEl.value.trim() : matched.name;
  matched.category = catEl ? catEl.value : (matched.category || 'Price List');
  matched.description = descEl ? descEl.value.trim() : '';

  var wantPrimary = primaryEl && primaryEl.value === 'true';
  if (wantPrimary) {
    list.forEach(function (d) { d.isPrimary = (d.id === activeViewingDocId); });
    c.pdfBrochureUrl = matched.url;
  }

  closeDocViewModal();
  renderDocList();
  if (typeof waAiSaveConfig === 'function') waAiSaveConfig(true);
  if (typeof showToast === 'function') showToast('Document details saved', 'success');
}
window.saveDocModalDetails = saveDocModalDetails;

function renderDocList() {
  var container = $('doc-list-container');
  if (!container) return;
  var c = waAiConfig || {};
  var list = Array.isArray(c.docList) ? c.docList : [];

  // Update badge count
  var badge = $('doc-count-badge');
  if (badge) {
    badge.textContent = list.length + ' / 25 Documents';
  }

  // Dropzone visual state when capacity reached (25 docs max)
  var dropzone = $('doc-dropzone');
  if (dropzone) {
    if (list.length >= 25) {
      dropzone.style.opacity = '0.6';
      dropzone.style.pointerEvents = 'none';
      dropzone.style.cursor = 'not-allowed';
      var dropTitle = dropzone.querySelector('.doc-dropzone-title');
      if (dropTitle) dropTitle.textContent = 'Document catalog limit reached (25 / 25 PDFs)';
    } else {
      dropzone.style.opacity = '1';
      dropzone.style.pointerEvents = 'auto';
      dropzone.style.cursor = 'pointer';
      var dropTitle = dropzone.querySelector('.doc-dropzone-title');
      if (dropTitle) dropTitle.textContent = 'Click to browse or drag & drop PDF documents here';
    }
  }

  // Update search bar visibility
  var searchContainer = $('doc-search-container');
  if (searchContainer) {
    searchContainer.style.display = list.length > 0 ? 'flex' : 'none';
  }

  if (list.length === 0) {
    container.innerHTML = '<div class="empty-state" style="padding:2.5rem 1rem;text-align:center;background:var(--bg-card);border:1px dashed var(--border-color);border-radius:var(--radius-md);">' +
      '<i class="fa-solid fa-file-circle-plus text-teal" style="font-size:2.5rem;margin-bottom:0.75rem;opacity:0.8;display:block;"></i>' +
      '<div style="font-weight:600;font-size:1rem;color:var(--text-main);margin-bottom:0.25rem;">No PDF documents uploaded yet</div>' +
      '<div style="font-size:0.8125rem;color:var(--text-muted);max-width:480px;margin:0 auto;line-height:1.5;">' +
        'Upload your price lists, restaurant menus, real estate brochures, or unit floor plans above. The WhatsApp AI Receptionist reads the document title and description to intelligently deliver matching PDFs directly in customer conversations.' +
      '</div>' +
    '</div>';
    return;
  }

  var filteredList = list;
  if (currentDocSearchQuery) {
    filteredList = filteredList.filter(function (doc) {
      var nameMatch = (doc.name || '').toLowerCase().indexOf(currentDocSearchQuery) !== -1;
      var descMatch = (doc.description || '').toLowerCase().indexOf(currentDocSearchQuery) !== -1;
      var fileMatch = (doc.fileName || '').toLowerCase().indexOf(currentDocSearchQuery) !== -1;
      var catMatch = (doc.category || '').toLowerCase().indexOf(currentDocSearchQuery) !== -1;
      return nameMatch || descMatch || fileMatch || catMatch;
    });
  }

  if (filteredList.length === 0) {
    container.innerHTML = emptyState(
      '<i class="fa-solid fa-magnifying-glass"></i>',
      t('catalog.noDocMatchTitle', 'No documents match'),
      'No PDF documents matching "' + esc(currentDocSearchQuery) + '" were found.'
    );
    return;
  }

  var html = '';
  filteredList.forEach(function (doc) {
    var isPrimary = doc.isPrimary || (waAiConfig && waAiConfig.pdfBrochureUrl === doc.url);
    var categoryLabel = doc.category || 'Price List';

    var primaryBadge = isPrimary
      ? '<span class="doc-primary-badge"><i class="fa-brands fa-whatsapp"></i> Primary WhatsApp Brochure</span>'
      : '<button type="button" class="btn-dash btn-outline btn-xs" onclick="setPrimaryBrochure(\'' + esc(doc.id) + '\')" title="Send this document when customers ask for general brochure on WhatsApp"><i class="fa-brands fa-whatsapp text-teal"></i> Make Primary</button>';

    var viewBtn = doc.url
      ? '<a href="' + esc(doc.url) + '" target="_blank" class="btn-dash btn-outline btn-xs" style="text-decoration:none;display:inline-flex;align-items:center;gap:0.25rem;" title="Open PDF in new tab"><i class="fa-solid fa-arrow-up-right-from-square text-teal"></i> View PDF</a>'
      : '';
    var editBtn = '<button type="button" class="btn-dash btn-outline btn-xs" onclick="openDocViewModal(\'' + esc(doc.id) + '\')" title="Edit details"><i class="fa-solid fa-sliders"></i></button>';
    var deleteBtn = '<button type="button" class="btn-dash btn-outline btn-xs btn-danger-soft" onclick="deleteDocCard(\'' + esc(doc.id) + '\')" title="Delete PDF"><i class="fa-solid fa-trash"></i></button>';

    var categories = ['Menu', 'Price List', 'Brochure', 'Floor Plan', 'Catalog', 'Specifications', 'Catering Package', 'Other'];
    var catOptions = categories.map(function (c) {
      return '<option value="' + esc(c) + '"' + (categoryLabel === c ? ' selected' : '') + '>' + esc(c) + '</option>';
    }).join('');

    html += '<div class="doc-item-card">' +
      '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:0.75rem;flex-wrap:wrap;">' +
        '<div style="flex:1;min-width:min(100%, 220px);">' +
          '<div style="display:flex;align-items:center;gap:0.5rem;flex-wrap:wrap;margin-bottom:0.375rem;">' +
            '<span class="badge-pdf"><i class="fa-solid fa-file-pdf"></i> PDF</span>' +
            '<select class="form-select font-sans" style="padding:0.2rem 0.5rem;font-size:0.75rem;border-radius:var(--radius-xs);height:auto;width:auto;min-width:110px;" onchange="updateDocField(\'' + esc(doc.id) + '\', \'category\', this.value)">' +
              catOptions +
            '</select>' +
            primaryBadge +
          '</div>' +
          '<div style="margin-bottom:0.5rem;">' +
            '<input class="form-input font-sans" style="font-weight:600;font-size:0.9375rem;color:var(--text-main);padding:0.375rem 0.5rem;width:100%;border:1px solid transparent;background:transparent;border-radius:var(--radius-xs);" ' +
              'value="' + esc(doc.name || doc.title || '') + '" ' +
              'placeholder="Enter document display name..." ' +
              'onfocus="this.style.borderColor=\'var(--accent)\';this.style.background=\'var(--bg-input)\';" ' +
              'onblur="this.style.borderColor=\'transparent\';this.style.background=\'transparent\';" ' +
              'onchange="updateDocField(\'' + esc(doc.id) + '\', \'name\', this.value)">' +
          '</div>' +
          '<div style="font-size:0.75rem;color:var(--text-muted);display:flex;gap:0.75rem;align-items:center;flex-wrap:wrap;margin-bottom:0.625rem;">' +
            '<span class="font-mono" style="color:var(--text-secondary);"><i class="fa-solid fa-paperclip text-teal me-1"></i>' + esc(doc.fileName || '') + '</span>' +
            '<span class="font-mono">' + esc(doc.size || doc.fileSize || '') + '</span>' +
            '<span>&bull;</span>' +
            '<span>Uploaded ' + esc(doc.uploadDate || doc.uploadedAt || '') + '</span>' +
          '</div>' +
        '</div>' +
        '<div style="display:flex;align-items:center;gap:0.375rem;flex-shrink:0;">' +
          viewBtn + editBtn + deleteBtn +
        '</div>' +
      '</div>' +
      '<div style="margin-top:0.5rem;border-top:1px solid var(--border-color);padding-top:0.625rem;">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:0.375rem;">' +
          '<label class="form-label" style="font-size:0.75rem;font-weight:600;color:var(--text-main);margin:0;display:inline-flex;align-items:center;gap:0.375rem;">' +
            '<i class="fa-solid fa-robot text-teal"></i> AI Context &amp; Trigger Instructions:' +
          '</label>' +
          '<span style="font-size:0.6875rem;color:var(--text-muted);">The WhatsApp AI reads this description to know when to send this PDF</span>' +
        '</div>' +
        '<textarea class="form-input font-sans" rows="2" style="width:100%;resize:vertical;font-size:0.8125rem;line-height:1.4;" ' +
          'placeholder="Describe what is inside this document and when the AI should send it to customers (e.g. \'Contains complete 2026 beverage and dining prices in IDR. Send when customers ask for menu, drink list, or pricing.\')." ' +
          'onchange="updateDocField(\'' + esc(doc.id) + '\', \'description\', this.value)">' + esc(doc.description || '') + '</textarea>' +
      '</div>' +
    '</div>';
  });

  container.innerHTML = html;
}
window.renderDocList = renderDocList;

function setupDocumentUploader() {
  var input = $('doc-upload-input');
  if (input && !input._bound) {
    input._bound = true;
    input.addEventListener('change', handleDocFileUpload);
  }
  initDocDropzone();
  renderDocList();
}
window.setupDocumentUploader = setupDocumentUploader;

/* Live status polling timer reference */
var _waStatusPollingInterval = null;
/* QR lifetime law (2026-08-26): a QR shows ONLY after an explicit click and
   auto-expires (~45s). Never persistent. */
var _waQrCountdownTimer = null;

function clearWaQrCountdown() {
  if (_waQrCountdownTimer) { clearInterval(_waQrCountdownTimer); _waQrCountdownTimer = null; }
}
