var liveChatPoll = null;
function onPanelActivated(id) {
  applyRoleEnforcement();
  if (liveChatPoll) { clearInterval(liveChatPoll); liveChatPoll = null; }

  if (id === 'live-chat') {
    if (!activeChatPhone) renderUnselectedChatPlaceholder();
    loadInbox();
    liveChatPoll = setInterval(function () {
      if (document.visibilityState === 'hidden') return;
      loadInbox(true);
      if (activeChatPhone) loadThreadMessages(activeChatPhone, true);
    }, 5000);
  } else if (id === 'appointments' || id === 'bookings') {
    var isSpacesOn = false;
    if (waAiConfig && waAiConfig.spacesEnabled !== undefined) {
      isSpacesOn = Boolean(waAiConfig.spacesEnabled);
    } else if (window.waAiState && window.waAiState.config && window.waAiState.config.spaces_enabled !== undefined) {
      isSpacesOn = Boolean(window.waAiState.config.spaces_enabled);
    }
    var defaultSubTab = isSpacesOn ? 'stations' : 'schedule';
    var savedSubTab = defaultSubTab;
    try { savedSubTab = sessionStorage.getItem('codaxiom-dash-bk-subtab') || defaultSubTab; } catch(e) {}
    if (typeof switchBookingsSubTab === 'function') {
      switchBookingsSubTab(savedSubTab);
    } else {
      bkInitBookingsPanel();
    }
  } else if (id === 'analytics') {
    loadAnalytics();
  } else if (id === 'overview') {
    loadOverview();
  } else if (id === 'business-module') {
    mountBusinessModule(false);
  } else if (id === 'payments') {
    loadPaymentsPanel();
  } else if (id === 'staff') {
    var staffCfgP = configLoaded ? Promise.resolve() : waAiLoadConfig();
    staffCfgP.then(function () { waAiLoadStaff(); });
  } else if (id === 'settings') {
    var setCfgP = configLoaded ? Promise.resolve() : waAiLoadConfig();
    setCfgP.then(function () {
      applyRoleEnforcement();
    });
  } else if (id === 'reviews') {
    reviewsLoad();
  } else if (id === 'ai-receptionist') {
    var cfgP = (typeof configLoaded !== 'undefined' && configLoaded) ? Promise.resolve() : waAiLoadConfig();
    cfgP.then(function () {
      var targetTab = window._activeAiCockpitTab || 'connection';
      switchCockpitTab(targetTab);
    });
  } else if (id === 'catalog') {
    waAiRenderCatalog();
    if (typeof waAiLoadConfig === 'function' && !window.__SANDBOXED_DEMO__ && (typeof bkIsDemo !== 'function' || !bkIsDemo())) {
      waAiLoadConfig(true).then(function () {
        waAiRenderCatalog();
      }).catch(function () {});
    }
  } else if (id === 'orders') {
    loadOrdersFromLedger();
  } else if (id === 'stations') {
    initStationsPanel();
  } else if (id === 'rentals') {
    renderRentalsPanel();
    if (typeof waAiLoadRentalsAndActivity === 'function') waAiLoadRentalsAndActivity();
  } else if (id === 'customers' || id === 'passes') {
    if (typeof umLoadPasses === 'function') umLoadPasses();
    else renderPassesPanel();
  } else if (id === 'studio') {
    loadStudioContent();
  }

  applySellingModeGating();
}

