function toggleSpacesSection(forceVal) {
  var isDemo = Boolean(window.__SANDBOXED_DEMO__) || (typeof DEMO_MODE !== 'undefined' && DEMO_MODE);
  var current;
  if (typeof forceVal === 'boolean') {
    current = !forceVal;
  } else {
    var toggleEl = $('settings-spaces-toggle');
    if (toggleEl) {
      current = toggleEl.classList.contains('on');
    } else if (waAiConfig && waAiConfig.spacesEnabled !== undefined) {
      current = Boolean(waAiConfig.spacesEnabled);
    } else {
      current = false;
    }
  }
  var next = !current;
  if (!waAiConfig) waAiConfig = {};
  waAiConfig.spacesEnabled = next;
  if (window.waAiState && window.waAiState.config) {
    window.waAiState.config.spaces_enabled = next;
  }

  // Persist to local config mirror
  if (typeof mirrorLocalConfig === 'function') {
    mirrorLocalConfig({ spacesEnabled: next });
  }

  // Refresh taxonomy and DOM visibility
  applyNicheTaxonomy();
  if (typeof updateBookingCapacityState === 'function') {
    updateBookingCapacityState();
  }

  // If enabled, trigger floor load immediately
  if (next && typeof loadStationsData === 'function') {
    loadStationsData();
  }

  // Save to backend if real operational cockpit
  if (!window.__SANDBOXED_DEMO__ && typeof apiPost === 'function') {
    var sub = typeof waAiGetSubdomain === 'function' ? waAiGetSubdomain() : '';
    if (sub) {
      apiPost('/api/admin/client-bot-config', { subdomain: sub, spacesEnabled: next, skipDeploy: true }).catch(function () {});
    }
  }

  var msg = next 
    ? 'Stations module enabled and added to navigation.' 
    : 'Stations module disabled and hidden from navigation.';
  if (typeof showToast === 'function') showToast(msg, 'success');
}
window.toggleSpacesSection = toggleSpacesSection;
window.toggleStationsSection = toggleSpacesSection;

function applySellingModeGating() {
  // Active-but-empty law (2026-08-22): in DEMO every selling mode stays visible
  // (nav + panels + filter chips) so the showcase shows the full capability;
  // modes the niche profile does not populate render their normal empty states.
  // Real cockpits keep the client's declared subset (unchanged behavior).
  applyNicheTaxonomy();
  var isDemoMode = Boolean(window.__SANDBOXED_DEMO__) || (typeof DEMO_MODE !== 'undefined' && DEMO_MODE);
  var activeMod = (typeof activeModuleId !== 'undefined' && activeModuleId) || 'universal';
  var enabled = getEnabledSellingModes(activeMod);
  document.querySelectorAll('[data-selling-modes]').forEach(function (el) {
    var raw = el.getAttribute('data-selling-modes') || '';
    var req = raw.split(/\s+/).filter(Boolean);
    if (req.length === 0) return;
    var hasMatch = req.some(function (m) { return enabled.indexOf(m) !== -1; });
    if (isDemoMode || hasMatch) {
      el.classList.remove('mode-hidden');
      if (el.style.display === 'none') el.style.display = '';
    } else {
      el.classList.add('mode-hidden');
      el.style.display = 'none';
    }
  });

  var activePanel = document.querySelector('.panel.active');
  if (activePanel && activePanel.classList.contains('mode-hidden')) {
    switchPanel('overview');
  }
}

/* ============================================================
   BOT CONFIG (AI Training / Keyword Rules / Catalog / Media)
   ============================================================ */
var waAiConfig = {
  aiPersona: { tone: 'professional', language: 'both', customPrompt: '' },
  productCatalog: [], mediaAttachments: [], customRules: [],
  welcomeMessage: '', faqs: '', productsAndServices: '', aiBotEnabled: true};
window.waAiConfig = waAiConfig;
var configLoaded = false;

/* ============================================================
   LOCAL CONFIG MIRROR
   The engine client-bot-config endpoint round-trips a known key set
   (catalog, gateway, sellingModes, businessModule, ...). Dashboard-owned
   keys it does NOT persist yet - staff, rolePermissions, nicheModules
   (ENGINE-API-GAPS.proai.md Section 3.8) - are mirrored to localStorage so the
   UI stays functional per device, and POSTed anyway (forward-compatible:
   the moment the engine whitelists them they become server truth).
   Server values always win over the mirror when both exist.
   ============================================================ */
var LOCAL_CFG_KEY = 'codaxiom-dash-localcfg';
var LOCAL_CFG_KEYS = ['staff', 'rolePermissions', 'nicheModules', 'siteContent', 'spacesEnabled'];

function localCfgStorageKey() { return LOCAL_CFG_KEY + ':' + waAiGetSubdomain(); }
function getLocalCfg() {
  try { return JSON.parse(localStorage.getItem(localCfgStorageKey()) || '{}'); }
  catch (e) { return {}; }
}
function mirrorLocalConfig(patch) {
  try {
    var cur = getLocalCfg();
    Object.keys(patch || {}).forEach(function (k) {
      if (LOCAL_CFG_KEYS.indexOf(k) !== -1) cur[k] = patch[k];
    });
    localStorage.setItem(localCfgStorageKey(), JSON.stringify(cur));
  } catch (e) {}
}
function adoptLocalConfigMirror() {
  var mirror = getLocalCfg();
  LOCAL_CFG_KEYS.forEach(function (k) {
    if (waAiConfig[k] === undefined && mirror[k] !== undefined) waAiConfig[k] = mirror[k];
  });
}

function waAiLoadConfig() {
  return apiGet('/api/admin/client-bot-config')
    .then(function (data) {
      if (data.config) {
        waAiConfig = data.config;
        waAiConfig.reservedStock = data.reservedStock || data.config.reservedStock || {};
        if (data.config.niche) {
          try {
            var sub = typeof waAiGetSubdomain === 'function' ? waAiGetSubdomain() : '';
            var cleanNiche = String(data.config.niche).toLowerCase().trim();
            if (sub && cleanNiche) localStorage.setItem('codaxiom_niche:' + sub, cleanNiche);
            window.__dash_cached_niche = cleanNiche;
            if (window.__dash_session_data) window.__dash_session_data.niche = cleanNiche;
          } catch (e) {}
        }
      }
      configLoaded = true;
      updateBrainChip(data.brainFingerprint, data.trainingVersion);
      adoptLocalConfigMirror();
      applyConfigToUI();
      applyConfigTheme();
      resolveModuleFromConfig();
      applyPlanGating();
      renderCatalogTypeControls();
      applyNicheTaxonomy();
    })
    .catch(function (e) { console.warn('[Config] Load error:', e); });
}

/* ── Brain fingerprint chip (law 2026-08-25) ── */
function updateBrainChip(fingerprint, trainingVersion) {
  var chip = $('brain-version-chip');
  if (!chip) return;
  if (!fingerprint) { chip.style.display = 'none'; return; }
  chip.textContent = 'AI Brain: ' + fingerprint + (trainingVersion ? ' · ' + trainingVersion : '');
  chip.style.display = 'inline-flex';
}

function applyConfigToUI() {
  var c = waAiConfig || {};
  var p = c.aiPersona || {};

  if (c.businessName) {
    document.title = 'Codaxiom Cockpit · ' + c.businessName;
  }

  var toneEl = $('ai-tone') || $('wa-ai-tone');
  if (toneEl) toneEl.value = p.tone || 'professional';

  var currentLang = p.language || c.language || 'both';
  var langContainer = $('ai-language');
  if (langContainer && langContainer.querySelectorAll) {
    var langBtns = langContainer.querySelectorAll('.pill-btn');
    langBtns.forEach(function (btn) {
      btn.classList.toggle('active', btn.getAttribute('data-value') === currentLang);
    });
  } else if ($('wa-ai-language')) {
    $('wa-ai-language').value = currentLang;
  }

  var currentRespLen = p.responseLength || c.responseLength || 'concise';
  var respLenContainer = $('ai-response-length');
  if (respLenContainer && respLenContainer.querySelectorAll) {
    var respLenBtns = respLenContainer.querySelectorAll('.pill-btn');
    respLenBtns.forEach(function (btn) {
      btn.classList.toggle('active', btn.getAttribute('data-value') === currentRespLen);
    });
  }

  var promptEl = $('ai-prompt') || $('custom-rules-textarea') || $('wa-ai-custom-prompt');
  if (promptEl) promptEl.value = p.customPrompt || c.customPrompt || '';

  setAiEnabledUI(c.aiBotEnabled !== false);

  // Custom welcome message REMOVED (operator request 2026-08-31): the AI
  // composes its own senior-sales opening per the Senior Closer doctrine.

  if ($('ai-agent-name')) $('ai-agent-name').value = p.agentName || c.agentName || '';
  if ($('ai-role-title')) $('ai-role-title').value = p.roleTitle || c.roleTitle || '';
  if ($('custom-rules-textarea') && $('custom-rules-textarea') !== promptEl) {
    $('custom-rules-textarea').value = c.customRulesText || c.escalationRules || '';
  }

  // 47-Nation Primary & Secondary Language Selector Bindings
  if ($('persona-primary-lang')) {
    var pLang = p.primaryLanguage || (c.languages && c.languages.primary) || (p.language === 'en' ? 'en' : 'id');
    $('persona-primary-lang').value = pLang;
  }
  if ($('persona-secondary-lang')) {
    var sLang = p.secondaryLanguage || (c.languages && c.languages.secondary) || 'auto';
    $('persona-secondary-lang').value = sLang;
  }

  // Autonomous Review Collection Toggle
  if ($('wa-ai-auto-reviews-toggle')) {
    $('wa-ai-auto-reviews-toggle').checked = (p.autoReviewsEnabled !== false && c.autoReviewsEnabled !== false);
  }

  if ($('wa-ai-faqs')) $('wa-ai-faqs').value = c.faqs || '';
  if ($('wa-ai-products-text')) $('wa-ai-products-text').value = c.productsAndServices || '';

  if ($('biz-desc-input')) $('biz-desc-input').value = c.businessDescription || '';
  if ($('wa-company-story')) $('wa-company-story').value = c.companyStory || '';
  if ($('biz-address-input')) $('biz-address-input').value = c.businessAddress || c.address || '';
  if ($('biz-gmaps-link')) $('biz-gmaps-link').value = c.googleMapsUrl || c.gmapsUrl || '';
  if ($('biz-website-input')) $('biz-website-input').value = c.websiteUrl || c.website || '';
  if ($('biz-email-input')) $('biz-email-input').value = c.supportEmail || c.email || '';
  if ($('wa-op-hours')) $('wa-op-hours').value = c.operatingHours || '';
  if (typeof renderAboutScheduleSummary === 'function') renderAboutScheduleSummary();

  if ($('doc-pdf-url')) $('doc-pdf-url').value = c.catalogPaymentUrl || c.docPdfUrl || c.pdfBrochureUrl || '';
  if ($('doc-raw-text')) {
    var rawT = c.docRawText || c.knowledgeBaseText || '';
    if (rawT.indexOf('FlateDecode') !== -1 || rawT.indexOf('stream') !== -1) {
      rawT = rawT.replace(/=== DOCUMENT:[^=]*===[\s\S]*?(?=(=== DOCUMENT:|$))/g, function (block) {
        if (block.indexOf('FlateDecode') !== -1 || block.indexOf('stream') !== -1) return '';
        return block;
      }).replace(/Filter\s+FlateDecode[\s\S]*?(?=(\n\n|\n===|$))/gi, '').trim();
    }
    $('doc-raw-text').value = rawT;
  }

  if ($('cat-pane-payurl')) $('cat-pane-payurl').value = c.catalogPaymentUrl || c.defaultPaymentUrl || '';

  if ($('promo-code-input')) $('promo-code-input').value = c.promoCode || '';
  if ($('promo-discount-input')) $('promo-discount-input').value = c.promoDiscount || '';
  if ($('wa-promo-rules')) $('wa-promo-rules').value = c.promoRules || '';

  if (c.promosList && Array.isArray(c.promosList)) {
    waAiConfig.promosList = c.promosList;
  } else if (c.promotions && Array.isArray(c.promotions)) {
    waAiConfig.promosList = c.promotions;
  }

  if ($('wa-appt-meet-link')) $('wa-appt-meet-link').value = c.appointmentMeetLink || c.meetLink || '';
  if ($('wa-appt-slot-duration')) $('wa-appt-slot-duration').value = c.appointmentSlotDuration || c.slotDuration || '30';

  if ($('biz-seo-title-preview')) $('biz-seo-title-preview').value = c.seoTitle || '';
  if ($('biz-seo-desc-preview')) $('biz-seo-desc-preview').value = c.seoDescription || '';
  if ($('biz-seo-keywords-preview')) $('biz-seo-keywords-preview').value = c.seoKeywords || '';
  if ($('biz-tagline-preview')) $('biz-tagline-preview').value = c.tagline || '';

  // Milestone 2 Cockpit additions
  if ($('ai-temperature-slider')) {
    $('ai-temperature-slider').value = p.temperature !== undefined ? p.temperature : (c.temperature || 0.3);
    updateTemperatureLabel();
  }
  if (c.strictPriceGuard !== undefined) {
    var toggle = $('ai-strict-price-guard-toggle');
    var label = $('ai-strict-price-guard-label');
    if (toggle) toggle.className = 'toggle-switch ' + (c.strictPriceGuard ? 'on' : '');
    if (label) label.textContent = c.strictPriceGuard ? 'Active' : 'Disabled';
  }
  updatePromptCharCounter();
  updateCockpitTabBadges();

  // Synchronize Persona Word Counter & About Preview Links
  updatePersonaWordCounter();
  updateAboutPreviewLinks();

  // Multi-Currency & Gateway Dynamic Synchronization (Zero Hardcoding Law)
  var activeCur = defaultCurrency();
  var curBadge = $('cat-edit-currency-badge');
  if (curBadge) curBadge.textContent = activeCur;
  var stBadges = document.querySelectorAll('.st-currency-badge');
  for (var sbi = 0; sbi < stBadges.length; sbi++) {
    stBadges[sbi].textContent = activeCur;
  }
  var quoteCurLabel = $('quote-fee-currency-label');
  if (quoteCurLabel) quoteCurLabel.textContent = activeCur;
  var promoAddon = $('promo-discount-addon');
  if (promoAddon) promoAddon.textContent = getCurrencySymbol(activeCur).trim();
  var promoSample = $('promo-calc-result');
  if (promoSample && (!promoSample.getAttribute('data-custom') || promoSample.getAttribute('data-custom') === 'false')) {
    if (activeCur === 'IDR') {
      promoSample.textContent = 'Sample: ' + fmtPrice(100000, 'IDR') + ' -> ' + fmtPrice(80000, 'IDR') + ' (Saves ' + fmtPrice(20000, 'IDR') + ')';
    } else {
      promoSample.textContent = 'Sample: ' + fmtPrice(100, activeCur) + ' -> ' + fmtPrice(80, activeCur) + ' (Saves ' + fmtPrice(20, activeCur) + ')';
    }
  }
  if (typeof syncPayMethodFilterOptions === 'function') syncPayMethodFilterOptions();

  if (c.docList) {
    if (Array.isArray(c.docList)) {
      c.docList.forEach(function (d) {
        if (!d.name && d.title) d.name = d.title;
        if (!d.title && d.name) d.title = d.name;
        if (!d.size && d.fileSize) d.size = d.fileSize;
        if (!d.fileSize && d.size) d.fileSize = d.size;
      });
    }
    waAiConfig.docList = c.docList;
    if (typeof waState !== 'undefined' && waState.aiConfig) {
      waState.aiConfig.docList = c.docList;
      waState.aiConfig.knowledgeBase = c.docList;
    }
  }

  if (c.blockedSlots) {
    waAiConfig.blockedSlots = c.blockedSlots;
    if (typeof umState !== 'undefined') {
      umState.blockedSlots = c.blockedSlots;
    }
  }

  // Schedule & Availability Sub-section Live Hydration
  if (c.weeklySchedule && Array.isArray(c.weeklySchedule) && c.weeklySchedule.length > 0) {
    umState.weeklySchedule = JSON.parse(JSON.stringify(c.weeklySchedule));
    waAiConfig.weeklySchedule = JSON.parse(JSON.stringify(c.weeklySchedule));
    if (typeof bkRenderWeeklySchedule === 'function') bkRenderWeeklySchedule();
  }
  if (c.businessTimezone) {
    waAiConfig.businessTimezone = c.businessTimezone;
    if (typeof bkUpdateBizTimezoneDisplay === 'function') bkUpdateBizTimezoneDisplay(c.businessTimezone);
  }
  if (c.advanceNoticeMin !== undefined) {
    waAiConfig.advanceNoticeMin = c.advanceNoticeMin;
    if (typeof bkUpdateAdvanceNoticeDisplay === 'function') bkUpdateAdvanceNoticeDisplay(c.advanceNoticeMin);
  }
  if (c.pendingTtlMinutes !== undefined) {
    waAiConfig.pendingTtlMinutes = c.pendingTtlMinutes;
    if (typeof bkUpdatePendingTtlDisplay === 'function') bkUpdatePendingTtlDisplay(c.pendingTtlMinutes);
  }
  if (c.autoReminders && typeof c.autoReminders === 'object') {
    waAiConfig.autoReminders = c.autoReminders;
    var r24 = $('bk-remind-24h');
    if (r24 && typeof c.autoReminders['24h'] === 'boolean') r24.checked = c.autoReminders['24h'];
    var r1h = $('bk-remind-1h');
    if (r1h && typeof c.autoReminders['1h'] === 'boolean') r1h.checked = c.autoReminders['1h'];
  }
  if (typeof renderActiveBlocksShelf === 'function') renderActiveBlocksShelf();

  waAiRenderCatalog(c.productCatalog || []);
  waAiRenderMedia(c.mediaAttachments || []);
  waAiRenderRules(c.customRules || []);
  renderPromoList();
  renderFaqsList();
  renderDocList();
  initDocDropzone();

  updateSidebarBranding();
}

function setAiEnabledUI(enabled) {
  var toggle = $('wa-ai-enabled-toggle');
  if (toggle) { toggle.classList.toggle('on', enabled); }
  var label = $('wa-ai-enabled-label');
  if (label) label.textContent = enabled ? t('training.aiEnabled', 'Enabled') : t('training.aiDisabled', 'Disabled');
  var ovToggle = $('overview-ai-toggle');
  if (ovToggle) ovToggle.classList.toggle('on', enabled);
  var ovLabel = $('overview-ai-label');
  if (ovLabel) ovLabel.textContent = enabled ? t('overview.aiOn', 'AI assistant is enabled') : t('overview.aiOff', 'AI assistant is paused');

  // AI Agent Dashboard law: AI Receptionist is native and unconditional.
  var navAi = $('nav-ai-receptionist');
  if (navAi) navAi.classList.remove('plan-hidden');
  var panelAi = $('panel-ai-receptionist');
  if (panelAi) panelAi.classList.remove('plan-hidden');
}

/* Theme from config: only applies when the user has NOT explicitly chosen. */
function applyConfigTheme() {
  if (getStoredTheme()) return;
  var ct = waAiConfig && waAiConfig.dashboardTheme;
  if (ct === 'light' || ct === 'dark') applyTheme(ct, false);
}

function toggleAiEnabled() {
  if (demoActionBlocked()) return;
  var next = !(waAiConfig.aiBotEnabled !== false);
  waAiConfig.aiBotEnabled = next;
  setAiEnabledUI(next);
  waAiSaveConfig(true);
  if (typeof showToast === 'function') {
    showToast(next ? 'WhatsApp AI Receptionist is active and replying.' : 'WhatsApp AI Receptionist is paused (direct staff chat only).', 'info');
  }
}

function waAiSaveConfig(quiet, options) {
  if (demoActionBlocked()) return;

  // Hydration safety guard (2026-09-06): Never fire a save if config hasn't loaded yet.
  if (!configLoaded && !window.__SANDBOXED_DEMO__ && !DEMO_MODE) {
    console.warn('[waAiSaveConfig] Aborted: config not loaded yet, preventing unhydrated blank-sweep.');
    return Promise.resolve();
  }

  var saveBtns = [$('wa-ai-save-btn'), $('cat-save-btn'), $('doc-save-btn')].filter(Boolean);
  if (saveBtns.length && !quiet) {
    saveBtns.forEach(function (b) {
      if (!b.getAttribute('data-label')) b.setAttribute('data-label', b.innerHTML);
      b.innerHTML = '<i class="fa-solid fa-spinner fa-spin me-1"></i> ' + t('common.saving', 'Saving...');
      b.disabled = true;
    });
  }

  var toneVal = $('ai-tone') ? $('ai-tone').value : ($('wa-ai-tone') ? $('wa-ai-tone').value : 'professional');

  var langVal = 'both';
  var langContainer = $('ai-language');
  if (langContainer) {
    var activeLangBtn = langContainer.querySelector('.pill-btn.active');
    if (activeLangBtn) langVal = activeLangBtn.getAttribute('data-value') || 'both';
  } else if ($('wa-ai-language')) {
    langVal = $('wa-ai-language').value;
  }

  var respLenVal = 'concise';
  var respLenContainer = $('ai-response-length');
  if (respLenContainer) {
    var activeRespLenBtn = respLenContainer.querySelector('.pill-btn.active');
    if (activeRespLenBtn) respLenVal = activeRespLenBtn.getAttribute('data-value') || 'concise';
  }

  var promptVal = $('ai-prompt') ? $('ai-prompt').value : ($('custom-rules-textarea') ? $('custom-rules-textarea').value : ($('wa-ai-custom-prompt') ? $('wa-ai-custom-prompt').value : ''));
  if (!promptVal && waAiConfig && waAiConfig.aiPersona && waAiConfig.aiPersona.customPrompt) {
    promptVal = waAiConfig.aiPersona.customPrompt;
  }
  if (promptVal) {
    var pWords = promptVal.trim().split(/\s+/).filter(Boolean);
    if (pWords.length > 100) {
      promptVal = pWords.slice(0, 100).join(' ');
      if ($('custom-rules-textarea')) $('custom-rules-textarea').value = promptVal;
      updatePersonaWordCounter();
    }
  }
  var faqsVal = $('wa-ai-faqs') ? $('wa-ai-faqs').value : '';
  if (!faqsVal && waAiConfig && waAiConfig.faqs) {
    faqsVal = waAiConfig.faqs;
  }

  // 47-Nation persona language selectors (v3-wave): previously rendered but
  // never read into the payload. Persist primary + secondary (auto/en/id/none).
  var personaPrimaryLang = $('persona-primary-lang') ? $('persona-primary-lang').value : (waAiConfig.aiPersona && waAiConfig.aiPersona.primaryLanguage) || 'id';
  var personaSecondaryLang = $('persona-secondary-lang') ? $('persona-secondary-lang').value : (waAiConfig.aiPersona && waAiConfig.aiPersona.secondaryLanguage) || 'auto';
  var autoReviewsEnabled = $('wa-ai-auto-reviews-toggle') ? $('wa-ai-auto-reviews-toggle').checked : (waAiConfig.aiPersona && waAiConfig.aiPersona.autoReviewsEnabled !== false);

  var agentNameVal = $('ai-agent-name') ? $('ai-agent-name').value.trim() : (waAiConfig.agentName || '');
  var roleTitleVal = $('ai-role-title') ? $('ai-role-title').value.trim() : (waAiConfig.roleTitle || '');
  var companyStoryVal = $('wa-company-story') ? $('wa-company-story').value.trim() : (waAiConfig.companyStory || '');
  var brandColorVal = ($('studio-brand-color') ? $('studio-brand-color').value.trim() : '') || ($('wa-brand-color') ? $('wa-brand-color').value : '') || (waAiConfig.brandColor || (waAiConfig.siteContent && waAiConfig.siteContent.brandColor) || '');
  var opHoursVal = (typeof formatWeeklyScheduleSummary === 'function') ? formatWeeklyScheduleSummary() : ($('wa-op-hours') ? $('wa-op-hours').value.trim() : (waAiConfig.operatingHours || ''));
  if (!opHoursVal && waAiConfig && waAiConfig.operatingHours) {
    opHoursVal = waAiConfig.operatingHours;
  }
  var primaryDoc = (waAiConfig.docList || []).find(function (d) { return d.isPrimary; });
  var docPdfUrlVal = (primaryDoc && primaryDoc.url) || ($('doc-pdf-url') ? $('doc-pdf-url').value.trim() : '') || (waAiConfig.pdfBrochureUrl || waAiConfig.docPdfUrl || '');
  var docRawTextVal = $('doc-raw-text') ? $('doc-raw-text').value.trim() : (waAiConfig.docRawText || '');
  var catPayUrlVal = $('cat-pane-payurl') ? $('cat-pane-payurl').value.trim() : (waAiConfig.catalogPaymentUrl || waAiConfig.defaultPaymentUrl || '');
  var promoCodeVal = $('promo-code-input') ? $('promo-code-input').value.trim() : (waAiConfig.promoCode || '');
  var promoDiscountVal = $('promo-discount-input') ? $('promo-discount-input').value.trim() : (waAiConfig.promoDiscount || '');
  var promoRulesVal = $('wa-promo-rules') ? $('wa-promo-rules').value.trim() : (waAiConfig.promoRules || '');
  var apptMeetLinkVal = $('wa-appt-meet-link') ? $('wa-appt-meet-link').value.trim() : (waAiConfig.appointmentMeetLink || '');
  var apptSlotDurationVal = $('wa-appt-slot-duration') ? $('wa-appt-slot-duration').value : (waAiConfig.appointmentSlotDuration || '30');

  var tempVal = $('ai-temperature-slider') ? parseFloat($('ai-temperature-slider').value) : 0.3;
  var strictLock = waAiConfig ? waAiConfig.strictPriceGuard !== false : true;

  // Catalog safety guard (2026-09-08): Only send productCatalog when:
  // 1. Explicitly requested via options (e.g. isCatalogOnlySave or explicitStockItemIds)
  // 2. The catalog was actively modified (catalogDirty === true)
  // 3. Or when currently in the catalog panel
  var isCatalogSave = Boolean(
    (options && (options.isCatalogOnlySave || (Array.isArray(options.explicitStockItemIds) && options.explicitStockItemIds.length > 0))) ||
    catalogDirty ||
    (typeof currentPanel !== 'undefined' && currentPanel === 'catalog')
  );

  var catalogPayload = undefined;
  var clearCatalogFlag = false;
  if (isCatalogSave) {
    catalogPayload = waAiCollectCatalog();
    if (catalogPayload.length === 0) {
      if (catalogDirty || catalogClearedByUser) {
        clearCatalogFlag = true;
        catalogClearedByUser = false;
      } else if (waAiConfig && Array.isArray(waAiConfig.productCatalog) && waAiConfig.productCatalog.length > 0) {
        catalogPayload = waAiConfig.productCatalog;
      }
    }
  }

  var mediaPayload = waAiCollectMedia();
  var clearMediaFlag = false;
  var mediaListEl = $('wa-ai-media-list');
  if (mediaPayload.length === 0) {
    if (mediaListEl && mediaListEl.children.length === 0 && waAiConfig && Array.isArray(waAiConfig.mediaAttachments) && waAiConfig.mediaAttachments.length > 0) {
      clearMediaFlag = true;
    } else if (waAiConfig && Array.isArray(waAiConfig.mediaAttachments) && waAiConfig.mediaAttachments.length > 0) {
      mediaPayload = waAiConfig.mediaAttachments;
    }
  }

  var rulesPayload = waAiCollectRules();
  var clearRulesFlag = false;
  var rulesListEl = $('wa-ai-rules-list');
  if (rulesPayload.length === 0) {
    if (rulesListEl && rulesListEl.children.length === 0 && waAiConfig && Array.isArray(waAiConfig.customRules) && waAiConfig.customRules.length > 0) {
      clearRulesFlag = true;
    } else if (waAiConfig && Array.isArray(waAiConfig.customRules) && waAiConfig.customRules.length > 0) {
      rulesPayload = waAiConfig.customRules;
    }
  }

  var payload = {
    subdomain: waAiGetSubdomain(),
    aiPersona: {
      tone: toneVal,
      language: langVal,
      responseLength: respLenVal,
      customPrompt: promptVal,
      agentName: agentNameVal,
      roleTitle: roleTitleVal,
      temperature: tempVal,
      primaryLanguage: personaPrimaryLang,
      secondaryLanguage: personaSecondaryLang,
      autoReviewsEnabled: autoReviewsEnabled
    },
    autoReviewsEnabled: autoReviewsEnabled,
    // Website template languages (law 2026-09-12):
    // Preserved strictly from waAiConfig.languages / client intake, decoupled from
    // the WhatsApp bot's persona secondaryLanguage ('auto' / 'none' / backup).
    languages: (function () {
      if (waAiConfig && waAiConfig.languages && waAiConfig.languages.primary) {
        return {
          primary: String(waAiConfig.languages.primary).toLowerCase().trim(),
          secondary: waAiConfig.languages.secondary ? String(waAiConfig.languages.secondary).toLowerCase().trim() : String(waAiConfig.languages.primary).toLowerCase().trim()
        };
      }
      var sec = (personaSecondaryLang && personaSecondaryLang !== 'auto' && personaSecondaryLang !== 'none') ? personaSecondaryLang : (personaPrimaryLang === 'id' ? 'en' : 'id');
      return { primary: personaPrimaryLang, secondary: sec };
    })(),
    strictPriceGuard: strictLock,
    temperature: tempVal,
    aiBotEnabled: waAiConfig.aiBotEnabled !== false,
    faqs: faqsVal,
    productsAndServices: $('wa-ai-products-text') ? $('wa-ai-products-text').value : (waAiConfig.productsAndServices || ''),
    mediaAttachments: mediaPayload,
    clearMedia: clearMediaFlag,
    customRules: rulesPayload,
    clearRules: clearRulesFlag,

    // Cockpit 8-Subsection Bindings
    agentName: agentNameVal,
    roleTitle: roleTitleVal,
    companyStory: companyStoryVal,
    brandColor: brandColorVal,
    operatingHours: opHoursVal,
    docPdfUrl: docPdfUrlVal,
    pdfBrochureUrl: docPdfUrlVal,
    docRawText: docRawTextVal,
    docList: waAiConfig.docList || [],
    catalogPaymentUrl: catPayUrlVal,
    defaultPaymentUrl: catPayUrlVal,
    promoCode: promoCodeVal,
    promoDiscount: promoDiscountVal,
    promoRules: promoRulesVal,
    promotions: (typeof waAiConfig !== 'undefined' && Array.isArray(waAiConfig.promosList)) ? waAiConfig.promosList : [],
    appointmentMeetLink: apptMeetLinkVal,
    appointmentSlotDuration: apptSlotDurationVal,
    blockedSlots: (typeof umState !== 'undefined' && umState.blockedSlots) ? umState.blockedSlots : ((typeof waAiConfig !== 'undefined' && waAiConfig.blockedSlots) ? waAiConfig.blockedSlots : []),

    // Brand, Copywriting & SEO settings
    businessName: ($('biz-name-input') && $('biz-name-input').value.trim()) || waAiConfig.businessName || '',
    logoUrl: ($('biz-logo-input') && $('biz-logo-input').value.trim()) || waAiConfig.logoUrl || '',
    tagline: ($('biz-tagline-preview') && $('biz-tagline-preview').value.trim()) || waAiConfig.tagline || '',
    seoTitle: ($('biz-seo-title-preview') && $('biz-seo-title-preview').value.trim()) || waAiConfig.seoTitle || '',
    seoDescription: ($('biz-seo-desc-preview') && $('biz-seo-desc-preview').value.trim()) || waAiConfig.seoDescription || '',
    seoKeywords: ($('biz-seo-keywords-preview') && $('biz-seo-keywords-preview').value.trim()) || waAiConfig.seoKeywords || '',
    businessDescription: ($('biz-desc-input') && $('biz-desc-input').value.trim()) || waAiConfig.businessDescription || '',
    businessAddress: ($('biz-address-input') && $('biz-address-input').value.trim()) || waAiConfig.businessAddress || '',
    googleMapsUrl: ($('biz-gmaps-link') && $('biz-gmaps-link').value.trim()) || waAiConfig.googleMapsUrl || '',
    websiteUrl: ($('biz-website-input') && $('biz-website-input').value.trim()) || waAiConfig.websiteUrl || '',
    supportEmail: ($('biz-email-input') && $('biz-email-input').value.trim()) || waAiConfig.supportEmail || '',
    businessTimezone: (typeof waAiConfig !== 'undefined' && waAiConfig.businessTimezone) ? waAiConfig.businessTimezone : (typeof getBizTimezone === 'function' ? getBizTimezone() : ''),
    reminderSettings: (typeof waReminderSettings !== 'undefined') ? waReminderSettings : { reminder24h: true, reminder1h: true }
  };
  // Preserve server-side fields we don't edit in the UI
  if (waAiConfig.businessModule) payload.businessModule = waAiConfig.businessModule;
  if (waAiConfig.dashboardTheme) payload.dashboardTheme = waAiConfig.dashboardTheme;
  if (waAiConfig.paymentGateway) payload.paymentGateway = waAiConfig.paymentGateway;

  // Booking section round-trip (law 2026-09-01): these were toast-only before —
  // the AI never received the toggle state or the weekly schedule, so it kept
  // auto-booking even after the operator switched it off.
  payload.aiAutoBooking = (typeof waAiConfig !== 'undefined') ? (waAiConfig.aiAutoBooking !== false) : true;
  payload.advanceNoticeMin = (typeof waAiConfig !== 'undefined' && waAiConfig.advanceNoticeMin != null) ? waAiConfig.advanceNoticeMin : 0;
  payload.autoReminders = (typeof waAiConfig !== 'undefined' && waAiConfig.autoReminders) ? waAiConfig.autoReminders : { '24h': true, '1h': true };
  payload.depositRequired = (typeof waAiConfig !== 'undefined') ? (waAiConfig.depositRequired === true) : false;
  payload.maxParallel = (typeof waAiConfig !== 'undefined' && waAiConfig.slotCapacity) ? waAiConfig.slotCapacity : 1;
  payload.pendingTtlMinutes = (typeof waAiConfig !== 'undefined' && waAiConfig.pendingTtlMinutes) ? waAiConfig.pendingTtlMinutes : 30;
  payload.restBufferMinutes = (typeof waAiConfig !== 'undefined' && waAiConfig.restBufferMinutes != null) ? waAiConfig.restBufferMinutes : 5;
  payload.weeklySchedule = (typeof bkGetWeeklySchedule === 'function') ? bkGetWeeklySchedule() : null;

  if (isCatalogSave) {
    payload.productCatalog = catalogPayload;
    payload.isCatalogOnlySave = (options && options.isCatalogOnlySave === true) ? true : false;
    payload.explicitStockItemIds = (options && Array.isArray(options.explicitStockItemIds)) ? options.explicitStockItemIds : [];
    payload.clearCatalog = clearCatalogFlag;
  }

  return apiPost('/api/admin/client-bot-config', payload)
    .then(function (data) {
      if (saveBtns.length && !quiet) {
        saveBtns.forEach(function (b) {
          b.innerHTML = data && data.success ? '<i class="fa-solid fa-check me-1"></i> ' + t('common.saved', 'Saved') : '<i class="fa-solid fa-xmark me-1"></i> ' + t('common.saveFailed', 'Failed');
          b.disabled = false;
          setTimeout(function () { b.innerHTML = b.getAttribute('data-label') || t('common.save', 'Save Changes'); }, 2000);
        });
      }
      if (data && data.success) {
        // Keep the local mirror in sync so KPIs reflect the save immediately.
        if (payload.productCatalog !== undefined) waAiConfig.productCatalog = payload.productCatalog;
        waAiConfig.businessName = payload.businessName;
        waAiConfig.logoUrl = payload.logoUrl;
        waAiConfig.tagline = payload.tagline;
        waAiConfig.seoTitle = payload.seoTitle;
        waAiConfig.seoDescription = payload.seoDescription;
        waAiConfig.seoKeywords = payload.seoKeywords;
        waAiConfig.businessDescription = payload.businessDescription;
        waAiConfig.catalogPaymentUrl = payload.catalogPaymentUrl;
        waAiConfig.defaultPaymentUrl = payload.defaultPaymentUrl;
        waAiConfig.docPdfUrl = payload.docPdfUrl;
        waAiConfig.docRawText = payload.docRawText;
        waAiConfig.docList = payload.docList;
        waAiConfig.pdfBrochureUrl = payload.pdfBrochureUrl;
        waAiConfig.promoCode = payload.promoCode;
        waAiConfig.promoDiscount = payload.promoDiscount;
        waAiConfig.promoRules = payload.promoRules;
        waAiConfig.appointmentMeetLink = payload.appointmentMeetLink;
        waAiConfig.appointmentSlotDuration = payload.appointmentSlotDuration;
        waAiConfig.blockedSlots = payload.blockedSlots;
        if (payload.weeklySchedule) waAiConfig.weeklySchedule = payload.weeklySchedule;
        if (payload.businessTimezone) waAiConfig.businessTimezone = payload.businessTimezone;
        if (payload.advanceNoticeMin !== undefined) waAiConfig.advanceNoticeMin = payload.advanceNoticeMin;
        if (payload.pendingTtlMinutes !== undefined) waAiConfig.pendingTtlMinutes = payload.pendingTtlMinutes;
        if (payload.autoReminders) waAiConfig.autoReminders = payload.autoReminders;
        if (!waAiConfig.aiPersona) waAiConfig.aiPersona = {};
        waAiConfig.aiPersona.autoReviewsEnabled = payload.autoReviewsEnabled;
        waAiConfig.autoReviewsEnabled = payload.autoReviewsEnabled;
        markCatalogDirty(false);
        if (!quiet) showToast(t('common.saved', 'Configuration saved successfully'), 'success');
      } else {
        if (!quiet) showToast(t('common.saveFailed', 'Save failed'), 'error');
      }
    })
    .catch(function () {
      if (saveBtns.length && !quiet) {
        saveBtns.forEach(function (b) {
          b.innerHTML = '<i class="fa-solid fa-xmark me-1"></i> ' + t('common.saveFailed', 'Failed');
          b.disabled = false;
          setTimeout(function () { b.innerHTML = b.getAttribute('data-label') || t('common.save', 'Save Changes'); }, 2000);
        });
      }
      if (!quiet) showToast(t('common.networkError', 'Network error'), 'error');
    });
}
window.applyConfigToUI = applyConfigToUI;
window.waAiLoadConfig = waAiLoadConfig;
window.waAiSaveConfig = waAiSaveConfig;

/* ============================================================
   CATALOG - universal sellable items (Products & Services)
   ------------------------------------------------------------
   Rich item model (works for ANY business type):
     { id, name: { en, id }, description, price, currency,
       type: one of the Universal Primitives (SELLING_PRIMITIVES),
       imageUrl, active, sortOrder, paymentUrl? }
   • name.id falls back to name.en when empty.
   • price may be a number (formatted by currency) or a legacy
     display string (e.g. "Rp 1.499.000") - shown verbatim.
   • paymentUrl = optional gateway-hosted Payment Link created
     in the CLIENT'S OWN Stripe/Midtrans dashboard (SOP Section 2.3
     Mode A). When set, "send payment link" uses this real URL.
   • Type CHOICES (filter chips + edit select) are filtered to the
     selling modes enabled for this client - items whose type is
     currently disabled keep rendering (never hidden/deleted).

   PERSISTENCE: saved through POST /api/admin/client-bot-config
   (engine stores product_catalog verbatim - REAL backend).
   A dedicated REST API is proposed but not required:
   docs/ENGINE-API-GAPS.proai.md Section 3.1.
   ============================================================ */
var SELLING_TYPE_ICONS = {
  product: 'fa-box-open',
  service: 'fa-hand-holding-heart',
  booking: 'fa-calendar-check',
  package: 'fa-cubes',
  membership: 'fa-id-card',
  rental: 'fa-key',
  voucher: 'fa-ticket'
};
var CATALOG_TYPES = SELLING_TYPE_IDS.slice();
var CURRENCY_OPTIONS = ['IDR', 'USD', 'EUR', 'GBP', 'AUD', 'SGD', 'MYR', 'CAD', 'JPY', 'NZD', 'CHF', 'HKD', 'AED', 'BRL', 'MXN', 'PLN', 'SEK', 'NOK', 'DKK', 'THB', 'ZAR'];
var catalogState = [];
var catalogDirty = false;
var catalogClearedByUser = false;
var catalogFilter = { q: '', type: 'all', category: 'all', stock: 'all', active: 'all', refund: 'all' };
var catalogSort = { col: 'default', dir: 'asc' };
var catCurrentOpenHeaderCol = null;
var catalogViewMode = (function() {
  try {
    var saved = localStorage.getItem('cat_view_mode');
    if (saved === 'cards' || saved === 'table') return saved;
  } catch (e) {}
  return 'table';
})();
var catalogPage = 1;
var catalogPageSize = 25;
var catalogSelectMode = false;
var catalogSelected = {};
var catalogDragIndex = null;

/* ---------- SELLING MODES (per active business module) ----------
   config.selling.modes / config.sellingModes (engine, real persistence)
   selects which of the ACTIVE MODULE's declared sellingModes are
   enabled. The engine serves selling:null for legacy (unconfigured)
   clients -> treated as ALL of the module's modes enabled. */
function getModuleSellingModes(moduleId) {
  var mod = DASH_MODULE_REGISTRY[moduleId || activeModuleId];
  var declared = mod && Array.isArray(mod.sellingModes) ? mod.sellingModes : ALL_SELLING_TAXONOMY;
  var clean = sanitizeSellingModes(declared);
  return clean.length ? clean : ALL_SELLING_TAXONOMY.slice();
}
function getConfiguredSellingModes() {
  // Engine canonical field: sellingModes (array of ids, null when unconfigured)
  if (waAiConfig && Array.isArray(waAiConfig.sellingModes)) return sanitizeSellingModes(waAiConfig.sellingModes);
  var selling = waAiConfig ? waAiConfig.selling : undefined;
  if (selling === null || selling === undefined) return null; // legacy -> all enabled
  var m = selling.modes;
  if (m && typeof m === 'object') {
    // Explicit boolean map (set by operator/build console) - honor verbatim.
    return ALL_SELLING_TAXONOMY.filter(function (id) { return m[id] === true; });
  }
  return null;
}
function getEnabledSellingModes(moduleId) {
  var declared = getModuleSellingModes(moduleId);
  var conf = getConfiguredSellingModes();
  if (!conf) {
    return declared.filter(function (id) { return SELLING_TYPE_IDS.indexOf(id) !== -1; });
  }
  var enabled = declared.filter(function (id) { return conf.indexOf(id) !== -1; });
  return enabled;
}

/* Canonical 3 Universal Primitives + Bundle model (law 2026-09-04):
   Product (inventory/goods) · Booking (time slot/service) · Pass (access/membership/voucher).
   Package is a flexible bundle combining any offerings.
   Legacy types map safely onto them. */
var SELLING_TYPE_CANON = {
  product: 'product',
  booking: 'booking',
  service: 'booking',
  pass: 'pass',
  membership: 'pass',
  rental: 'booking',
  voucher: 'pass',
  package: 'package'
};
var SELLING_TYPE_LABELS = {
  product: 'Product',
  booking: 'Service',
  pass: 'Pass',
  package: 'Bundle'
};
var SELLING_TYPE_LABELS_ID = {
  product: 'Produk',
  booking: 'Booking & Layanan',
  pass: 'Pass & Akses',
  package: 'Paket Bundle'
};
function getSellingTypeLabel(mode) {
  var isId = document.documentElement.lang === 'id';
  var labels = isId ? SELLING_TYPE_LABELS_ID : SELLING_TYPE_LABELS;
  var canon = SELLING_TYPE_CANON[mode] || mode;
  return labels[canon] || t('catalog.type.' + canon, canon);
}
window.getSellingTypeLabel = getSellingTypeLabel;

/* Rebuild the catalog type filter chips + the edit-modal type select
   from the currently enabled selling modes. */
function renderCatalogTypeControls() {
  var enabled = getEnabledSellingModes(activeModuleId);
  var chips = $('catalog-type-chips');
  if (chips) {
    var modeIcons = {
      product: 'fa-box-open',
      booking: 'fa-calendar-check',
      pass: 'fa-id-card',
      package: 'fa-cubes'
    };
    var seen = {};
    var canonModes = enabled.map(function (m) { return SELLING_TYPE_CANON[m] || m; }).filter(function (c) {
      if (seen[c]) return false; seen[c] = true; return true;
    });
    // Universal availability: Bundles & Passes are core primitives and must never be hidden
    if (canonModes.indexOf('pass') === -1) canonModes.push('pass');
    if (canonModes.indexOf('package') === -1) canonModes.push('package');
    var html = '<button class="filter-chip' + (catalogFilter.type === 'all' ? ' active' : '') + '" onclick="catSetTypeFilter(\'all\', this)" id="cat-filter-chip-all">' + esc(t('catalog.filterAllTypes', 'All Types')) + '</button>';
    canonModes.forEach(function (mode) {
      var iconClass = modeIcons[mode] || 'fa-box-open';
      var dataGating = (mode === 'package' || mode === 'pass') ? '' : ' data-selling-modes="' + esc(mode) + '"';
      html += '<button class="filter-chip' + (catalogFilter.type === mode ? ' active' : '') + '" onclick="catSetTypeFilter(\'' + mode + '\', this)" id="cat-filter-chip-' + mode + '"' + dataGating + '><i class="fa-solid ' + iconClass + '"></i> ' + esc(getSellingTypeLabel(mode)) + '</button>';
    });
    chips.innerHTML = html;
    if (catalogFilter.type !== 'all' && canonModes.indexOf(catalogFilter.type) === -1) {
      catalogFilter.type = 'all';
      waAiRenderCatalog();
    }
  }
  var sel = $('cat-edit-type');
  if (sel) {
    var cur = sel.value;
    var seenSel = {};
    var canonOpts = enabled.map(function (m) { return SELLING_TYPE_CANON[m] || m; }).filter(function (c) {
      if (seenSel[c]) return false; seenSel[c] = true; return true;
    });
    sel.innerHTML = canonOpts.map(function (mode) {
      return '<option value="' + mode + '">' + esc(getSellingTypeLabel(mode)) + '</option>';
    }).join('');
    if (canonOpts.indexOf(cur) !== -1) sel.value = cur;
  }
}

