function resolveCurrencyFromPhone(phone) {
  if (!phone) return null;
  var digits = String(phone).replace(/[^0-9]/g, '');
  if (!digits) return null;
  if (digits.startsWith('00')) digits = digits.substring(2);
  if (digits.startsWith('011') && digits.length > 3) digits = digits.substring(3);
  if (digits.startsWith('0')) return 'IDR'; // local Indonesian trunk
  for (var len = Math.min(4, digits.length); len >= 1; len--) {
    var prefix = digits.substring(0, len);
    if (DIAL_CODE_CURRENCIES[prefix]) return DIAL_CODE_CURRENCIES[prefix];
  }
  return null;
}

function defaultCurrency() {
  if (typeof window !== 'undefined' && window.location && window.location.search) {
    try {
      var sp = new URLSearchParams(window.location.search);
      var qCur = sp.get('currency');
      if (qCur) return String(qCur).trim().toUpperCase();
      var qCountry = sp.get('country') || sp.get('countryCode');
      if (qCountry && COUNTRY_BASE_CURRENCIES[qCountry.toUpperCase()]) return COUNTRY_BASE_CURRENCIES[qCountry.toUpperCase()];
    } catch (_) {}
  }
  if (typeof waAiConfig !== 'undefined' && waAiConfig && waAiConfig.currency) return String(waAiConfig.currency).trim().toUpperCase();
  if (typeof currentClientConfig !== 'undefined' && currentClientConfig && currentClientConfig.currency) return String(currentClientConfig.currency).trim().toUpperCase();
  if (window.CLIENT_CONFIG && window.CLIENT_CONFIG.currency) return String(window.CLIENT_CONFIG.currency).trim().toUpperCase();
  if (window.__dash_session_data && window.__dash_session_data.currency) return String(window.__dash_session_data.currency).trim().toUpperCase();

  var cCode = (typeof waAiConfig !== 'undefined' && waAiConfig && waAiConfig.countryCode) ||
              (typeof currentClientConfig !== 'undefined' && currentClientConfig && currentClientConfig.countryCode) ||
              (window.CLIENT_CONFIG && window.CLIENT_CONFIG.countryCode) ||
              (window.__dash_session_data && window.__dash_session_data.countryCode) || '';
  if (cCode) {
    cCode = String(cCode).trim().toUpperCase();
    if (COUNTRY_BASE_CURRENCIES[cCode]) return COUNTRY_BASE_CURRENCIES[cCode];
  }

  var phoneCur = resolveCurrencyFromPhone(waAiConfig && (waAiConfig.phone || waAiConfig.whatsappNumber));
  if (phoneCur) return phoneCur;
  var gw = (typeof getConfiguredGateway === 'function') ? getConfiguredGateway() : null;
  if (gw === 'midtrans') return 'IDR';
  var isIndonesian = (typeof waAiConfig !== 'undefined' && waAiConfig && (waAiConfig.primaryLanguage === 'id' || (waAiConfig.languages && waAiConfig.languages.primary === 'id')));
  return isIndonesian ? 'IDR' : 'USD';
}
window.defaultCurrency = defaultCurrency;

function normalizeCatalogItem(item, i) {
  item = item || {};
  var name = item.name;
  if (typeof name === 'string') name = { en: name, id: '' };
  name = { en: (name && name.en) || '', id: (name && name.id) || '' };
  var rawType = item.type;
  var canonType = SELLING_TYPE_CANON[rawType] || rawType;
  var type = (CATALOG_TYPES.indexOf(canonType) !== -1) ? canonType : 'product';
  var catVal = (item.category && typeof item.category === 'string' && item.category.trim()) ? item.category.trim() : (item.category || 'General');
  return {
    id: item.id || ('item-' + Date.now() + '-' + i),
    name: name,
    description: item.description || '',
    category: catVal,
    price: (item.price === 0 || item.price) ? item.price : '',
    currency: CURRENCY_OPTIONS.indexOf(item.currency) !== -1 ? item.currency : defaultCurrency(),
    type: type,
    imageUrl: item.imageUrl || '',
    sku: item.sku || '',
    stock: item.stock !== undefined ? item.stock : null,
    active: item.active !== false,
    sortOrder: item.sortOrder != null ? item.sortOrder : i,
    paymentUrl: item.paymentUrl || '',
    payToBook: item.payToBook === true,
    duration: item.duration != null ? item.duration : null,
    sessions: item.sessions != null ? item.sessions : null,
    validity: item.validity != null ? item.validity : null,
    voucherCode: item.voucherCode || '',
    requiresDelivery: (type === 'product' || type === 'package') ? (item.requiresDelivery === true) : false,
    freeDelivery: (type === 'product' || type === 'package') ? (item.freeDelivery === true) : false,
    bundleItems: Array.isArray(item.bundleItems) ? item.bundleItems : [],
    passFlavor: item.passFlavor || (item.type === 'membership' ? 'membership' : (item.type === 'rental' ? 'rental' : (item.type === 'voucher' ? 'voucher' : ((item.sessions != null && item.sessions !== '') ? 'credit_pack' : 'membership')))),
    stationBinding: item.stationBinding || 'any',
    originalTotal: item.originalTotal != null ? item.originalTotal : null,
    savingsAmount: item.savingsAmount != null ? item.savingsAmount : null,
    savingsPercent: item.savingsPercent != null ? item.savingsPercent : null,
    refundPolicy: (item.refundPolicy === 'none' || item.refundPolicy === 'partial') ? item.refundPolicy : 'full',
    refundWindowHours: item.refundWindowHours != null && !isNaN(Number(item.refundWindowHours)) ? Number(item.refundWindowHours) : 24,
    refundFeePercent: item.refundFeePercent != null && !isNaN(Number(item.refundFeePercent)) ? Number(item.refundFeePercent) : 0,
    refundNoticeText: item.refundNoticeText || ''
  };
}

function catItemName(item) {
  if (typeof item.name === 'string') return item.name || t('catalog.untitled', 'Untitled item');
  var lang = document.documentElement.lang === 'id' ? 'id' : 'en';
  return (item.name && (item.name[lang] || item.name.en || item.name.id)) || t('catalog.untitled', 'Untitled item');
}
function catItemNameBoth(item) {
  if (typeof item.name === 'string') return { en: item.name, id: item.name };
  var en = (item.name && item.name.en) || (typeof item.name === 'string' ? item.name : '');
  var id = (item.name && item.name.id) || (typeof item.name === 'string' ? item.name : '');
  return { en: en, id: id || en };
}

var CURRENCY_LOCALES = {
  IDR: 'id-ID',
  EUR: 'nl-NL',
  GBP: 'en-GB',
  USD: 'en-US',
  CAD: 'en-CA',
  AUD: 'en-AU',
  SGD: 'en-SG',
  MYR: 'ms-MY',
  JPY: 'ja-JP',
  NZD: 'en-NZ',
  CHF: 'de-CH',
  HKD: 'zh-HK',
  AED: 'en-AE',
  BRL: 'pt-BR',
  MXN: 'es-MX',
  PLN: 'pl-PL',
  SEK: 'sv-SE',
  NOK: 'nb-NO',
  DKK: 'da-DK',
  THB: 'th-TH',
  ZAR: 'en-ZA',
  INR: 'en-IN'
};

function fmtPrice(price, currency) {
  if (price === '' || price == null) return '-';
  var n = typeof price === 'number' ? price : numericPrice(price, currency);
  if (typeof n === 'number' && !isNaN(n)) {
    var cur = currency || (typeof defaultCurrency === 'function' ? defaultCurrency() : 'IDR');
    var isZeroDec = (cur === 'IDR' || cur === 'JPY' || cur === 'KRW' || cur === 'VND');
    var locale = CURRENCY_LOCALES[cur] || (cur === 'IDR' ? 'id-ID' : (cur === 'EUR' ? 'nl-NL' : 'en-US'));
    try {
      return new Intl.NumberFormat(locale, { style: 'currency', currency: cur, maximumFractionDigits: isZeroDec ? 0 : 2 }).format(n);
    } catch (e) {
      var sym = (typeof getCurrencySymbol === 'function') ? getCurrencySymbol(cur) : cur;
      return sym + ' ' + (isZeroDec ? Math.round(n).toLocaleString() : n.toFixed(2));
    }
  }
  return String(price); // legacy display string, shown verbatim
}
function formatCurrency(amount, currency) {
  return fmtPrice(amount, currency || defaultCurrency());
}
function isNumericPrice(price) {
  if (typeof price === 'number') return true;
  if (price == null || String(price).trim() === '') return false;
  return /^[\d\s.,-]+$/.test(String(price));
}
function numericPrice(price, currency) {
  if (typeof price === 'number') return isNaN(price) ? null : price;
  if (price == null || String(price).trim() === '') return null;
  var s = String(price).trim().replace(/[^\d.,-]/g, '');
  if (!s || s === '-') return null;

  var hasComma = s.indexOf(',') !== -1;
  var hasDot = s.indexOf('.') !== -1;

  if (hasComma && hasDot) {
    var lastComma = s.lastIndexOf(',');
    var lastDot = s.lastIndexOf('.');
    if (lastComma < lastDot) {
      // Anglo: 1,500.50 -> remove comma
      s = s.replace(/,/g, '');
    } else {
      // Continental: 1.500,50 -> remove dot, comma to dot
      s = s.replace(/\./g, '').replace(',', '.');
    }
  } else if (hasComma) {
    var parts = s.split(',');
    if (parts.length > 2) {
      s = s.replace(/,/g, '');
    } else {
      var lastPart = parts[1];
      var cur = (currency || (typeof defaultCurrency === 'function' ? defaultCurrency() : '') || '').toUpperCase();
      if (lastPart.length === 3 && cur !== 'IDR') {
        s = s.replace(/,/g, '');
      } else {
        s = parts[0] + '.' + lastPart;
      }
    }
  } else if (hasDot) {
    var parts = s.split('.');
    if (parts.length > 2) {
      s = s.replace(/\./g, '');
    } else {
      var lastPart = parts[1];
      var hasIdrHint = /\b(rp|idr)\b/i.test(String(price));
      var cur = (currency || (typeof defaultCurrency === 'function' ? defaultCurrency() : '') || '').toUpperCase();
      var isZeroDec = hasIdrHint || (cur === 'IDR' || cur === 'JPY' || cur === 'KRW' || cur === 'VND');
      if (lastPart.length === 3 && (isZeroDec || cur === 'EUR' || hasIdrHint)) {
        s = s.replace(/\./g, '');
      }
    }
  }
  var n = Number(s);
  return isNaN(n) ? null : n;
}

function switchCatSubTab(tabName, el) {
  var container = $('panel-catalog');
  if (!container) return;
  var tabs = container.querySelectorAll('#cat-subtabs-bar .btn-tab');
  if (tabs && tabs.length) {
    tabs.forEach(function (t) {
      var isActive = el ? (t === el) : (t.id === 'cat-tab-' + tabName);
      t.classList.toggle('active', isActive);
      t.setAttribute('aria-selected', isActive ? 'true' : 'false');
      t.tabIndex = isActive ? 0 : -1;
    });
  }
  if (el && el.focus) el.focus({ preventScroll: true });

  var panes = container.querySelectorAll('.cat-subpane');
  panes.forEach(function (p) { p.style.display = 'none'; });

  var targetPane = $('cat-pane-' + tabName);
  if (targetPane) targetPane.style.display = 'block';

  if (tabName === 'items') {
    if (typeof waAiRenderCatalog === 'function') waAiRenderCatalog();
  } else if (tabName === 'promos') {
    if (typeof renderPromoList === 'function') renderPromoList();
  } else if (tabName === 'docs') {
    if (typeof renderDocList === 'function') renderDocList();
  } else if (tabName === 'analytics') {
    if (typeof renderCatalogAnalytics === 'function') renderCatalogAnalytics();
  }

  // Two-way sidebar sub-item sync
  document.querySelectorAll('#nav-group-catalog .nav-sub-item').forEach(function (s) {
    s.classList.toggle('active', s.id === 'nav-sub-cat-' + tabName);
  });
}
window.switchCatSubTab = switchCatSubTab;

// Open-design ARIA tablist: arrow-key navigation between the 4 catalog sub-tabs
function catTablistKeydown(e) {
  if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight' && e.key !== 'Home' && e.key !== 'End') return;
  var bar = $('cat-subtabs-bar');
  if (!bar) return;
  var tabs = Array.prototype.slice.call(bar.querySelectorAll('.btn-tab'));
  if (!tabs.length) return;
  var idx = tabs.indexOf(document.activeElement);
  if (idx === -1) idx = tabs.findIndex(function (t) { return t.classList.contains('active'); });
  var next = idx;
  if (e.key === 'ArrowRight') next = (idx + 1) % tabs.length;
  if (e.key === 'ArrowLeft') next = (idx - 1 + tabs.length) % tabs.length;
  if (e.key === 'Home') next = 0;
  if (e.key === 'End') next = tabs.length - 1;
  e.preventDefault();
  var target = tabs[next];
  if (target) target.click();
}
window.catTablistKeydown = catTablistKeydown;

// Helper: derive physical or virtual bundle stock info across catalog views & analytics
function getCatalogItemStockInfo(item, catalog) {
  if (!item) return { stock: null, isTracked: false, isBundle: false, bottleneck: null, bottleneckReason: null };
  var catList = (catalog && Array.isArray(catalog)) ? catalog : (typeof catalogState !== 'undefined' && Array.isArray(catalogState) ? catalogState : []);
  var itemType = item.type || 'product';
  var isBundleType = itemType === 'package' || itemType === 'bundle' || (Array.isArray(item.bundleItems) && item.bundleItems.length > 0);

  // Deactivated Item Law: Inactive item or bundle cannot be offered or purchased
  if (item.active === false) {
    var inactName = catItemName(item);
    return {
      stock: 0,
      isTracked: true,
      isBundle: isBundleType,
      bottleneck: inactName,
      bottleneckItem: inactName,
      bottleneckReason: 'inactive_component'
    };
  }

  if (itemType === 'product' || (!item.type && item.stock !== undefined && item.stock !== null && item.stock !== '')) {
    if (item.stock !== undefined && item.stock !== null && String(item.stock).trim() !== '' && !isNaN(Number(item.stock))) {
      var s = Math.max(0, Number(item.stock));
      return {
        stock: s,
        isTracked: true,
        isBundle: false,
        bottleneck: s <= 0 ? catItemName(item) : null,
        bottleneckItem: catItemName(item),
        bottleneckReason: s <= 0 ? 'out_of_stock' : null
      };
    }
    return { stock: null, isTracked: false, isBundle: false, bottleneck: null, bottleneckReason: null };
  }

  if (isBundleType) {
    var bundleItems = Array.isArray(item.bundleItems) ? item.bundleItems : [];
    if (bundleItems.length === 0) {
      return { stock: null, isTracked: false, isBundle: true, bottleneck: null, bottleneckReason: null };
    }
    var minCombos = Infinity;
    var bottleneckName = null;
    var anyTracked = false;
    for (var b = 0; b < bundleItems.length; b++) {
      var bi = bundleItems[b];
      var bQty = Math.max(1, Number(bi.qty) || 1);
      var comp = catList.find(function (c) {
        return c && (
          (bi.itemId && (String(c.id) === String(bi.itemId))) ||
          (bi.id && (String(c.id) === String(bi.id))) ||
          (bi.name && c.name && (
            (typeof c.name === 'string' && typeof bi.name === 'string' && c.name.trim().toLowerCase() === bi.name.trim().toLowerCase()) ||
            (catItemName(c).toLowerCase() === String(bi.name).trim().toLowerCase())
          ))
        );
      });
      if (!comp) {
        var missingName = bi.name || 'Component item';
        return {
          stock: 0,
          isTracked: true,
          isBundle: true,
          bottleneck: missingName,
          bottleneckItem: missingName,
          bottleneckReason: 'missing_component'
        };
      }
      if (comp.active === false) {
        var compInactName = catItemName(comp) || bi.name || 'Component item';
        return {
          stock: 0,
          isTracked: true,
          isBundle: true,
          bottleneck: compInactName,
          bottleneckItem: compInactName,
          bottleneckReason: 'inactive_component'
        };
      }
      if (comp.stock !== undefined && comp.stock !== null && String(comp.stock).trim() !== '' && !isNaN(Number(comp.stock))) {
        anyTracked = true;
        var compStock = Math.max(0, Number(comp.stock));
        var combos = Math.floor(compStock / bQty);
        if (combos < minCombos) {
          minCombos = combos;
          bottleneckName = catItemName(comp) || bi.name;
        }
      }
    }
    if (!anyTracked) {
      return { stock: null, isTracked: false, isBundle: true, bottleneck: null, bottleneckReason: null };
    }
    var finalCombos = isFinite(minCombos) ? minCombos : null;
    return {
      stock: finalCombos,
      isTracked: true,
      isBundle: true,
      bottleneck: (finalCombos !== null && finalCombos <= 0) ? bottleneckName : null,
      bottleneckItem: bottleneckName,
      bottleneckReason: (finalCombos !== null && finalCombos <= 0) ? 'out_of_stock' : null
    };
  }
  return { stock: null, isTracked: false, isBundle: false, bottleneck: null, bottleneckReason: null };
}
window.getCatalogItemStockInfo = getCatalogItemStockInfo;

