function catGetDistinctCategories(items) {
  var cats = [];
  var seen = {};
  if (!Array.isArray(items)) return cats;
  items.forEach(function (it) {
    var c = (it && it.category && typeof it.category === 'string') ? it.category.trim() : '';
    if (c && !seen[c]) {
      seen[c] = true;
      cats.push(c);
    }
  });
  cats.sort(function (a, b) { return a.localeCompare(b); });
  return cats;
}

function catGetLowStockThreshold(category) {
  var catName = (category && typeof category === 'string') ? category.trim() : '';
  if (typeof waAiConfig !== 'undefined' && waAiConfig) {
    if (catName && waAiConfig.categoryLowStockThresholds && typeof waAiConfig.categoryLowStockThresholds[catName] === 'number') {
      return waAiConfig.categoryLowStockThresholds[catName];
    }
    if (typeof waAiConfig.defaultLowStockThreshold === 'number') {
      return waAiConfig.defaultLowStockThreshold;
    }
  }
  return 5;
}
window.catGetLowStockThreshold = catGetLowStockThreshold;

function catOpenThresholdModal() {
  var modal = $('modal-cat-thresholds');
  if (!modal) return;

  var cfg = (typeof waAiConfig !== 'undefined' && waAiConfig) ? waAiConfig : {};
  var globalThresh = (typeof cfg.defaultLowStockThreshold === 'number') ? cfg.defaultLowStockThreshold : 5;
  var globalInp = $('cat-thresh-global-input');
  if (globalInp) globalInp.value = globalThresh;

  var items = (typeof catalogState !== 'undefined' && Array.isArray(catalogState)) ? catalogState : [];
  var distinctCategories = catGetDistinctCategories(items);
  var countEl = $('cat-thresh-category-count');
  if (countEl) {
    countEl.textContent = distinctCategories.length + (distinctCategories.length === 1 ? ' category' : ' categories');
  }

  var container = $('cat-thresholds-table-body');
  if (container) {
    if (distinctCategories.length === 0) {
      container.innerHTML =
        '<div style="text-align:center;padding:2rem 1rem;color:var(--text-muted);font-size:0.8125rem;">' +
          '<i class="fa-solid fa-tags" style="font-size:1.5rem;margin-bottom:0.5rem;display:block;opacity:0.5;"></i>' +
          'No distinct categories detected in catalog.<br>' +
          '<span style="font-size:0.75rem;">All offerings will use the global default threshold (' + globalThresh + ' units).</span>' +
        '</div>';
    } else {
      var overrides = cfg.categoryLowStockThresholds || {};
      var html = '';
      distinctCategories.forEach(function (catName) {
        var catCount = items.filter(function (it) {
          return it.category && it.category.trim() === catName;
        }).length;
        var existingVal = (typeof overrides[catName] === 'number') ? overrides[catName] : '';
        html +=
          '<div class="cat-thresh-row">' +
            '<div style="display:flex;align-items:center;gap:0.625rem;min-width:0;flex:1;">' +
              '<div style="width:28px;height:28px;border-radius:var(--radius-xs);background:var(--bg-input);border:1px solid var(--border-color);display:flex;align-items:center;justify-content:center;font-size:0.75rem;flex-shrink:0;">' +
                '<i class="fa-solid fa-tag text-teal"></i>' +
              '</div>' +
              '<div style="min-width:0;flex:1;">' +
                '<div style="font-size:0.8125rem;font-weight:600;color:var(--text-main);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="' + esc(catName) + '">' + esc(catName) + '</div>' +
                '<div style="font-size:0.6875rem;color:var(--text-muted);">' + catCount + (catCount === 1 ? ' offering' : ' offerings') + '</div>' +
              '</div>' +
            '</div>' +
            '<div style="display:flex;align-items:center;gap:0.5rem;flex-shrink:0;">' +
              '<input type="number" min="1" max="999" class="form-input cat-thresh-input font-mono" data-cat="' + esc(catName) + '" value="' + esc(existingVal) + '" placeholder="' + globalThresh + '" style="width:75px;padding:0.35rem 0.5rem;text-align:center;font-weight:700;">' +
              '<span style="font-size:0.75rem;color:var(--text-muted);">units</span>' +
            '</div>' +
          '</div>';
      });
      container.innerHTML = html;
    }
  }

  modal.classList.add('open');
}
window.catOpenThresholdModal = catOpenThresholdModal;

function catCloseThresholdModal() {
  var modal = $('modal-cat-thresholds');
  if (modal) modal.classList.remove('open');
}
window.catCloseThresholdModal = catCloseThresholdModal;

function catSaveCategoryThresholds() {
  if (typeof waAiConfig === 'undefined' || !waAiConfig) {
    window.waAiConfig = {};
  }
  var globalInp = $('cat-thresh-global-input');
  var globalVal = globalInp ? parseInt(globalInp.value, 10) : 5;
  if (isNaN(globalVal) || globalVal < 1) globalVal = 5;

  waAiConfig.defaultLowStockThreshold = globalVal;
  waAiConfig.categoryLowStockThresholds = {};

  var rows = document.querySelectorAll('.cat-thresh-input');
  rows.forEach(function (inp) {
    var cat = inp.getAttribute('data-cat');
    var val = parseInt(inp.value, 10);
    if (cat && !isNaN(val) && val >= 1) {
      waAiConfig.categoryLowStockThresholds[cat] = val;
    }
  });

  if (typeof markCatalogDirty === 'function') {
    markCatalogDirty(true);
  }

  catCloseThresholdModal();
  renderCatalogAnalytics();
  if (typeof showToast === 'function') {
    showToast('Inventory safe stock thresholds saved successfully', 'success');
  }
}
window.catSaveCategoryThresholds = catSaveCategoryThresholds;

// Global keyboard shortcuts and click dismissal for catalog insight controls
document.addEventListener('keydown', function (e) {
  if (e.key === '/' && !e.ctrlKey && !e.metaKey && !e.altKey) {
    var activeTag = (document.activeElement && document.activeElement.tagName) ? document.activeElement.tagName.toLowerCase() : '';
    if (activeTag === 'input' || activeTag === 'textarea' || activeTag === 'select' || (document.activeElement && document.activeElement.isContentEditable)) {
      return;
    }
    var pane = $('cat-pane-analytics');
    var inp = $('cat-insight-search-input');
    if (inp && pane && pane.style.display !== 'none') {
      e.preventDefault();
      inp.focus();
      inp.select();
    }
  } else if (e.key === 'Escape') {
    if (typeof catCloseHeaderPopover === 'function') catCloseHeaderPopover();
    catInsightCloseSortDropdown();
    catInsightCloseCategoryDropdown();
    catCloseThresholdModal();
    var inp = $('cat-insight-search-input');
    if (document.activeElement === inp) {
      if (catInsightSearchQuery) {
        catInsightClearSearch();
      } else {
        inp.blur();
      }
    }
  }
});

document.addEventListener('click', function (e) {
  var catPopover = $('cat-header-popover');
  if (catPopover && catPopover.style.display !== 'none') {
    if (!catPopover.contains(e.target) && !e.target.closest('.cat-th-interactive')) {
      if (typeof catCloseHeaderPopover === 'function') catCloseHeaderPopover();
    }
  }
  var sortComp = $('cat-insight-sort-custom');
  if (sortComp && !sortComp.contains(e.target)) {
    catInsightCloseSortDropdown();
  }
  var catComp = $('cat-insight-category-custom');
  if (catComp && !catComp.contains(e.target)) {
    catInsightCloseCategoryDropdown();
  }
});

window.addEventListener('scroll', function () {
  var catPopover = $('cat-header-popover');
  if (catPopover && catPopover.style.display !== 'none') {
    if (typeof catCloseHeaderPopover === 'function') catCloseHeaderPopover();
  }
}, { passive: true, capture: true });


