function updatePersonaWordCounter() {
  var area = $('custom-rules-textarea');
  var counter = $('persona-word-counter') || $('persona-char-token-counter');
  if (!area || !counter) return;
  var text = area.value.trim();
  var words = text ? text.split(/\s+/).filter(Boolean).length : 0;
  counter.textContent = words + ' / 100 words';

  if (words > 100) {
    counter.style.color = 'var(--status-red)';
    counter.style.fontWeight = '700';
  } else if (words >= 75) {
    counter.style.color = 'var(--status-amber)';
    counter.style.fontWeight = '600';
  } else {
    counter.style.color = 'var(--text-muted)';
    counter.style.fontWeight = '400';
  }
}
