function formatWeeklyScheduleSummary() {
  if (typeof bkGetWeeklySchedule !== 'function') return 'Mon–Sat: 09:00 – 18:00 · Sun: Closed';
  var schedule = bkGetWeeklySchedule();
  if (!Array.isArray(schedule) || !schedule.length) return 'Mon–Sat: 09:00 – 18:00 · Sun: Closed';

  var groups = [];
  var currentGroup = null;

  schedule.forEach(function (item) {
    var status = item.open ? ((item.start || '09:00') + ' – ' + (item.end || '18:00')) : 'Closed';
    if (currentGroup && currentGroup.status === status) {
      currentGroup.endDay = item.day;
      currentGroup.count++;
    } else {
      if (currentGroup) groups.push(currentGroup);
      currentGroup = { startDay: item.day, endDay: item.day, status: status, count: 1 };
    }
  });
  if (currentGroup) groups.push(currentGroup);

  return groups.map(function (g) {
    var daySpan = g.count === 1 ? g.startDay : (g.startDay + '–' + g.endDay);
    return daySpan + ': ' + g.status;
  }).join(' · ');
}
window.formatWeeklyScheduleSummary = formatWeeklyScheduleSummary;

function renderAboutScheduleSummary() {
  var el = $('about-live-schedule-text');
  if (!el) return;
  el.textContent = formatWeeklyScheduleSummary();
}
window.renderAboutScheduleSummary = renderAboutScheduleSummary;

/* ============================================================
   VIDEO UPLOAD (preserved integration)
   ============================================================ */
function parseMp4Fps(arrayBuffer) {
  var view = new DataView(arrayBuffer);
  var len = arrayBuffer.byteLength;
  var timescale = 0;
  var sampleDelta = 0;
  for (var i = 0; i < Math.min(len - 32, 10 * 1024 * 1024); i++) {
    if (view.getUint8(i) === 109 && view.getUint8(i + 1) === 100 && view.getUint8(i + 2) === 104 && view.getUint8(i + 3) === 100) {
      var version = view.getUint8(i + 4);
      var offset = version === 0 ? i + 12 : i + 20;
      if (offset + 4 <= len) { timescale = view.getUint32(offset); break; }
    }
  }
  for (var j = 0; j < Math.min(len - 24, 10 * 1024 * 1024); j++) {
    if (view.getUint8(j) === 115 && view.getUint8(j + 1) === 116 && view.getUint8(j + 2) === 116 && view.getUint8(j + 3) === 115) {
      if (j + 16 + 4 <= len) {
        var entryCount = view.getUint32(j + 8);
        if (entryCount > 0) { sampleDelta = view.getUint32(j + 16); break; }
      }
    }
  }
  if (timescale > 0 && sampleDelta > 0) return Math.round(timescale / sampleDelta);
  return null;
}

function validateVideoDimensionsAndFps(file, expectedRatio, expectedFps) {
  return new Promise(function (resolve) {
    var video = document.createElement('video');
    video.preload = 'metadata';
    video.src = URL.createObjectURL(file);
    video.onloadedmetadata = function () {
      URL.revokeObjectURL(video.src);
      var width = video.videoWidth;
      var height = video.videoHeight;
      var ratio = width / height;
      var ratioValid = false;
      if (expectedRatio === '16:9') ratioValid = Math.abs(ratio - (16 / 9)) < 0.05;
      else if (expectedRatio === '1:1') ratioValid = Math.abs(ratio - 1.0) < 0.05;
      if (!ratioValid) {
        resolve({ success: false, error: 'Invalid aspect ratio. Expected ' + expectedRatio + ' (detected ' + width + 'x' + height + ').' });
        return;
      }
      var reader = new FileReader();
      reader.onload = function (evt) {
        var fps = parseMp4Fps(evt.target.result);
        if (fps !== null && fps !== expectedFps) {
          resolve({ success: false, error: 'Invalid frame rate. Expected exactly ' + expectedFps + ' FPS (detected ' + fps + ' FPS).' });
          return;
        }
        resolve({ success: true });
      };
      reader.onerror = function () { resolve({ success: false, error: 'Failed to read video file headers.' }); };
      reader.readAsArrayBuffer(file);
    };
    video.onerror = function () {
      URL.revokeObjectURL(video.src);
      resolve({ success: false, error: 'Invalid or corrupt video file.' });
    };
  });
}



