  currentDensityNorm = norm;
  var isDark = document.documentElement.getAttribute('data-theme') !== 'light';
  var palette = typeof getOverviewThemePalette === 'function' ? getOverviewThemePalette(isDark) : {
    teal: '#0E9AA7', gold: '#E2B13C', green: '#10B981', purple: '#8B5CF6',
    fillOpacityFrom: 0.35, fillOpacityTo: 0.05, gridBorder: isDark ? 'rgba(255,255,255,0.08)' : 'rgba(15,23,42,0.08)', axisColor: isDark ? '#94a3b8' : '#475569'
  };

  if (selectedAnalyticsDay) {
    var selIdx = norm.dateKeys.indexOf(selectedAnalyticsDay);
    var selLabel = selIdx !== -1 ? norm.dateLabels[selIdx] : selectedAnalyticsDay;
    if (kicker) kicker.innerHTML = '<i class="fa-solid fa-filter text-teal"></i> FILTERED ACTIVITY: ' + esc(selLabel).toUpperCase();
    if (headline) headline.innerHTML = 'Showing activity for <strong>' + esc(selLabel) + '</strong>. Click bar again or <a href="javascript:void(0)" onclick="clearAnalyticsDayFilter()" style="color:var(--accent);text-decoration:underline;">clear filter</a> to view full ' + esc(rangeLabel) + '.';
  } else {
    if (kicker) kicker.innerHTML = '<i class="fa-solid fa-chart-column text-teal"></i> MULTI-CHANNEL VOLUME DENSITY &amp; ACTIVITY (' + esc(rangeLabel) + ')';
    var totalVol = norm.totals.reduce(function (acc, d) { return acc + d; }, 0);
    if (totalVol === 0) {
      if (headline) headline.textContent = 'No customer activity recorded in the selected ' + rangeLabel + ' period.';
    } else {
      if (headline) headline.textContent = 'Daily engagement distribution across Inbound Inquiries, Bookings, and Paid Orders. Click any bar to inspect daily activity.';
    }
  }

  wrap.innerHTML = '<div id="an-apex-volume-chart" style="width:100%;min-height:300px;"></div>';
  var chartContainer = $('an-apex-volume-chart');
  if (!chartContainer || typeof window.ApexCharts === 'undefined') return;

