function bkRenderServicesStrip() {
  var strip = $('bk-services-strip');
  if (!strip) return;
  var services = (typeof catalogState !== 'undefined' && Array.isArray(catalogState))
    ? catalogState.filter(function (it) { return it && it.active !== false && (it.type === 'service' || it.type === 'booking'); })
    : [];

  if (!services.length) {
    var dur = (typeof bkEffectiveDuration === 'function') ? bkEffectiveDuration() : 30;
    strip.innerHTML = '<div style="font-size:0.75rem;color:var(--text-muted);display:flex;align-items:center;gap:0.5rem;padding:0.4rem 0.625rem;background:var(--bg-input);border-radius:var(--radius-sm);border:1px dashed var(--border-color);width:100%;">' +
      '<i class="fa-solid fa-circle-info text-teal"></i>' +
      '<span>No dedicated services created yet. All appointments use the <strong>Fallback Duration (' + dur + ' min)</strong> below. Click <strong>+ Add Service</strong> above to offer dedicated appointment types with custom durations &amp; pricing.</span>' +
    '</div>';
    return;
  }

  var html = services.map(function (s) {
    var sName = typeof catItemName === 'function' ? catItemName(s) : (s.name || 'Service');
    var dur = Number(s.duration) || Number(s.durationMinutes) || 30;
    var priceStr = (typeof fmtPrice === 'function') ? fmtPrice(s.price, s.currency) : (s.price ? String(s.price) : 'Free');
    var isPay = !!s.payToBook;
    var payBadge = isPay
      ? '<span class="badge badge-teal" style="font-size:0.625rem;padding:0.05rem 0.35rem;display:inline-flex;align-items:center;gap:0.2rem;"><i class="fa-solid fa-lock" style="font-size:0.5625rem;"></i> Pay to Lock</span>'
      : '<span class="badge badge-muted" style="font-size:0.625rem;padding:0.05rem 0.35rem;">Pay on Arrival</span>';
    var skuBadge = s.sku
      ? '<span style="font-family:var(--font-mono);font-size:0.625rem;color:var(--text-muted);background:var(--bg-card);border:1px solid var(--border-color);padding:0.05rem 0.3rem;border-radius:3px;">' + esc(s.sku) + '</span>'
      : '';
    var sid = esc(s.id || '');

    return '<div class="bk-service-pill" onclick="catOpenEdit(\'' + sid + '\')" style="display:inline-flex;align-items:center;gap:0.45rem;padding:0.35rem 0.6rem;background:var(--bg-input);border:1px solid var(--border-color);border-radius:var(--radius-sm);cursor:pointer;user-select:none;transition:border-color 0.15s ease;" title="Click to edit duration, pricing, or pay-to-lock">' +
      '<i class="fa-solid fa-scissors text-teal" style="font-size:0.6875rem;"></i>' +
      '<strong style="font-size:0.75rem;color:var(--text-main);">' + esc(sName) + '</strong>' +
      skuBadge +
      '<span style="font-size:0.6875rem;color:var(--text-muted);font-family:var(--font-mono);">' + dur + 'm</span>' +
      '<span style="font-size:0.6875rem;font-weight:600;color:var(--text-main);font-family:var(--font-mono);">' + priceStr + '</span>' +
      payBadge +
      '<i class="fa-solid fa-pen-to-square text-muted" style="font-size:0.625rem;margin-left:0.15rem;"></i>' +
    '</div>';
  }).join('');

  html += '<button type="button" class="btn-dash btn-outline btn-xs" data-cap="catalog_edit" onclick="catOpenAddService()" style="display:inline-flex;align-items:center;gap:0.3rem;border-style:dashed;padding:0.35rem 0.55rem;font-size:0.6875rem;">' +
    '<i class="fa-solid fa-plus"></i> Add Service' +
  '</button>';

  strip.innerHTML = html;
}
window.bkRenderServicesStrip = bkRenderServicesStrip;


