function bkInitBookingsPanel() {
  if (typeof populateBizTimezoneSelect === 'function') populateBizTimezoneSelect();
  if (typeof bkRenderWeeklySchedule === 'function') bkRenderWeeklySchedule();

  var sel = $('wa-appt-slot-duration');
  if (sel) {
    // Repopulate from the persisted slot duration (law 2026-09-02): the select
    // previously always snapped back to the default 30 on reload, so a saved
    // custom 45 looked lost. Known presets map directly; anything else shows
    // as "Custom…" with its real minutes.
    var savedDur = (typeof waAiConfig !== 'undefined' && waAiConfig.appointmentSlotDuration) ? String(waAiConfig.appointmentSlotDuration) : '';
    var knownOpts = ['15', '20', '30', '45', '60', '90', '120'];
    var savedNum = parseInt(savedDur, 10);
    var row = $('bk-custom-duration-row');
    var ci = $('bk-custom-duration');
    if (knownOpts.indexOf(savedDur) !== -1) {
      sel.value = savedDur;
      bkState.slotDuration = savedNum;
      bkState.customDuration = null;
      if (row) row.style.display = 'none';
    } else if (savedNum > 0) {
      sel.value = 'custom';
      bkState.customDuration = savedNum;
      bkState.slotDuration = savedNum;
      if (row) row.style.display = 'block';
      if (ci) ci.value = savedDur;
    } else {
      sel.value = '30';
      bkState.slotDuration = 30;
      bkState.customDuration = null;
      if (row) row.style.display = 'none';
    }
  }

  var aiToggle = $('bk-ai-booking-toggle');
  if (aiToggle && typeof waAiConfig !== 'undefined') {
    aiToggle.checked = waAiConfig.aiAutoBooking !== false;
  }

  var advSel = $('bk-advance-notice');
  if (advSel && typeof waAiConfig !== 'undefined' && waAiConfig.advanceNoticeMin != null) {
    advSel.value = String(waAiConfig.advanceNoticeMin);
    bkUpdateAdvanceNoticeDisplay(waAiConfig.advanceNoticeMin);
  } else {
    bkUpdateAdvanceNoticeDisplay(120);
  }

  var rem24 = $('bk-remind-24h');
  if (rem24 && typeof waAiConfig !== 'undefined' && waAiConfig.autoReminders) {
    rem24.checked = waAiConfig.autoReminders['24h'] !== false;
  }
  var rem1 = $('bk-remind-1h');
  if (rem1 && typeof waAiConfig !== 'undefined' && waAiConfig.autoReminders) {
    rem1.checked = waAiConfig.autoReminders['1h'] !== false;
  }


  var capInput = $('bk-slot-capacity');
  if (capInput && typeof waAiConfig !== 'undefined') {
    capInput.value = String(waAiConfig.slotCapacity || 1);
  }

  var ttlSel = $('bk-pending-ttl');
  if (ttlSel && typeof waAiConfig !== 'undefined') {
    var ttlVal = waAiConfig.pendingTtlMinutes != null ? String(waAiConfig.pendingTtlMinutes) : '30';
    var ttlOpts = ['15', '30', '60', '120', '1440'];
    var finalTtl = ttlOpts.indexOf(ttlVal) !== -1 ? ttlVal : '30';
    ttlSel.value = finalTtl;
    bkUpdatePendingTtlDisplay(finalTtl);
  } else {
    bkUpdatePendingTtlDisplay(30);
  }

  var restSel = $('bk-rest-buffer');
  if (restSel && typeof waAiConfig !== 'undefined') {
    var restVal = waAiConfig.restBufferMinutes != null ? String(waAiConfig.restBufferMinutes) : '5';
    var restOpts = ['0', '5', '10', '15'];
    restSel.value = restOpts.indexOf(restVal) !== -1 ? restVal : '5';
  }

  bkLoadAppointments();
  if (typeof waAiLoadTimeBlocks === 'function') waAiLoadTimeBlocks();
  if (typeof bkRenderServicesStrip === 'function') bkRenderServicesStrip();
  if (typeof updateBookingCapacityState === 'function') updateBookingCapacityState();
}
