function umOpenBlockSlotModal(opts) {
  if (!dashCan('bookings_manage')) { showToast(t('staff.noPermission', 'You do not have permission for this action.'), 'error'); return; }
  opts = opts || {};
  var m = $('block-slot-modal');
  if (!m) return;

  var cardScope = $('bk-card-block-scope') ? $('bk-card-block-scope').value : 'all';
  var chosenTarget = opts.target || cardScope || 'all';

  if (typeof populateBlockTargetDropdown === 'function') {
    populateBlockTargetDropdown(chosenTarget);
  }

  var todayKey = bkDateKey(new Date());
  var selDate = opts.date || (bkState && bkState.viewDate ? bkDateKey(bkState.viewDate) : todayKey);
  if (selDate < todayKey) selDate = todayKey;
  var selTime = opts.time || '10:00';
  var selDuration = opts.duration || bkEffectiveDuration() || 60;

  var dateInput = $('block-slot-date');
  var startDateInput = $('block-slot-start-date');
  var endDateInput = $('block-slot-end-date');
  var timeInput = $('block-slot-time');
  var endTimeInput = $('block-slot-end-time');
  var durInput = $('block-slot-duration');
  var reasonInput = $('block-slot-reason');
  var weeklyInput = $('block-slot-weekly');

  if (dateInput) {
    dateInput.min = todayKey;
    dateInput.value = selDate;
  }
  if (startDateInput) {
    startDateInput.min = todayKey;
    startDateInput.value = (opts.startDate && opts.startDate >= todayKey) ? opts.startDate : selDate;
  }
  if (endDateInput) {
    endDateInput.min = startDateInput ? startDateInput.value : todayKey;
    endDateInput.value = (opts.endDate && opts.endDate >= todayKey) ? opts.endDate : selDate;
  }
  if (timeInput) timeInput.value = selTime;

  var parts = selTime.split(':');
  var sMin = (parseInt(parts[0], 10) || 10) * 60 + (parseInt(parts[1], 10) || 0);
  var eMin = sMin + selDuration;
  var eH = Math.floor(eMin / 60) % 24;
  var eM = eMin % 60;
  var defEndTime = (eH < 10 ? '0' + eH : String(eH)) + ':' + (eM < 10 ? '0' + eM : String(eM));

  if (endTimeInput) endTimeInput.value = opts.endTime || defEndTime;
  if (durInput) durInput.value = selDuration;
  if (reasonInput) reasonInput.value = opts.reason || '';
  if (weeklyInput) weeklyInput.checked = !!opts.repeatWeekly;

  umSetBlockType(opts.type || 'timespan');
  if (typeof onBlockTimeChanged === 'function') onBlockTimeChanged();
  m.classList.add('open');
}
window.umOpenBlockSlotModal = umOpenBlockSlotModal;
window.openBlockSlotModal = umOpenBlockSlotModal;

function umCloseBlockSlotModal() {
  var m = $('block-slot-modal');
  if (m) {
    m.classList.remove('open');
    var f = m.querySelector('form');
    if (f) f.reset();
  }
}
window.umCloseBlockSlotModal = umCloseBlockSlotModal;
window.closeBlockSlotModal = umCloseBlockSlotModal;
window.closeSlotBlockModal = umCloseBlockSlotModal;

function umSaveBlockedSlot() {
  var r = $('block-slot-reason') ? $('block-slot-reason').value.trim() : '';
  if (!r) {
    showToast('Please enter a reason for blocking time.', 'error');
    return false;
  }

  if (!umState.blockedSlots) umState.blockedSlots = [];
  var beforeCount = umState.blockedSlots.length;
  var targetVal = $('block-slot-target') ? $('block-slot-target').value : 'all';
  var todayKey = bkDateKey(new Date());
  var now = new Date();
  var currentMinutes = now.getHours() * 60 + now.getMinutes();

  if (currentBlockType === 'indefinite') {
    var indefBlock = {
      id: 'blk-' + crypto.randomUUID(),
      type: 'indefinite',
      targetStationId: targetVal,
      date: bkDateKey(new Date()),
      time: '00:00',
      timeSlot: 'Indefinite (OFF)',
      durationMin: 999999,
      reason: r,
      isFullDay: true,
      repeatWeekly: false,
      createdAt: new Date().toISOString()
    };
    umState.blockedSlots.push(indefBlock);

    // Apply maintenance status to target units
    var stations = stationsState.stations || [];
    stations.forEach(function(st) {
      var match = (targetVal === 'all' || targetVal === st.id || targetVal === ('cat:' + (st.area || st.category)));
      if (match) {
        st.status = 'maintenance';
        st.active = false;
      }
    });

    if (typeof bkLogAuditEvent === 'function') {
      bkLogAuditEvent('Block', 'Indefinite block applied', r + ' (Target: ' + targetVal + ')', 'Staff');
    }
    showToast('Indefinite block applied (' + r + '). Target set to Offline.', 'info');
  } else 

  if (currentBlockType === 'timespan') {
    var d = $('block-slot-date') ? $('block-slot-date').value : '';
    var tVal = $('block-slot-time') ? $('block-slot-time').value : '10:00';
    var endTVal = $('block-slot-end-time') ? $('block-slot-end-time').value : '';
    var dur = parseInt(($('block-slot-duration') ? $('block-slot-duration').value : '60') || '60', 10);
    var weekly = $('block-slot-weekly') ? $('block-slot-weekly').checked : false;

    if (!d || !tVal) {
      showToast('Please select date and start time.', 'error');
      return false;
    }
    if (d < todayKey) {
      showToast('Cannot block past dates. Please select today or an upcoming date.', 'error');
      return false;
    }
    var sMin = (parseInt(tVal.split(':')[0], 10) || 0) * 60 + (parseInt(tVal.split(':')[1], 10) || 0);
    if (d === todayKey && sMin < currentMinutes) {
      showToast('Start time has already passed for today. Please select a future time window.', 'error');
      return false;
    }
    if (endTVal) {
      var eMin = (parseInt(endTVal.split(':')[0], 10) || 0) * 60 + (parseInt(endTVal.split(':')[1], 10) || 0);
      if (eMin <= sMin) {
        showToast('End time must be later than start time.', 'error');
        return false;
      }
    }

    var timeSlotStr = endTVal ? (tVal + ' - ' + endTVal) : (tVal + ' (' + dur + 'm)');

    umState.blockedSlots.push({
      id: 'blk-' + crypto.randomUUID(),
      type: 'timespan',
      targetStationId: targetVal,
      date: d,
      time: tVal,
      endTime: endTVal || undefined,
      timeSlot: timeSlotStr,
      durationMin: isNaN(dur) ? 60 : dur,
      reason: r,
      repeatWeekly: weekly,
      createdAt: new Date().toISOString()
    });
    if (typeof bkLogAuditEvent === 'function') {
      bkLogAuditEvent('Block', 'Time window blocked', d + ' @ ' + timeSlotStr + ' (' + r + ')', 'Staff');
    }
    showToast(t('module.universal.slotBlocked', 'Time slot blocked successfully') + ' (' + d + ' @ ' + timeSlotStr + ')', 'success');

  } else if (currentBlockType === 'fullday') {
    var dFull = $('block-slot-date') ? $('block-slot-date').value : '';
    var weeklyFull = $('block-slot-weekly') ? $('block-slot-weekly').checked : false;

    if (!dFull) {
      showToast('Please select a date to block.', 'error');
      return false;
    }
    if (dFull < todayKey) {
      showToast('Cannot block past dates. Please select today or an upcoming date.', 'error');
      return false;
    }

    umState.blockedSlots.push({
      id: 'blk-' + crypto.randomUUID(),
      type: 'fullday',
      targetStationId: targetVal,
      date: dFull,
      time: '00:00',
      timeSlot: 'Full Day',
      durationMin: 1440,
      reason: r,
      isFullDay: true,
      repeatWeekly: weeklyFull,
      createdAt: new Date().toISOString()
    });
    if (typeof bkLogAuditEvent === 'function') {
      bkLogAuditEvent('Block', 'Full day blocked', dFull + ' (' + r + ')', 'Staff');
    }
    showToast('Full day blocked: ' + dFull + ' (' + r + ')', 'success');

  } else if (currentBlockType === 'daterange') {
    var startD = $('block-slot-start-date') ? $('block-slot-start-date').value : '';
    var endD = $('block-slot-end-date') ? $('block-slot-end-date').value : '';

    if (!startD || !endD) {
      showToast('Please select both start and end dates.', 'error');
      return false;
    }
    if (startD < todayKey) {
      showToast('Start date cannot be in the past. Please select today or an upcoming date.', 'error');
      return false;
    }
    if (endD < startD) {
      showToast('End date cannot be earlier than start date.', 'error');
      return false;
    }

    var cur = new Date(startD);
    var end = new Date(endD);
    var count = 0;

    while (cur <= end) {
      var dKey = bkDateKey(cur);
      umState.blockedSlots.push({
        id: 'blk-' + Date.now() + '-' + dKey,
        type: 'fullday',
        targetStationId: targetVal,
        date: dKey,
        time: '00:00',
        timeSlot: 'Full Day',
        durationMin: 1440,
        reason: r,
        isFullDay: true,
        repeatWeekly: false,
        createdAt: new Date().toISOString()
      });
      cur.setDate(cur.getDate() + 1);
      count++;
    }
    if (typeof bkLogAuditEvent === 'function') {
      bkLogAuditEvent('Block', 'Date range blocked', count + ' days: ' + startD + ' to ' + endD + ' (' + r + ')', 'Staff');
    }
    showToast('Date range blocked (' + count + ' days: ' + startD + ' to ' + endD + ')', 'success');
  }

  if (typeof waAiConfig !== 'undefined') {
    waAiConfig.blockedSlots = umState.blockedSlots.slice();
    if (typeof waAiSaveConfig === 'function') waAiSaveConfig(true);
  }

  umCloseBlockSlotModal();
  if (typeof umRenderBlockedSlots === 'function') umRenderBlockedSlots();
  if (typeof bkRenderBlockedSlots === 'function') bkRenderBlockedSlots();
  if (typeof bkRenderTimeline === 'function') bkRenderTimeline();
  if (typeof bkRenderCalendar === 'function') bkRenderCalendar();
  if (typeof renderActiveBlocksShelf === 'function') renderActiveBlocksShelf();
  if (typeof renderDispatchMatrix === 'function') renderDispatchMatrix();

  // Persist to the TimeBlock table (2026-08-31, fixed 2026-09-02): the WA AI's
  // slot tool + booking flow enforce this store, so EVERY block added in this
  // save must land there — previously only the LAST block was persisted, so a
  // multi-day "date range" block silently hard-blocked only its final day for
  // the AI (the other days lived only in the frontmatter mirror the slot engine
  // never read).
  var newBlocks = (umState.blockedSlots || []).slice(beforeCount);
  if (newBlocks.length > 0 && !isStaffSandbox()) {
    var persistQueue = Promise.resolve();
    newBlocks.forEach(function (blk) {
      persistQueue = persistQueue.then(function () {
        return apiPost('/api/admin/time-blocks', {
          date: blk.date,
          isFullDay: !!blk.isFullDay,
          time: blk.time || '10:00',
          durationMin: blk.durationMin || (blk.isFullDay ? 1440 : 60),
          reason: blk.reason || ''
        }).then(function (resp) {
          if (resp && resp.success && resp.block) {
            // Adopt the server row id so a later unblock removes the REAL row.
            for (var i = 0; i < umState.blockedSlots.length; i++) {
              if (umState.blockedSlots[i] === blk) { umState.blockedSlots[i] = resp.block; break; }
            }
          }
        }).catch(function () { /* sandbox / offline keeps the local mirror */ });
      });
    });
    persistQueue.then(function () {
      if (typeof bkRenderBlockedSlots === 'function') bkRenderBlockedSlots();
    });
  }
  return false;
}
window.umSaveBlockedSlot = umSaveBlockedSlot;
window.umSubmitBlockSlot = umSaveBlockedSlot;
window.submitSlotBlockForm = umSaveBlockedSlot;

function umUnblockSlot(id) {
  if (!umState.blockedSlots) return;
  umState.blockedSlots = umState.blockedSlots.filter(function (s) { return s.id !== id; });
  if (typeof waAiConfig !== 'undefined') {
    waAiConfig.blockedSlots = umState.blockedSlots;
    if (typeof waAiSaveConfig === 'function') waAiSaveConfig(true);
  }
  umRenderBlockedSlots();
  if (typeof umRenderScheduleGrid === 'function') umRenderScheduleGrid([]);
  if (typeof bkRenderBlockedSlots === 'function') bkRenderBlockedSlots();
  if (typeof bkRenderTimeline === 'function') bkRenderTimeline();
  if (typeof showToast === 'function') showToast('Slot unblocked successfully', 'success');
}
window.umUnblockSlot = umUnblockSlot;

function umRenderBlockedSlots() {
  var container = $('bookings-panel-blocked-slots') || $('blocked-slots-container');
  if (!container) return;
  var slots = umState.blockedSlots || [];
  if (slots.length === 0) {
    container.innerHTML = '<div style="padding:1rem;text-align:center;color:var(--text-muted);font-size:0.8125rem;border:1px dashed var(--border-color);border-radius:var(--radius-sm);">' +
      '<i class="fa-solid fa-calendar-check" style="font-size:1.5rem;margin-bottom:0.375rem;display:block;opacity:0.5;"></i>No blocked date or time slots configured.</div>';
    return;
  }
  var html = '<table class="dash-table" style="width:100%;"><thead><tr><th>Date</th><th>Time Slot</th><th>Reason</th><th>Action</th></tr></thead><tbody>';
  slots.forEach(function (s) {
    html += '<tr>' +
      '<td><span class="font-mono" style="font-weight:600;">' + esc(s.date) + '</span></td>' +
      '<td><span class="font-mono">' + esc(s.timeSlot || s.time || 'Full Day') + '</span></td>' +
      '<td>' + esc(s.reason || '-') + '</td>' +
      '<td><button type="button" class="btn-dash btn-outline btn-sm text-red" onclick="umUnblockSlot(\'' + s.id + '\')"><i class="fa-solid fa-trash"></i> Unblock</button></td>' +
    '</tr>';
  });
  html += '</tbody></table>';
  container.innerHTML = html;
}
window.umRenderBlockedSlots = umRenderBlockedSlots;

function umSavePasses() {
  // Deprecated: Passes are now server-authoritative in Prisma. Safe no-op.
}
window.umSavePasses = umSavePasses;

function umLoadPasses() {
  var sub = (typeof waAiGetSubdomain === 'function' ? waAiGetSubdomain() : '') || '';
  if (typeof apiGet === 'function' && !DEMO_MODE && !window.__SANDBOXED_DEMO__) {
    var qs = sub ? ('?subdomain=' + encodeURIComponent(sub)) : '';
    apiGet('/api/admin/members' + qs).then(function (data) {
      if (data && data.success && Array.isArray(data.members)) {
        umState.passes = data.members.map(function (m) {
          return {
            id: m.id,
            code: m.code || ('PASS-' + (m.id ? m.id.slice(-4).toUpperCase() : Math.floor(1000 + Math.random() * 9000))),
            customerName: m.name,
            phone: m.phone,
            planName: m.planName,
            passFlavor: m.passFlavor || 'membership',
            totalCredits: m.totalCredits != null ? m.totalCredits : null,
            usedCredits: m.usedCredits != null ? m.usedCredits : 0,
            voucherCode: m.voucherCode || null,
            stationBinding: m.stationBinding || 'any',
            expiresAt: m.expiresAt || null,
            status: m.status || 'active',
            checkIns: Array.isArray(m.checkIns) ? m.checkIns : []
          };
        });
      }
      umRenderPasses();
      if (typeof renderPassesPanel === 'function') renderPassesPanel();
    }).catch(function () {
      umRenderPasses();
      if (typeof renderPassesPanel === 'function') renderPassesPanel();
    });
  } else {
    umRenderPasses();
    if (typeof renderPassesPanel === 'function') renderPassesPanel();
  }
}
window.umLoadPasses = umLoadPasses;

function umRenderPasses() {
  var tbody = $('um-passes-tbody');
  if (!tbody) return;
  if (umState.passes.length === 0) {
    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;color:var(--text-muted);padding:1.5rem;">No active customer passes found.</td></tr>';
    return;
  }
  tbody.innerHTML = umState.passes.map(function (p) {
    var pFlav = p.passFlavor || (p.type === 'voucher' ? 'voucher' : (p.type === 'membership' ? 'membership' : ((p.totalCredits != null || p.creditsLeft != null) ? 'credit_pack' : 'membership')));
    var isUnlimited = (pFlav === 'membership') || (p.totalCredits == null && !p.creditsLeft && pFlav !== 'credit_pack');
    var isExp = p.expiresAt && new Date(p.expiresAt).getTime() < Date.now();
    var statusClass = (p.status === 'active' && !isExp) ? 'pill-green' : 'pill-red';

    var flavMeta = {
      membership: { label: 'Membership', icon: 'fa-id-card', pill: 'pill-green' },
      credit_pack: { label: 'Credit Pack', icon: 'fa-ticket', pill: 'pill-teal' },
      voucher: { label: 'Voucher', icon: 'fa-tag', pill: 'pill-amber' }
    }[pFlav] || { label: 'Pass', icon: 'fa-id-card', pill: 'pill-teal' };

    var varietyPill = '<span class="pill ' + flavMeta.pill + ' font-medium" style="font-size:0.6875rem;"><i class="fa-solid ' + flavMeta.icon + '"></i> ' + esc(flavMeta.label) + '</span>';

    var accessCol = '';
    if (isUnlimited) {
      var checkInCount = (Array.isArray(p.checkIns) ? p.checkIns.length : (p.usedCredits || 0));
      accessCol = '<span class="cat-pill-badge cat-pill-stock-green"><i class="fa-solid fa-infinity"></i> Unlimited</span>' +
        (checkInCount > 0 ? '<div style="font-size:0.6875rem;color:var(--text-muted);margin-top:2px;">' + checkInCount + ' check-in' + (checkInCount === 1 ? '' : 's') + '</div>' : '');
    } else if (pFlav === 'voucher') {
      accessCol = '<span class="font-mono" style="font-size:0.75rem;color:var(--text-main);font-weight:600;"><i class="fa-solid fa-tag text-teal"></i> ' + esc(p.voucherCode || p.code || 'Voucher') + '</span>';
    } else {
      var tot = p.totalCredits != null ? p.totalCredits : 10;
      var left = (p.totalCredits != null && p.usedCredits != null) ? Math.max(0, p.totalCredits - p.usedCredits) : (p.creditsLeft || 0);
      accessCol = '<span style="font-weight:700;color:var(--accent);">' + esc(left) + '</span> / ' + esc(tot) + ' <span style="font-size:0.75rem;color:var(--text-muted);">left</span>';
    }

    var stBadge = '';
    if (p.stationBinding && p.stationBinding !== 'any') {
      var cleanSt = p.stationBinding.replace('station:', '').replace('category:', 'Zone: ');
      stBadge = '<div style="font-size:0.6875rem;color:var(--color-teal,#14b8a6);margin-top:2px;display:flex;align-items:center;gap:0.25rem;"><i class="fa-solid fa-chair"></i> ' + esc(cleanSt) + '</div>';
    }

    var actionBtn = '';
    if (isUnlimited) {
      actionBtn = '<button type="button" class="btn-dash btn-accent btn-sm" title="Record Member Check-In" onclick="umCheckInCustomerPass(\'' + esc(p.id) + '\')"><i class="fa-solid fa-id-badge"></i> Check In</button> ';
    } else if (pFlav === 'voucher') {
      if (p.status === 'redeemed' || p.status === 'completed') {
        actionBtn = '<span class="text-muted" style="font-size:0.75rem;margin-right:0.5rem;"><i class="fa-solid fa-check"></i> Redeemed</span>';
      } else {
        actionBtn = '<button type="button" class="btn-dash btn-accent btn-sm" title="Redeem Voucher" onclick="umRedeemSpecificPass(\'' + esc(p.id) + '\')"><i class="fa-solid fa-tag"></i> Redeem</button> ';
      }
    } else {
      actionBtn = '<button type="button" class="btn-dash btn-accent btn-sm" title="Deduct 1 Session Credit" onclick="umRedeemSpecificPass(\'' + esc(p.id) + '\')"><i class="fa-solid fa-check-to-slot"></i> Deduct</button> ';
    }
    if (p.stationBinding && p.stationBinding !== 'any') {
      actionBtn += '<button type="button" class="btn-dash btn-outline btn-sm" title="Check In & Seat at Assigned Station" onclick="umCheckInAndSeat(\'' + esc(p.id) + '\', \'' + esc(p.stationBinding) + '\')"><i class="fa-solid fa-chair text-teal"></i> Seat</button> ';
    }
    actionBtn += '<button type="button" class="btn-dash btn-outline btn-sm" title="Send E-Card via WhatsApp" onclick="umSendPassWa(\'' + esc(p.id) + '\')"><i class="fa-brands fa-whatsapp text-green"></i></button> ';
    actionBtn += '<button type="button" class="btn-dash btn-danger-outline btn-sm" title="Remove Pass" onclick="umDeleteSpecificPass(\'' + esc(p.id) + '\')"><i class="fa-solid fa-trash"></i></button>';

    return '<tr>' +
      '<td style="font-weight:600;">' + esc(p.customerName || p.name) + '</td>' +
      '<td>' + esc(p.phone || p.customerPhone || '') + '</td>' +
      '<td>' + varietyPill + ' <div style="display:inline-block;margin-left:0.25rem;vertical-align:middle;">' + esc(p.planName || p.passTier) + stBadge + '</div></td>' +
      '<td>' + accessCol + '</td>' +
      '<td><span class="pill ' + statusClass + '">' + esc(isExp ? 'EXPIRED' : String(p.status).toUpperCase()) + '</span></td>' +
      '<td style="color:var(--text-muted);white-space:nowrap;">' + esc(fmtDate(p.expiresAt)) + '</td>' +
      '<td style="text-align:right;white-space:nowrap;">' + actionBtn + '</td>' +
    '</tr>';
  }).join('');
}

/* ============================================================
   MANUAL PASS ISSUANCE & WHATSAPP DELIVERY STUDIO LOGIC
   ============================================================ */

function umCleanCustomerPhone(phone) {
  var d = String(phone || '').replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('0')) d = '62' + d.slice(1);
  else if (!d.startsWith('62') && d.length <= 11) d = '62' + d;
  return d;
}
window.umCleanCustomerPhone = umCleanCustomerPhone;

function umBuildPassWaMessage(passData) {
  var bName = (typeof brandData !== 'undefined' && brandData && brandData.name) ? brandData.name : (document.title ? document.title.split('-')[0].trim() : 'Codaxiom Business');
  var pFlav = passData.passFlavor || 'membership';
  var flavLabel = { membership: 'Membership', credit_pack: 'Credit Pack', voucher: 'Voucher' }[pFlav] || 'Customer Pass';
  var entitlement = (pFlav === 'membership') ? 'Unlimited visits' : ((pFlav === 'voucher') ? ((passData.totalCredits || 1) + ' Voucher Redemption(s)') : ((passData.totalCredits || 10) + ' Session Credits'));
  var expiryStr = passData.expiresAt ? fmtDate(passData.expiresAt) : 'No Expiry';

  var lines = [
    '*DIGITAL PASS & MEMBERSHIP*',
    bName,
    '',
    'Halo ' + (passData.customerName || 'Pelanggan') + ', pass digital Anda telah aktif:',
    '',
    '• Pass: ' + (passData.planName || 'Customer Pass'),
    '• Tipe: ' + flavLabel,
    '• Kode Pass: ' + (passData.code || 'PASS-READY'),
    '• Akses / Sesi: ' + entitlement
  ];

  if (passData.stationBinding && passData.stationBinding !== 'any') {
    lines.push('• Designated Space: ' + passData.stationBinding.replace('station:', '').replace('category:', 'Zone: '));
  }

  lines.push('• Berlaku Hingga: ' + expiryStr);
  lines.push('');
  lines.push('Tunjukkan pesan ini atau sebutkan kode pass Anda saat berkunjung.');
  lines.push('Terima kasih telah mempercayai layanan kami.');
  return lines.join('\n');
}
window.umBuildPassWaMessage = umBuildPassWaMessage;

function umUpdatePassLivePreview() {
  var brandNameEl = $('pass-prev-brand');
  var titleEl = $('pass-prev-title');
  var custEl = $('pass-prev-cust');
  var badgeEl = $('pass-prev-flavor-badge');
  var codeEl = $('pass-prev-code');
  var entEl = $('pass-prev-entitlement');
  var expEl = $('pass-prev-expiry');
  var msgPreEl = $('pass-wa-msg-pre');

  var bName = (typeof brandData !== 'undefined' && brandData && brandData.name) ? brandData.name : (document.title ? document.title.split('-')[0].trim() : 'Codaxiom Business');
  if (brandNameEl) brandNameEl.textContent = bName;

  var isCustom = $('pass-tab-custom') && $('pass-tab-custom').classList.contains('active');
  var planName = 'VIP 1-Month Unlimited Pass';
  var pFlav = 'membership';
  var credits = 10;
  var stBinding = 'any';

  var stGroup = $('pass-station-binding-group');
  var stSelect = $('pass-station-binding');
  if (stSelect && stGroup && stGroup.style.display !== 'none') {
    stBinding = stSelect.value || 'any';
  }

  if (isCustom) {
    pFlav = ($('pass-custom-flavor') && $('pass-custom-flavor').value) || 'membership';
    var rawName = $('pass-custom-name') ? $('pass-custom-name').value.trim() : '';
    if (rawName) {
      planName = rawName;
    } else {
      var nameMap = { membership: 'VIP Membership Pass', credit_pack: '10-Session Credit Pack', voucher: 'Promo Discount Voucher' };
      planName = nameMap[pFlav] || 'Custom Customer Pass';
    }
  } else {
    var sel = $('pass-plan-name');
    if (sel && sel.value) {
      planName = sel.value;
      var catItems = Array.isArray(catalogState) ? catalogState : ((catalogState && Array.isArray(catalogState.items)) ? catalogState.items : []);
      var item = catItems.find(function(it) {
        var itName = (typeof it.name === 'object' && it.name) ? (it.name.en || it.name.id || Object.values(it.name)[0] || '') : (it.name || it.title || '');
        return itName === sel.value || it.name === sel.value || it.id === sel.value;
      });
      pFlav = item ? (item.passFlavor || (item.type === 'voucher' ? 'voucher' : (item.type === 'membership' ? 'membership' : ((item.sessions != null && item.sessions !== '') ? 'credit_pack' : 'membership')))) : 'membership';
      if (item && item.stationBinding && stBinding === 'any') {
        stBinding = item.stationBinding;
      }
    }
  }

  var flavMeta = {
    membership: { label: 'Membership', icon: 'fa-id-badge' },
    credit_pack: { label: 'Credit Pack', icon: 'fa-ticket' },
    voucher: { label: 'Voucher', icon: 'fa-tag' }
  }[pFlav] || { label: 'Pass', icon: 'fa-id-card' };

  if (titleEl) titleEl.textContent = planName;
  if (badgeEl) badgeEl.innerHTML = '<i class="fa-solid ' + flavMeta.icon + '"></i> ' + esc(flavMeta.label);

  var custName = ($('pass-cust-name') && $('pass-cust-name').value.trim()) || 'Customer Name';
  if (custEl) custEl.textContent = custName;

  var credInput = $('pass-credits');
  var entitlement = 'Unlimited visits';
  if (pFlav === 'membership') {
    entitlement = 'Unlimited visits';
  } else if (pFlav === 'voucher') {
    var vVal = credInput ? parseInt(credInput.value, 10) : 1;
    entitlement = (isNaN(vVal) || vVal <= 0 ? 1 : vVal) + ' Redemption';
  } else {
    var cVal = credInput ? parseInt(credInput.value, 10) : 10;
    credits = (isNaN(cVal) || cVal <= 0) ? 10 : cVal;
    entitlement = credits + ' Sessions';
  }
  if (entEl) entEl.textContent = entitlement;

  var expInput = $('pass-expiry');
  var expiryStr = (expInput && expInput.value) ? fmtDate(expInput.value) : '-';
  if (expEl) expEl.textContent = expiryStr;

  var stWrap = $('pass-prev-station-wrap');
  var stEl = $('pass-prev-station');
  if (stWrap && stEl) {
    if (stBinding && stBinding !== 'any') {
      stWrap.style.display = 'block';
      stEl.textContent = stBinding.replace('station:', '').replace('category:', 'Zone: ');
    } else {
      stWrap.style.display = 'none';
    }
  }

  var currentCode = (codeEl && codeEl.textContent && codeEl.textContent !== 'PASS-READY') ? codeEl.textContent : 'PASS-7842';

  if (msgPreEl) {
    var previewData = {
      customerName: custName,
      planName: planName,
      passFlavor: pFlav,
      code: currentCode,
      totalCredits: (pFlav === 'credit_pack' || pFlav === 'voucher') ? credits : null,
      stationBinding: stBinding,
      expiresAt: (expInput && expInput.value) ? expInput.value : ''
    };
    msgPreEl.textContent = umBuildPassWaMessage(previewData);
  }
}
window.umUpdatePassLivePreview = umUpdatePassLivePreview;

function umSetPassSourceMode(mode) {
  var catTab = $('pass-tab-catalog');
  var custTab = $('pass-tab-custom');
  var catSec = $('pass-source-catalog-sec');
  var custSec = $('pass-source-custom-sec');

  if (mode === 'custom') {
    if (catTab) catTab.classList.remove('active');
    if (custTab) custTab.classList.add('active');
    if (catSec) catSec.style.display = 'none';
    if (custSec) custSec.style.display = 'flex';
    var curFlav = ($('pass-custom-flavor') && $('pass-custom-flavor').value) || 'membership';
    umSelectCustomPassFlavor(curFlav);
  } else {
    if (custTab) custTab.classList.remove('active');
    if (catTab) catTab.classList.add('active');
    if (custSec) custSec.style.display = 'none';
    if (catSec) catSec.style.display = 'block';
    var sel = $('pass-plan-name');
    if (sel && sel.value) onPassTypeChange(sel.value);
  }
  umUpdatePassLivePreview();
}
window.umSetPassSourceMode = umSetPassSourceMode;

function umSelectCustomPassFlavor(flavor) {
  var hidden = $('pass-custom-flavor');
  if (hidden) hidden.value = flavor;

  var grid = $('pass-custom-flavor-grid');
  if (grid) {
    var btns = grid.querySelectorAll('.pass-flavor-btn');
    btns.forEach(function(b) {
      b.classList.toggle('active', b.getAttribute('data-flavor') === flavor);
    });
  }

  var creditsInput = $('pass-credits');
  var creditsLabel = $('pass-credits-label');

  if (creditsInput && creditsLabel) {
    if (flavor === 'membership') {
      creditsLabel.innerHTML = '<i class="fa-solid fa-infinity text-teal"></i> Access Mode';
      creditsInput.value = '';
      creditsInput.placeholder = 'Unlimited visits (Membership)';
      creditsInput.disabled = true;
      creditsInput.removeAttribute('required');
    } else if (flavor === 'voucher') {
      creditsLabel.innerHTML = '<i class="fa-solid fa-tag text-teal"></i> Voucher Redemptions';
      creditsInput.value = '1';
      creditsInput.placeholder = '1 Redemption';
      creditsInput.disabled = false;
      creditsInput.setAttribute('required', 'true');
    } else {
      creditsLabel.innerHTML = '<i class="fa-solid fa-ticket text-teal"></i> Session Credits';
      creditsInput.disabled = false;
      creditsInput.setAttribute('required', 'true');
      creditsInput.value = '10';
      creditsInput.placeholder = 'e.g. 10';
    }
  }
  umUpdatePassLivePreview();
}
window.umSelectCustomPassFlavor = umSelectCustomPassFlavor;

function umSetPassExpiryPreset(days) {
  var expEl = $('pass-expiry');
  if (expEl) {
    var d = new Date(Date.now() + days * 24 * 60 * 60 * 1000);
    expEl.value = d.toISOString().split('T')[0];
    umUpdatePassLivePreview();
  }
}
window.umSetPassExpiryPreset = umSetPassExpiryPreset;

function umTogglePassWaSend(checked) {
  var previewBox = $('pass-wa-preview-text');
  if (previewBox) {
    previewBox.style.display = checked ? 'block' : 'none';
  }
  var btn = $('btn-save-issue-pass');
  if (btn) {
    btn.innerHTML = checked
      ? '<i class="fa-brands fa-whatsapp"></i> Issue &amp; Deliver Pass'
      : '<i class="fa-solid fa-paper-plane"></i> Issue Pass (Save Only)';
  }
}
window.umTogglePassWaSend = umTogglePassWaSend;

function umOpenIssuePassModal() {
  if (!dashCan('passes_issue')) { showToast(t('staff.noPermission', 'You do not have permission for this action.'), 'error'); return; }
  var m = $('issue-pass-modal');
  if (!m) return;

  var formEl = $('pass-issue-form');
  var succView = $('pass-issue-success-view');
  if (formEl) {
    formEl.reset();
    formEl.style.display = 'block';
    var waToggle = $('pass-send-wa-toggle');
    if (waToggle) { waToggle.checked = true; umTogglePassWaSend(true); }
  }
  if (succView) succView.style.display = 'none';

  // Populate designated station/zone dropdown if stations exist
  var stGroup = $('pass-station-binding-group');
  var stSelect = $('pass-station-binding');
  if (stGroup && stSelect) {
    var stationsList = (typeof stationsState !== 'undefined' && Array.isArray(stationsState.stations)) ? stationsState.stations : [];
    var categoriesList = (typeof stationsState !== 'undefined' && Array.isArray(stationsState.categories)) ? stationsState.categories : [];
    if (stationsList.length > 0 || categoriesList.length > 0) {
      stGroup.style.display = 'block';
      var uLabel = (stationsState && stationsState.unitLabel) || 'Station';
      var opts = '<option value="any">Floating / Any Available ' + esc(uLabel) + '</option>';
      if (categoriesList.length > 0) {
        categoriesList.forEach(function (cat) {
          opts += '<option value="category:' + esc(cat.name) + '">Zone / Area: ' + esc(cat.name) + '</option>';
        });
      }
      stationsList.forEach(function (st) {
        var stTitle = st.name || (uLabel + ' ' + (st.unitNumber || ''));
        opts += '<option value="station:' + esc(stTitle) + '">Dedicated ' + esc(uLabel) + ': ' + esc(stTitle) + ' (' + esc(st.area || st.category || 'Main') + ')</option>';
      });
      stSelect.innerHTML = opts;
      stSelect.value = 'any';
    } else {
      stGroup.style.display = 'none';
    }
  }

  var sel = $('pass-plan-name');
  var alertBox = $('pass-empty-catalog-alert');
  var catItems = Array.isArray(catalogState) ? catalogState : ((catalogState && Array.isArray(catalogState.items)) ? catalogState.items : []);
  var eligible = catItems.filter(function(it) {
    var t = (typeof SELLING_TYPE_CANON !== 'undefined' && SELLING_TYPE_CANON[it.type]) ? SELLING_TYPE_CANON[it.type] : it.type;
    return t === 'pass' || it.type === 'pass' || it.type === 'membership' || it.type === 'package';
  });

  if (eligible.length > 0) {
    if (sel) {
      sel.innerHTML = eligible.map(function(it) {
        var itName = (typeof it.name === 'object' && it.name) ? (it.name.en || it.name.id || Object.values(it.name)[0] || '') : (it.name || it.title || '');
        var pFlav = it.passFlavor || (it.type === 'voucher' ? 'voucher' : (it.type === 'membership' ? 'membership' : ((it.sessions != null && it.sessions !== '') ? 'credit_pack' : 'membership')));
        var flavLabel = { membership: 'Membership', credit_pack: 'Credit Pack', voucher: 'Voucher' }[pFlav] || 'Pass';
        return '<option value="' + esc(itName) + '">' + esc(itName) + ' (' + flavLabel + ')</option>';
      }).join('');
      sel.disabled = false;
      var firstName = (typeof eligible[0].name === 'object' && eligible[0].name) ? (eligible[0].name.en || eligible[0].name.id || Object.values(eligible[0].name)[0] || '') : (eligible[0].name || eligible[0].title || '');
      onPassTypeChange(firstName);
    }
    if (alertBox) alertBox.style.display = 'none';
    umSetPassSourceMode('catalog');
  } else {
    if (sel) {
      sel.innerHTML = '<option value="" disabled selected>No pass offerings in catalog</option>';
      sel.disabled = true;
    }
    if (alertBox) alertBox.style.display = 'flex';
    umSetPassSourceMode('custom');
  }

  var expEl = $('pass-expiry');
  if (expEl && !expEl.value) {
    var defaultExp = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
    expEl.value = defaultExp;
  }

  var codePrev = $('pass-prev-code');
  if (codePrev) {
    codePrev.textContent = 'PASS-' + Math.floor(1000 + Math.random() * 9000);
  }

  umUpdatePassLivePreview();
  m.classList.add('open');
}

function closePassIssueModal() {
  umCloseIssuePassModal();
}
window.closePassIssueModal = closePassIssueModal;

function onPassTypeChange(val) {
  var creditsInput = $('pass-credits');
  var creditsLabel = $('pass-credits-label');
  var expEl = $('pass-expiry');
  if (!val) return;

  var catItems = Array.isArray(catalogState) ? catalogState : ((catalogState && Array.isArray(catalogState.items)) ? catalogState.items : []);
  var item = catItems.find(function(it) {
    var itName = (typeof it.name === 'object' && it.name) ? (it.name.en || it.name.id || Object.values(it.name)[0] || '') : (it.name || it.title || '');
    return itName === val || it.name === val || it.id === val;
  });
  var pFlav = item ? (item.passFlavor || (item.type === 'voucher' ? 'voucher' : (item.type === 'membership' ? 'membership' : ((item.sessions != null && item.sessions !== '') ? 'credit_pack' : 'membership')))) : 'membership';

  if (creditsInput && creditsLabel) {
    if (pFlav === 'membership') {
      creditsLabel.innerHTML = '<i class="fa-solid fa-infinity text-teal"></i> Access Mode';
      creditsInput.value = '';
      creditsInput.placeholder = 'Unlimited visits (Membership)';
      creditsInput.disabled = true;
      creditsInput.removeAttribute('required');
    } else if (pFlav === 'voucher') {
      creditsLabel.innerHTML = '<i class="fa-solid fa-tag text-teal"></i> Voucher Redemptions';
      creditsInput.value = '1';
      creditsInput.placeholder = '1 Redemption';
      creditsInput.disabled = false;
      creditsInput.setAttribute('required', 'true');
    } else {
      creditsLabel.innerHTML = '<i class="fa-solid fa-ticket text-teal"></i> Session Credits';
      creditsInput.disabled = false;
      creditsInput.setAttribute('required', 'true');
      creditsInput.value = (item && item.sessions) ? item.sessions : '10';
      creditsInput.placeholder = 'e.g. 10';
    }
  }

  if (expEl) {
    var valDays = (item && item.validity) ? parseInt(item.validity, 10) : 30;
    if (isNaN(valDays) || valDays <= 0) valDays = 30;
    expEl.value = new Date(Date.now() + valDays * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
  }

  var stSelect = $('pass-station-binding');
  if (stSelect && item && item.stationBinding) {
    stSelect.value = item.stationBinding;
  }

  umUpdatePassLivePreview();
}
window.onPassTypeChange = onPassTypeChange;

function umCloseIssuePassModal() {
  var m = $('issue-pass-modal');
  if (m) {
    m.classList.remove('open');
    var f = m.querySelector('form');
    if (f) f.reset();
  }
}

function umResetIssuePassModal() {
  var formEl = $('pass-issue-form');
  var succView = $('pass-issue-success-view');
  if (formEl) {
    formEl.reset();
    formEl.style.display = 'block';
  }
  if (succView) succView.style.display = 'none';
  umOpenIssuePassModal();
}
window.umResetIssuePassModal = umResetIssuePassModal;

function umCopyIssuedPassCode() {
  var codeEl = $('pass-success-code-val');
  if (!codeEl) return;
  var code = codeEl.textContent.trim();
  if (!code) return;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(code).then(function() {
      showToast('Pass code copied: ' + code, 'success');
    }).catch(function() {
      showToast('Pass code: ' + code, 'info');
    });
  } else {
    showToast('Pass code: ' + code, 'info');
  }
}
window.umCopyIssuedPassCode = umCopyIssuedPassCode;

function umSubmitIssuePass(e) {
  if (e && e.preventDefault) e.preventDefault();
  var name = $('pass-cust-name') ? $('pass-cust-name').value.trim() : '';
  var rawPhone = $('pass-cust-phone') ? $('pass-cust-phone').value.trim() : '';
  var isCustom = $('pass-tab-custom') && $('pass-tab-custom').classList.contains('active');

  if (!name || !rawPhone) {
    showToast('Customer Name and WhatsApp Phone are required.', 'error');
    return false;
  }

  var cleanPhone = umCleanCustomerPhone(rawPhone);
  if (!cleanPhone) {
    showToast('Please provide a valid WhatsApp phone number.', 'error');
    return false;
  }

  var plan = '';
  var pFlav = 'membership';
  var credits = null;
  var expiry = ($('pass-expiry') && $('pass-expiry').value) ? $('pass-expiry').value : new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  var stBinding = 'any';
  var stSelect = $('pass-station-binding');
  if (stSelect && stSelect.value) stBinding = stSelect.value;

  if (isCustom) {
    plan = $('pass-custom-name') ? $('pass-custom-name').value.trim() : '';
    pFlav = $('pass-custom-flavor') ? $('pass-custom-flavor').value : 'membership';
    if (!plan) {
      var flavNameMap = { membership: 'VIP Membership Pass', credit_pack: '10-Session Credit Pack', voucher: 'Promo Discount Voucher' };
      plan = flavNameMap[pFlav] || 'Custom Customer Pass';
    }
  } else {
    var sel = $('pass-plan-name');
    plan = sel ? sel.value : '';
    if (!plan) {
      showToast('Please select a catalog offering or switch to Custom One-Off Pass.', 'error');
      return false;
    }
    var catItems = Array.isArray(catalogState) ? catalogState : ((catalogState && Array.isArray(catalogState.items)) ? catalogState.items : []);
    var item = catItems.find(function(it) {
      var itName = (typeof it.name === 'object' && it.name) ? (it.name.en || it.name.id || Object.values(it.name)[0] || '') : (it.name || it.title || '');
      return itName === plan || it.name === plan || it.id === plan;
    });
    if (item && item.stationBinding && stBinding === 'any') {
      stBinding = item.stationBinding;
    }
    var vCode = (item && item.voucherCode) ? item.voucherCode : null;
  }

  var isUnlimited = (pFlav === 'membership');
  if (!isUnlimited) {
    var credVal = $('pass-credits') ? parseInt($('pass-credits').value, 10) : NaN;
    credits = (!isNaN(credVal) && credVal > 0) ? credVal : (pFlav === 'voucher' ? 1 : 10);
  }

  var liveCodeEl = $('pass-prev-code');
  var code = (liveCodeEl && liveCodeEl.textContent && liveCodeEl.textContent !== 'PASS-READY') ? liveCodeEl.textContent : ('PASS-' + Math.floor(1000 + Math.random() * 9000));

  var newPass = {
    id: 'pass-' + Date.now(),
    code: code,
    customerName: name,
    phone: cleanPhone,
    planName: plan,
    passFlavor: pFlav,
    totalCredits: isUnlimited ? null : credits,
    usedCredits: 0,
    voucherCode: vCode || null,
    stationBinding: stBinding || 'any',
    checkIns: [],
    expiresAt: expiry,
    status: 'active'
  };

  umState.passes.unshift(newPass);
  umRenderPasses();
  renderCustomersPanel();

  var sub = (typeof waAiGetSubdomain === 'function' ? waAiGetSubdomain() : '') || '';
  if (typeof apiPost === 'function' && !DEMO_MODE && !window.__SANDBOXED_DEMO__) {
    apiPost('/api/admin/members', {
      subdomain: sub,
      name: name,
      phone: cleanPhone,
      planName: plan,
      passFlavor: pFlav,
      totalCredits: isUnlimited ? null : credits,
      code: code,
      stationBinding: stBinding || 'any',
      voucherCode: vCode || null,
      expiresAt: expiry
    }).then(function(res) {
      if (res && res.success && res.member) {
        newPass.id = res.member.id;
        newPass.code = res.member.code || newPass.code;
        if (typeof renderPassesPanel === 'function') renderPassesPanel();
      }
    }).catch(function(err) {
      console.warn('[Pass Issue] Server creation warning:', err);
    });
  }

  var sendWa = $('pass-send-wa-toggle') ? $('pass-send-wa-toggle').checked : true;
  var waMsg = umBuildPassWaMessage(newPass);

  var formEl = $('pass-issue-form');
  var succView = $('pass-issue-success-view');
  if (formEl && succView) {
    formEl.style.display = 'none';
    succView.style.display = 'block';

    var codeValEl = $('pass-success-code-val');
    if (codeValEl) codeValEl.textContent = newPass.code;

    var waStatusText = $('pass-success-wa-status-text');
    var waLink = $('pass-success-wa-link');
    var waUrl = 'https://wa.me/' + cleanPhone + '?text=' + encodeURIComponent(waMsg);

    if (waLink) {
      waLink.href = waUrl;
    }

    if (sendWa) {
      if (waStatusText) waStatusText.textContent = 'Dispatched to +' + cleanPhone;
      if (typeof apiPost === 'function') {
        apiPost('/api/admin/chat-send', {
          subdomain: (typeof waAiGetSubdomain === 'function') ? waAiGetSubdomain() : '',
          phone: cleanPhone,
          message: waMsg
        }).then(function(res) {
          if (res && res.success) {
            showToast('Pass sent to customer via WhatsApp!', 'success');
          }
        }).catch(function(err) {
          console.log('[Pass Issue] Engine chat-send fallback to web link', err);
        });
      }
      try {
        window.open(waUrl, '_blank');
      } catch(e) {}
      showToast(t('module.universal.passIssued', 'Customer pass issued & dispatched to ') + name, 'success');
    } else {
      if (waStatusText) waStatusText.textContent = 'Saved without WhatsApp dispatch';
      showToast(t('module.universal.passIssued', 'Customer pass issued successfully for ') + name, 'success');
    }
  }

  return false;
}
window.submitPassIssueForm = umSubmitIssuePass;

function umSendPassWa(id) {
  var pass = (umState.passes || []).find(function(p) { return p.id === id; });
  if (!pass) return;
  var cleanPhone = umCleanCustomerPhone(pass.phone || pass.customerPhone);
  if (!cleanPhone) {
    showToast('Customer does not have a valid WhatsApp phone number.', 'error');
    return;
  }
  var waMsg = umBuildPassWaMessage(pass);
  var waUrl = 'https://wa.me/' + cleanPhone + '?text=' + encodeURIComponent(waMsg);

  if (typeof apiPost === 'function') {
    apiPost('/api/admin/chat-send', {
      subdomain: (typeof waAiGetSubdomain === 'function') ? waAiGetSubdomain() : '',
      phone: cleanPhone,
      message: waMsg
    }).then(function(res) {
      if (res && res.success) {
        showToast('Digital E-Card sent to +' + cleanPhone, 'success');
      } else {
        window.open(waUrl, '_blank');
      }
    }).catch(function() {
      window.open(waUrl, '_blank');
    });
  } else {
    window.open(waUrl, '_blank');
  }
}
window.umSendPassWa = umSendPassWa;

function umGetVerifyTargets(scope) {
  var passInp = $('credit-verify-input');
  var passRes = $('credit-verify-result');
  var ovInp = $('ov-credit-verify-input');
  var ovRes = $('ov-credit-verify-result');

  if (scope === 'overview') {
    return { input: ovInp || passInp, res: ovRes || passRes, otherRes: passRes };
  }
  if (scope === 'passes') {
    return { input: passInp || ovInp, res: passRes || ovRes, otherRes: ovRes };
  }

  if (document.activeElement === ovInp) return { input: ovInp, res: ovRes, otherRes: passRes };
  if (document.activeElement === passInp) return { input: passInp, res: passRes, otherRes: ovRes };

  var activePanel = document.querySelector('.panel.active') || document.querySelector('.dash-panel.active');
  if (activePanel && (activePanel.id === 'panel-passes' || activePanel.id === 'panel-customers') && passInp) {
    return { input: passInp, res: passRes, otherRes: ovRes };
  }
  if (ovInp && ovInp.value && ovInp.value.trim()) return { input: ovInp, res: ovRes, otherRes: passRes };
  if (passInp && passInp.value && passInp.value.trim()) return { input: passInp, res: passRes, otherRes: ovRes };

  return { input: passInp || ovInp, res: passRes || ovRes, otherRes: (passInp ? ovRes : null) };
}

function umVerifyCredit(scope) {
  var targets = umGetVerifyTargets(scope);
  var input = targets.input;
  var res = targets.res;
  var otherRes = targets.otherRes;
  if (!input || !res) return;

  function renderResult(html, cls) {
    [res, otherRes].forEach(function (el) {
      if (el) {
        el.className = cls;
        el.style.display = 'block';
        el.innerHTML = html;
      }
    });
  }

  var q = input.value.trim().toLowerCase();
  if (!q) {
    renderResult('<i class="fa-solid fa-triangle-exclamation"></i> Please enter a customer phone number, pass code, or name.', 'credit-verify-res-warning');
    return;
  }

  var qClean = q.replace(/\D/g, '');
  var found = (umState.passes || []).find(function (p) {
    var pPhone = String(p.phone || p.customerPhone || '').toLowerCase();
    var pPhoneClean = pPhone.replace(/\D/g, '');
    var phoneMatched = (qClean.length >= 4 && pPhoneClean.indexOf(qClean) !== -1);
    var pCode = String(p.code || p.passCode || '').toLowerCase();
    var pName = String(p.customerName || p.name || '').toLowerCase();
    var pId = String(p.id || '').toLowerCase();
    var pVoucher = String(p.voucherCode || '').toLowerCase();
    return phoneMatched ||
           (pPhone && pPhone.indexOf(q) !== -1) ||
           (pCode && pCode.indexOf(q) !== -1) ||
           (pName && pName.indexOf(q) !== -1) ||
           (pId && pId.indexOf(q) !== -1) ||
           (pVoucher && pVoucher.indexOf(q) !== -1);
  });

  if (found) {
    umState.lastVerifiedPass = found;
    var pFlav = found.passFlavor || (found.type === 'voucher' ? 'voucher' : (found.type === 'membership' ? 'membership' : ((found.totalCredits != null || found.creditsLeft != null) ? 'credit_pack' : 'membership')));
    var isUnlimited = (pFlav === 'membership') || (found.totalCredits == null && !found.creditsLeft && pFlav !== 'credit_pack');
    var isExp = found.expiresAt && new Date(found.expiresAt).getTime() < Date.now();
    var daysLeft = found.expiresAt ? Math.ceil((new Date(found.expiresAt).getTime() - Date.now()) / (1000 * 60 * 60 * 24)) : null;

    if (found.status !== 'active' || isExp) {
      renderResult('<i class="fa-solid fa-circle-xmark"></i> <strong>Pass Inactive or Expired:</strong> ' + esc(found.customerName || found.name) + ' (' + esc(found.planName || found.passTier) + ') · Status: <span class="status-pill red">' + esc(found.status.toUpperCase()) + '</span>' + (isExp ? ' (Expired on ' + esc(found.expiresAt.slice(0, 10)) + ')' : ''), 'credit-verify-res-error');
      return;
    }

    if (isUnlimited) {
      var checkInCount = (Array.isArray(found.checkIns) ? found.checkIns.length : (found.usedCredits || 0));
      var seatBtn = '';
      if (found.stationBinding && found.stationBinding !== 'any') {
        var cleanStName = found.stationBinding.replace('station:', '').replace('category:', 'Zone: ');
        seatBtn = '<button type="button" class="btn-dash btn-accent btn-xs" onclick="umCheckInAndSeat(\'' + esc(found.id) + '\', \'' + esc(found.stationBinding) + '\')"><i class="fa-solid fa-chair"></i> Check In &amp; Seat at ' + esc(cleanStName) + '</button>';
      } else if (typeof stationsState !== 'undefined' && Array.isArray(stationsState.stations) && stationsState.stations.length > 0) {
        seatBtn = '<button type="button" class="btn-dash btn-outline btn-xs" onclick="umCheckInAndSeat(\'' + esc(found.id) + '\')"><i class="fa-solid fa-chair"></i> Check In &amp; Seat (Open)</button>';
      }
      var resHtml = '<div style="display:flex;align-items:center;justify-content:space-between;gap:0.75rem;flex-wrap:wrap;width:100%;">' +
        '<div><i class="fa-solid fa-circle-check text-green"></i> <strong>Member Pass Verified:</strong> ' + esc(found.customerName || found.name) + ' (' + esc(found.planName || found.passTier) + ') · <span class="cat-pill-badge cat-pill-stock-green"><i class="fa-solid fa-infinity"></i> Unlimited Access</span>' + (daysLeft != null ? ' · ' + daysLeft + ' days left' : '') + ' (' + checkInCount + ' check-ins logged)' + (found.stationBinding && found.stationBinding !== 'any' ? ' · <span class="text-teal font-medium"><i class="fa-solid fa-chair"></i> ' + esc(found.stationBinding.replace('station:', '').replace('category:', 'Zone: ')) + '</span>' : '') + '</div>' +
        '<div style="display:flex;gap:0.5rem;align-items:center;">' +
          seatBtn +
          '<button type="button" class="btn-dash btn-outline btn-xs" onclick="umCheckInCustomerPass(\'' + esc(found.id) + '\')"><i class="fa-solid fa-id-badge"></i> Check In Only</button>' +
        '</div>' +
      '</div>';
      renderResult(resHtml, 'credit-verify-res-success');
    } else if (pFlav === 'voucher') {
      var seatBtn = '';
      if (found.stationBinding && found.stationBinding !== 'any') {
        var cleanStName = found.stationBinding.replace('station:', '').replace('category:', 'Zone: ');
        seatBtn = '<button type="button" class="btn-dash btn-accent btn-xs" onclick="umCheckInAndSeat(\'' + esc(found.id) + '\', \'' + esc(found.stationBinding) + '\')"><i class="fa-solid fa-chair"></i> Redeem &amp; Seat at ' + esc(cleanStName) + '</button>';
      } else if (typeof stationsState !== 'undefined' && Array.isArray(stationsState.stations) && stationsState.stations.length > 0) {
        seatBtn = '<button type="button" class="btn-dash btn-outline btn-xs" onclick="umCheckInAndSeat(\'' + esc(found.id) + '\')"><i class="fa-solid fa-chair"></i> Redeem &amp; Seat (Open)</button>';
      }
      var resHtml = '<div style="display:flex;align-items:center;justify-content:space-between;gap:0.75rem;flex-wrap:wrap;width:100%;">' +
        '<div><i class="fa-solid fa-circle-check text-green"></i> <strong>Voucher Verified:</strong> ' + esc(found.customerName || found.name) + ' · Code: <span class="font-mono text-accent font-bold">' + esc(found.code || found.voucherCode || 'VOUCHER') + '</span> · Valid promo credit' + (found.stationBinding && found.stationBinding !== 'any' ? ' · <span class="text-teal font-medium"><i class="fa-solid fa-chair"></i> ' + esc(found.stationBinding.replace('station:', '').replace('category:', 'Zone: ')) + '</span>' : '') + '</div>' +
        '<div style="display:flex;gap:0.5rem;align-items:center;">' +
          seatBtn +
          '<button type="button" class="btn-dash btn-accent btn-xs" onclick="umRedeemSpecificPass(\'' + esc(found.id) + '\')"><i class="fa-solid fa-tag"></i> Redeem Voucher</button>' +
        '</div>' +
      '</div>';
      renderResult(resHtml, 'credit-verify-res-success');
    } else {
      var tot = found.totalCredits != null ? found.totalCredits : 10;
      var left = (found.totalCredits != null && found.usedCredits != null) ? Math.max(0, found.totalCredits - found.usedCredits) : (found.creditsLeft || 0);
      if (left <= 0) {
        renderResult('<i class="fa-solid fa-circle-xmark"></i> <strong>No Credits Remaining:</strong> ' + esc(found.customerName || found.name) + ' has 0 / ' + tot + ' session credits remaining.', 'credit-verify-res-error');
        return;
      }
      var seatBtn = '';
      if (found.stationBinding && found.stationBinding !== 'any') {
        var cleanStName = found.stationBinding.replace('station:', '').replace('category:', 'Zone: ');
        seatBtn = '<button type="button" class="btn-dash btn-accent btn-xs" onclick="umCheckInAndSeat(\'' + esc(found.id) + '\', \'' + esc(found.stationBinding) + '\')"><i class="fa-solid fa-chair"></i> Deduct &amp; Seat at ' + esc(cleanStName) + '</button>';
      } else if (typeof stationsState !== 'undefined' && Array.isArray(stationsState.stations) && stationsState.stations.length > 0) {
        seatBtn = '<button type="button" class="btn-dash btn-outline btn-xs" onclick="umCheckInAndSeat(\'' + esc(found.id) + '\')"><i class="fa-solid fa-chair"></i> Deduct &amp; Seat (Open)</button>';
      }
      var resHtml = '<div style="display:flex;align-items:center;justify-content:space-between;gap:0.75rem;flex-wrap:wrap;width:100%;">' +
        '<div><i class="fa-solid fa-circle-check text-green"></i> <strong>Credit Pack Verified:</strong> ' + esc(found.customerName || found.name) + ' (' + esc(found.planName || found.passTier) + ') · Credits Left: <strong class="text-accent">' + left + ' / ' + tot + '</strong> (Code: ' + esc(found.code || found.passCode) + ')' + (found.stationBinding && found.stationBinding !== 'any' ? ' · <span class="text-teal font-medium"><i class="fa-solid fa-chair"></i> ' + esc(found.stationBinding.replace('station:', '').replace('category:', 'Zone: ')) + '</span>' : '') + '</div>' +
        '<div style="display:flex;gap:0.5rem;align-items:center;">' +
          seatBtn +
          '<button type="button" class="btn-dash btn-accent btn-xs" onclick="umRedeemSpecificPass(\'' + esc(found.id) + '\')"><i class="fa-solid fa-check-to-slot"></i> Deduct 1 Credit</button>' +
        '</div>' +
      '</div>';
      renderResult(resHtml, 'credit-verify-res-success');
    }
  } else {
    umState.lastVerifiedPass = null;
    renderResult('<i class="fa-solid fa-triangle-exclamation"></i> <strong>No pass found matching</strong> "' + esc(q) + '". Verify customer phone, pass code, or name.', 'credit-verify-res-error');
  }
}

function umRedeemCredit(scope) {
  var targets = umGetVerifyTargets(scope);
  var input = targets.input;
  var res = targets.res;
  var query = input ? input.value.trim().toLowerCase() : '';
  var qClean = query.replace(/\D/g, '');

  var pass = umState.lastVerifiedPass;
  if (!pass && query) {
    pass = (umState.passes || []).find(function (p) {
      var pPhone = String(p.phone || p.customerPhone || '').toLowerCase();
      var pPhoneClean = pPhone.replace(/\D/g, '');
      var phoneMatched = (qClean.length >= 4 && pPhoneClean.indexOf(qClean) !== -1);
      var pCode = String(p.code || p.passCode || '').toLowerCase();
      var pName = String(p.customerName || p.name || '').toLowerCase();
      var pId = String(p.id || '').toLowerCase();
      var pVoucher = String(p.voucherCode || '').toLowerCase();
      return phoneMatched ||
             (pPhone && pPhone.indexOf(query) !== -1) ||
             (pCode && pCode.indexOf(query) !== -1) ||
             (pName && pName.indexOf(query) !== -1) ||
             (pId && pId.indexOf(query) !== -1) ||
             (pVoucher && pVoucher.indexOf(query) !== -1);
    });
  }

  if (!pass) {
    umVerifyCredit(scope);
    if (!umState.lastVerifiedPass) return;
    pass = umState.lastVerifiedPass;
  }

  var pFlav = pass.passFlavor || (pass.type === 'voucher' ? 'voucher' : (pass.type === 'membership' ? 'membership' : ((pass.totalCredits != null || pass.creditsLeft != null) ? 'credit_pack' : 'membership')));
  if (pFlav === 'membership' || (pass.totalCredits == null && !pass.creditsLeft && pFlav !== 'credit_pack')) {
    umCheckInCustomerPass(pass.id);
    return;
  }

  umRedeemSpecificPass(pass.id);
}

function umRedeemPassCredit(passId) {
  umRedeemSpecificPass(passId);
}

function umDeletePass(passId) {
  umDeleteSpecificPass(passId);
}

function umFilterOrders(status, btnEl) {
  umState.orderFilter = status;
  if (btnEl && btnEl.parentNode) {
    var tabs = btnEl.parentNode.querySelectorAll('.filter-tab');
    tabs.forEach(function (tEl) { tEl.classList.remove('active'); });
    btnEl.classList.add('active');
  }
  umRenderOrders();
}

function umRenderOrders() {
  var tbody = $('um-orders-tbody');
  if (!tbody) return;

  var list = umState.orders;
  if (umState.orderFilter !== 'all') {
    list = list.filter(function (o) { return o.status === umState.orderFilter; });
  }

  if (list.length === 0) {
    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;color:var(--text-muted);padding:1.5rem;">No orders matching status "' + esc(umState.orderFilter) + '".</td></tr>';
    return;
  }

  tbody.innerHTML = list.map(function (o) {
    var statusClass = 'pill-amber';
    if (o.status === 'shipped') statusClass = 'pill-blue';
    if (o.status === 'completed') statusClass = 'pill-green';

    var nextBtn = '';
    if (o.status === 'pending') {
      nextBtn = '<button class="btn-dash btn-accent btn-sm" onclick="umUpdateOrderStatus(\'' + esc(o.orderNo) + '\', \'shipped\')"><i class="fa-solid fa-truck"></i> Mark Shipped</button>';
    } else if (o.status === 'shipped') {
      nextBtn = '<button class="btn-dash btn-accent btn-sm" onclick="umUpdateOrderStatus(\'' + esc(o.orderNo) + '\', \'completed\')"><i class="fa-solid fa-check"></i> Mark Complete</button>';
    } else {
      nextBtn = '<span style="font-size:0.75rem;color:var(--text-muted);">Done</span>';
    }

    return '<tr>' +
      '<td style="font-weight:700;font-family:monospace;">' + esc(o.orderNo) + '</td>' +
      '<td style="font-weight:600;">' + esc(o.customerName) + '</td>' +
      '<td>' + esc(o.item) + '</td>' +
      '<td>' + esc(o.amount != null ? fmtPrice(o.amount, o.currency || defaultCurrency()) : '-') + '</td>' +
      '<td><span class="pill ' + statusClass + '">' + esc(o.status.toUpperCase()) + '</span></td>' +
      '<td style="color:var(--text-muted);white-space:nowrap;">' + esc(fmtDate(o.createdAt)) + '</td>' +
      '<td style="text-align:right;white-space:nowrap;">' + nextBtn + '</td>' +
    '</tr>';
  }).join('');
}

function umRenderRentalsAndVouchers() {
  var rBody = $('um-rentals-tbody');
  if (rBody) {
    if (umState.rentals.length === 0) {
      rBody.innerHTML = '<tr><td colspan="4" style="text-align:center;color:var(--text-muted);padding:1rem;">No asset rentals recorded.</td></tr>';
    } else {
      rBody.innerHTML = umState.rentals.map(function (r) {
        var sClass = r.status === 'active' ? 'pill-green' : 'pill-gray';
        return '<tr>' +
          '<td style="font-weight:600;">' + esc(r.assetName) + '</td>' +
          '<td>' + esc(r.customerName) + '</td>' +
          '<td style="color:var(--text-muted);">' + esc(r.checkoutDate) + '</td>' +
          '<td><span class="pill ' + sClass + '">' + esc(r.status.toUpperCase()) + '</span></td>' +
        '</tr>';
      }).join('');
    }
  }

  var vContainer = $('um-vouchers-container');
  if (vContainer) {
    if (umState.vouchers.length === 0) {
      vContainer.innerHTML = '<div style="color:var(--text-muted);font-size:0.8125rem;">No active vouchers.</div>';
    } else {
      vContainer.innerHTML = umState.vouchers.map(function (v) {
        return '<div class="voucher-stat-card">' +
          '<div><span class="voucher-code-badge">' + esc(v.code) + '</span> <span style="margin-left:0.5rem;font-weight:500;color:var(--text-secondary);">' + esc(v.discount) + '</span></div>' +
          '<div style="font-size:0.75rem;color:var(--text-muted);">Used: <strong>' + v.usedCount + '</strong> / ' + v.usageLimit + '</div>' +
        '</div>';
      }).join('');
    }
  }
}



