/* ── Bookings WA Reminder Settings (R2) ── */
var waReminderSettings = {
  reminder24h: true,
  reminder1h: true
};

function toggleWaReminder(timing) {
  if (timing === '24h') {
    waReminderSettings.reminder24h = !waReminderSettings.reminder24h;
    var t24 = $('toggle-wa-reminder-24h');
    if (t24) t24.className = 'toggle-switch ' + (waReminderSettings.reminder24h ? 'on' : '');
  } else if (timing === '1h') {
    waReminderSettings.reminder1h = !waReminderSettings.reminder1h;
    var t1 = $('toggle-wa-reminder-1h');
    if (t1) t1.className = 'toggle-switch ' + (waReminderSettings.reminder1h ? 'on' : '');
  }
}

/* Reminder channels (PRD 16.2A): WhatsApp-only. Legacy 'email'/'both' values
   are normalized to 'wa' so no email reminder is ever dispatched. */
function setReminderChannel(timing, channel) {
  if (typeof waReminderSettings !== 'undefined') {
    if (!waReminderSettings.channels) waReminderSettings.channels = {};
    waReminderSettings.channels[timing] = (channel === 'email' || channel === 'both') ? 'wa' : 'wa';
  }
  try { localStorage.setItem('codaxiom-wa-reminders:' + waAiGetSubdomain(), JSON.stringify(waReminderSettings)); } catch (e) {}
  if (typeof waAiSaveConfig === 'function') waAiSaveConfig(true);
  showToast(t('bookings.reminderChannelSaved', 'WhatsApp reminder settings saved.'), 'success');
}
window.setReminderChannel = setReminderChannel;

function saveWaReminderSettings() {
  try {
    localStorage.setItem('codaxiom-wa-reminders:' + waAiGetSubdomain(), JSON.stringify(waReminderSettings));
  } catch (e) {}
  showToast('Automated WhatsApp reminder settings saved', 'info');
}

function dispatchApptWaReminder(customer, phone, date, time) {
  var msg = 'Reminder: Hello ' + customer + ', your appointment is scheduled for ' + date + ' at ' + time + '. Reply 1 to confirm or 2 to reschedule.';
  /* Law 2026-08-19: the engine chat-send requires { subdomain, phone, message }
     — the old payload sent recipientPhone without subdomain and silently 400'd
     while the UI toasted success. Honest success/error now. */
  apiPost('/api/admin/chat-send', { subdomain: waAiGetSubdomain(), phone: phone, message: msg })
    .then(function () {
      showToast('WhatsApp reminder dispatched to ' + customer + ' (' + phone + ')', 'info');
    })
    .catch(function () {
      showToast('Failed to dispatch WhatsApp reminder to ' + customer, 'error');
    });
}

/* ── Payments 1-Click Re-Dispatch Payment Link (R2) ── */
function payReDispatchLink(id) {
  var rec = (typeof getPayLinks === 'function' ? getPayLinks() : []).filter(function (r) { return r.id === id; })[0];
  if (!rec) {
    showToast('Payment link record not found', 'error');
    return;
  }
  /* Law 2026-08-19: never send to a hardcoded fallback number. */
  var phone = rec.leadPhone || '';
  if (!phone) {
    showToast('No customer phone on this link record: nothing to dispatch.', 'error');
    return;
  }
  var msg = 'Payment Reminder: Please complete your payment for ' + (rec.itemName || 'your order') + ' using the following secure link: ' + rec.url;
  apiPost('/api/admin/chat-send', { subdomain: waAiGetSubdomain(), phone: phone, message: msg })
    .then(function () {
      rec.lastDispatchedAt = new Date().toISOString();
      if (typeof savePayLinks === 'function' && typeof getPayLinks === 'function') savePayLinks(getPayLinks());
      showToast('Payment link 1-click re-dispatched to ' + phone, 'info');
      renderPayLinksTable();
    })
    .catch(function () {
      showToast('Failed to re-dispatch payment link to ' + phone, 'error');
      renderPayLinksTable();
    });
}

/* ============================================================
   INIT
   ============================================================ */
function initMainDashboard() {
  // Billing suspension banner (2026-08-18)
  renderSuspendedBanner();

  // Demo badge & top banner
  if (DEMO_MODE) {
    var badge = $('demo-badge');
    if (badge) badge.style.display = 'inline-flex';
    var topBanner = $('demo-cockpit-banner');
    if (topBanner) {
      topBanner.style.display = 'flex';
      var params = new URLSearchParams(window.location.search);
      var reqNiche = (params.get('niche') || (window.__dash_session_data && window.__dash_session_data.niche) || '').toLowerCase().trim();
      var nicheName = NICHE_NAMES[reqNiche] || (typeof waAiConfig !== 'undefined' && waAiConfig && waAiConfig.businessName) || 'Master';
      var bannerTextEl = $('demo-cockpit-banner-text');
      if (bannerTextEl) {
        bannerTextEl.textContent = 'Demo Cockpit: Exploring ' + nicheName + ' Master Dashboard : Public preview, actions disabled (read-only)';
      }
    }
  } else {
    var topBanner = $('demo-cockpit-banner');
    if (topBanner) topBanner.style.display = 'none';
    var demoBadgeEl = $('demo-badge');
    if (demoBadgeEl) demoBadgeEl.style.display = 'none';
  }

  // Session identity in sidebar + settings
  var email = null;
  try {
    if (window.__dash_session_data && window.__dash_session_data.email) email = window.__dash_session_data.email;
    else {
      var s = JSON.parse(localStorage.getItem('dash_session') || '{}');
      if (s.email) email = s.email;
    }
  } catch (e) {}
  if (email) {
    var nameEl = $('sidebar-user-name');
    if (nameEl) { nameEl.textContent = email; nameEl.title = email; }
    var av = $('sidebar-avatar');
    if (av) av.textContent = email.substring(0, 2).toUpperCase();
    var accEmail = $('acc-email');
    if (accEmail) accEmail.value = email;
  }

  // Resolve module (query param known now; config may refine later).
  ensureModuleActive(resolveRequestedModuleId());

  // Immediate early taxonomy application (anti-flash law): applies cached or session niche before async fetch.
  applyNicheTaxonomy();

  // Plan gating applies immediately (covers ?plan=) and again after config.
  applyPlanGating();

  // Load config + initial data
  waAiLoadConfig();
  loadOverview();
  setupDocumentUploader();

  // Default active panel
  switchPanel('overview', document.querySelector('.nav-item[data-panel="overview"]'));

  // Enter-key handlers
  var chatInput = $('chat-manual-input');
  if (chatInput) chatInput.addEventListener('keydown', function (ev) { if (ev.key === 'Enter') sendManualMessage(); });

  // Close modal on overlay click
  document.addEventListener('click', function (ev) {
    if (ev.target && ev.target.classList && ev.target.classList.contains('modal-overlay')) {
      ev.target.classList.remove('open');
      ev.target.style.display = 'none';
    }
  });

  // Close active modal or dossier on Escape key
  document.addEventListener('keydown', function (ev) {
    if (ev.key === 'Escape' || ev.key === 'Esc') {
      var openModals = document.querySelectorAll('.modal-overlay.open, .modal-overlay[style*="display: flex"], .modal-overlay[style*="display: block"]');
      openModals.forEach(function (m) {
        m.classList.remove('open');
        m.style.display = 'none';
      });
      var chatLayout = document.querySelector('.chat-layout.dossier-open');
      if (chatLayout && typeof toggleDossierPane === 'function') {
        toggleDossierPane(false);
      }
    }
  });

  // Close customer dossier on click outside
  document.addEventListener('click', function (ev) {
    var chatLayout = document.querySelector('.chat-layout.dossier-open');
    if (!chatLayout) return;
    var dossierPane = $('chat-dossier-pane');
    var toggleBtn = $('btn-toggle-dossier');
    if (dossierPane && toggleBtn) {
      if (!dossierPane.contains(ev.target) && !toggleBtn.contains(ev.target)) {
        toggleDossierPane(false);
      }
    }
  });

  // Global shortcut: press / to focus chat inbox search (when Live Chat panel is active)
  document.addEventListener('keydown', function (ev) {
    if (ev.key === '/' && !ev.ctrlKey && !ev.metaKey && !ev.altKey) {
      var tag = (document.activeElement && document.activeElement.tagName) || '';
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || (document.activeElement && document.activeElement.isContentEditable)) return;
      var searchInput = $('chat-inbox-search');
      var chatPanel = $('panel-live-chat');
      if (searchInput && chatPanel && chatPanel.classList.contains('active')) {
        ev.preventDefault();
        searchInput.focus();
        searchInput.select();
      }
    }
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initMainDashboard);
} else {
  initMainDashboard();
}


/* ── Staff audit log, density & currency preferences (v3-wave PRD 16.8/16.9) ── */
function getCurrentOperator() {
  try { return localStorage.getItem('codaxiom-operator-name:' + waAiGetSubdomain()) || 'Owner'; } catch (e) { return 'Owner'; }
}
function auditStaffAction(action, target) {
  try {
    var key = 'codaxiom-staff-audit:' + waAiGetSubdomain();
    var list = JSON.parse(localStorage.getItem(key) || '[]');
    list.unshift({ ts: new Date().toLocaleString(), action: action, target: target, operator: getCurrentOperator() });
    localStorage.setItem(key, JSON.stringify(list.slice(0, 200)));
    renderStaffAudit();
  } catch (e) {}
}
window.auditStaffAction = auditStaffAction;
function renderStaffAudit() {
  var el = $('staff-audit-log');
  if (!el) return;
  var list = [];
  try { list = JSON.parse(localStorage.getItem('codaxiom-staff-audit:' + waAiGetSubdomain()) || '[]'); } catch (e) {}
  if (!list.length) {
    el.innerHTML = '<div style="font-size:0.8125rem;color:var(--text-muted);padding:0.5rem 0;">' + esc(t('staff.noAudit', 'No staff actions recorded yet.')) + '</div>';
    return;
  }
  el.innerHTML = '<div class="table-responsive"><table class="dash-table"><thead><tr><th>Timestamp</th><th>Operator</th><th>Action</th><th>Target</th></tr></thead><tbody>' +
    list.map(function (a) {
      return '<tr><td style="white-space:nowrap;">' + esc(a.ts) + '</td><td>' + esc(a.operator) + '</td><td>' + esc(a.action) + '</td><td>' + esc(a.target) + '</td></tr>';
    }).join('') + '</tbody></table></div>';
}
window.renderStaffAudit = renderStaffAudit;

/* ── WhatsApp Support Pass Helper ── */
function copySupportPass() {
  var input = $('setting-support-pass-input');
  var pass = input ? input.value.trim() : '';
  if (!pass) return;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(pass).then(function () {
      showToast(t('settings.supportPassCopied', 'WhatsApp Support Pass copied to clipboard: ') + pass, 'success');
    }).catch(function () {
      showToast(t('settings.supportPassCopyFail', 'Support pass: ') + pass, 'info');
    });
  } else {
    if (input) { input.select(); document.execCommand('copy'); }
    showToast(t('settings.supportPassCopied', 'WhatsApp Support Pass copied to clipboard: ') + pass, 'success');
  }
}
window.copySupportPass = copySupportPass;

function renderSupportPass() {
  var input = $('setting-support-pass-input');
  if (!input) return;
  var pass = (waAiConfig && (waAiConfig.supportPass || waAiConfig.supportPassPlain)) || '';
  var chatBtn = $('btn-chat-codaxiom-support');
  if (!pass) {
    input.value = '';
    input.placeholder = t('settings.supportPassFromEmail', 'Sent in your handoff email (reply to support to re-issue)');
    if (chatBtn) {
      chatBtn.href = 'https://wa.me/628139939013?text=' + encodeURIComponent(t('settings.supportChatPrefill', 'Hi Codaxiom Support, I need assistance with my dashboard.'));
    }
    return;
  }
  input.value = pass;
  if (chatBtn) {
    var text = 'Hi Codaxiom Support, I need assistance with my dashboard. My support pass is: ' + pass;
    chatBtn.href = 'https://wa.me/628139939013?text=' + encodeURIComponent(text);
  }
}
window.renderSupportPass = renderSupportPass;

