/* ── Data Sovereignty & Obsidian Vault Exports ── */
function exportAllData() {
  var exportBlob = {
    version: '1.0',
    exportDate: new Date().toISOString(),
    businessConfig: waAiConfig,
    catalog: (typeof catalogState !== 'undefined' && Array.isArray(catalogState)) ? catalogState : [],
    paymentLinks: (typeof getPayLinks === 'function') ? getPayLinks() : [],
    orders: (typeof ordersData !== 'undefined' && Array.isArray(ordersData)) ? ordersData : [],
    appointments: (window.fixtureState && window.fixtureState.appointments) || []
  };
  var jsonStr = JSON.stringify(exportBlob, null, 2);
  var blob = new Blob([jsonStr], { type: 'application/json' });
  var url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = ((waAiConfig && waAiConfig.businessName) ? waAiConfig.businessName.toLowerCase().replace(/[^a-z0-9]/g, '_') : 'dashboard') + '_full_export_' + Date.now() + '.json';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast('All business data exported to JSON successfully.', 'success');
}
