/* ── Static shell label translator (data-i18n attributes, Phase B prereq) ── */
function i18nShell() {
  var dict = window.DASH_I18N;
  if (!dict) return;
  document.querySelectorAll('[data-i18n]').forEach(function (el) {
    var key = el.getAttribute('data-i18n');
    var val = key.split('.').reduce(function (o, k) { return (o && o[k] !== undefined) ? o[k] : undefined; }, dict);
    if (val === undefined) return; // missing key: keep the built-in English label
    if (!el.hasAttribute('data-i18n-icon')) {
      var icon = el.querySelector('i');
      el.setAttribute('data-i18n-icon', icon ? icon.outerHTML : '');
    }
    el.innerHTML = (el.getAttribute('data-i18n-icon') || '') + esc(val);
  });
}
window.i18nShell = i18nShell;


