function kpiDelta(el, today, yesterday) {
  if (!el) return;
  el.className = 'kpi-delta';
  if (typeof yesterday === 'number' && yesterday > 0) {
    var pct = Math.round(((today - yesterday) / yesterday) * 100);
    if (pct === 0) { el.innerHTML = '<i class="fa-solid fa-minus"></i> ' + esc(String(pct)) + '%'; el.className += ' neutral'; }
    else if (pct > 0) { el.innerHTML = '<i class="fa-solid fa-caret-up"></i> ' + esc(String(pct)) + '%'; el.className += ' up'; }
    else { el.innerHTML = '<i class="fa-solid fa-caret-down"></i> ' + esc(String(Math.abs(pct))) + '%'; el.className += ' down'; }
  } else if (today > 0) {
    el.innerHTML = '+' + esc(String(today)) + ' new'; el.className += ' up';
  } else {
    el.innerHTML = ''; el.className += ' flat';
  }
}

/* ── Overview KPI Theme-Calibrated Palette & Formatting Engine ── */
function getOverviewThemePalette(isDark) {
  if (isDark) {
    return {
      teal: '#0E9AA7',
      gold: '#E2B13C',
      green: '#10B981',
      purple: '#8B5CF6',
      fillOpacityFrom: 0.40,
      fillOpacityTo: 0.05,
      gridBorder: 'oklch(0.95 0.01 240 / 0.08)',
      axisColor: 'oklch(0.60 0.03 240)'
    };
  }
  return {
    teal: '#0A6B75',   // deep maritime petrol (WCAG AA >= 5:1 contrast on white)
    gold: '#B87A10',   // rich burnished bronze amber (WCAG AA >= 4.8:1 contrast on white)
    green: '#0D8259',  // deep forest emerald (WCAG AA >= 5:1 contrast on white)
    purple: '#6D28D9', // deep royal violet (WCAG AA >= 5:1 contrast on white)
    fillOpacityFrom: 0.16,
    fillOpacityTo: 0.02,
    gridBorder: 'oklch(0.18 0.03 240 / 0.08)',
    axisColor: 'oklch(0.35 0.03 240)'
  };
}
window.getOverviewThemePalette = getOverviewThemePalette;

function formatCompactKpi(val, cur) {
  if (typeof val !== 'number' || isNaN(val)) return '0';
  cur = cur || (typeof defaultCurrency === 'function' ? defaultCurrency() : 'IDR');
  if (cur === 'IDR') {
    if (Math.abs(val) >= 1000000000) {
      return 'Rp ' + (val / 1000000000).toFixed(val % 1000000000 === 0 ? 0 : 2).replace('.', ',') + 'M';
    }
    if (Math.abs(val) >= 1000000) {
      return 'Rp ' + (val / 1000000).toFixed(val % 1000000 === 0 ? 0 : 2).replace('.', ',') + 'jt';
    }
    return typeof formatCurrency === 'function' ? formatCurrency(val, cur) : ('Rp ' + val.toLocaleString('id-ID'));
  }
  var sym = cur === 'USD' ? '$' : (cur === 'EUR' ? '€' : (cur === 'GBP' ? '£' : cur + ' '));
  if (val === 0) return sym + '0';
  if (Math.abs(val) >= 1000000) {
    return sym + (val / 1000000).toFixed(val % 1000000 === 0 ? 0 : 2) + 'M';
  }
  if (Math.abs(val) >= 1000) {
    return sym + (val / 1000).toFixed(val % 1000 === 0 ? 0 : 1) + 'k';
  }
  return sym + Math.round(val);
}
window.formatCompactKpi = formatCompactKpi;

