function openStationWalkInModal(stationId) {
  var modal = document.getElementById('modal-station-walkin');
  if (!modal) return;

  var st = stationsState.stations.find(function (s) { return s.id === stationId; });
  var idInput = document.getElementById('st-walkin-station-id');
  if (idInput) idInput.value = stationId || '';

  var titleEl = document.getElementById('st-walkin-modal-title');
  if (titleEl) titleEl.textContent = 'Seat Walk-In Guest: ' + (st ? st.name : 'Station');

  var guestInput = document.getElementById('st-walkin-guest-name');
  if (guestInput) guestInput.value = 'Walk-In Guest';

  var partyInput = document.getElementById('st-walkin-party-size');
  if (partyInput) partyInput.value = (st && st.capacity) ? st.capacity : 1;

  var notesInput = document.getElementById('st-walkin-notes');
  if (notesInput) notesInput.value = '';

  var sel = document.getElementById('st-walkin-service-select');
  if (sel) {
    var catalog = (typeof catalogState !== 'undefined' && Array.isArray(catalogState) && catalogState.length > 0)
      ? catalogState
      : ((window.waAiState && Array.isArray(window.waAiState.catalog) && window.waAiState.catalog.length > 0)
          ? window.waAiState.catalog
          : []);
    var services = catalog.filter(function (it) { return it.active && (it.type === 'service' || it.type === 'booking'); });
    var opts = '<option value="">General Visit / Open Session</option>';
    services.forEach(function (s) {
      opts += '<option value="' + escapeHtml(s.name) + '">' + escapeHtml(s.name) + ' (' + (s.duration || 30) + ' min)</option>';
    });
    sel.innerHTML = opts;
  }

  modal.classList.add('open');
}
