function stationSetNewCatDuration(min) {
  min = Math.max(5, parseInt(min, 10) || 60);
  var input = document.getElementById('st-new-cat-duration-val');
  if (input) input.value = min;
  var presets = document.querySelectorAll('#st-new-cat-dur-presets .cat-preset-btn');
  for (var i = 0; i < presets.length; i++) {
    var pMin = parseInt(presets[i].getAttribute('data-dur'), 10);
    if (pMin === min) presets[i].classList.add('active');
    else presets[i].classList.remove('active');
  }
  var treeWrap = document.getElementById('st-new-cat-services-tree-wrap');
  if (treeWrap && treeWrap.style.display !== 'none') {
    renderNewCatServicesTree();
  }
}
