  var display = document.getElementById('st-new-cat-model-display');
  if (display) {
    var iconClass = icon.indexOf('text-') >= 0 ? icon : (icon + ' text-teal');
    display.innerHTML = '<i class="fa-solid ' + iconClass + '"></i><span>' + escapeHtml(label) + '</span>';
  }
  var wrap = document.getElementById('st-new-cat-model-wrap');
