function stationSetNewCatServicesScope(scope) {
  var hidden = document.getElementById('st-new-cat-services-scope');
  if (hidden) hidden.value = scope;

  var allBtn = document.getElementById('st-new-cat-scope-all-btn');
  var customBtn = document.getElementById('st-new-cat-scope-custom-btn');
  if (allBtn) allBtn.classList.toggle('active', scope === 'all');
  if (customBtn) customBtn.classList.toggle('active', scope === 'custom');

  var allNotice = document.getElementById('st-new-cat-services-all-notice');
  var treeWrap = document.getElementById('st-new-cat-services-tree-wrap');

  if (scope === 'custom') {
    if (allNotice) allNotice.style.display = 'none';
    if (treeWrap) treeWrap.style.display = 'block';
    renderNewCatServicesTree();
  } else {
    if (allNotice) allNotice.style.display = 'flex';
    if (treeWrap) treeWrap.style.display = 'none';
  }
}
