function printBatchStationStands() {
  document.body.classList.add('is-printing-qr-batch');
  var cleanup = function() {
    document.body.classList.remove('is-printing-qr-batch');
    window.removeEventListener('afterprint', cleanup);
  };
  window.addEventListener('afterprint', cleanup);
  window.print();
  setTimeout(cleanup, 1500);
}

function formatStationPrice(amount, currency) {
  var num = Number(amount) || 0;
  var cur = currency || (typeof defaultCurrency === 'function' ? defaultCurrency() : 'IDR');
  if (typeof fmtPrice === 'function') {
    return fmtPrice(num, cur);
  }
  if (typeof formatCurrency === 'function') {
    return formatCurrency(num, cur);
  }
  return cur + ' ' + num.toLocaleString();
}

function getTimeElapsedStr(isoStr) {
  if (!isoStr) return '';
  var ms = Date.now() - new Date(isoStr).getTime();
  var mins = Math.floor(ms / 60000);
  if (mins < 1) return 'Just now';
  if (mins < 60) return mins + 'm ago';
  var hrs = Math.floor(mins / 60);
  return hrs + 'h ' + (mins % 60) + 'm ago';
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

