/* ============================================================
   TRI-TIER REFUND EXECUTION SYSTEM (Law 2026-09-06)
   ------------------------------------------------------------
   Full refund, partial refund (restocking/admin fee deducted),
   or final sale policy compliance.
   Rail-aware routing: Stripe / Midtrans Card -> automated API reversal;
   Indonesian VA / QRIS -> assisted bank disbursement with receipt.
   ============================================================ */
var currentRefundContext = null;

function openRefundModal(orderIdOrObj) {
  if (!dashCan('orders_manage') && !dashCan('payments_send')) {
    showToast(t('staff.noPermission', 'You do not have permission for this action.'), 'error');
    return;
  }
  var order = null;
  var orderId = '';
  if (typeof orderIdOrObj === 'object' && orderIdOrObj !== null) {
    order = orderIdOrObj;
    orderId = order.orderId || order.orderNo || order.id || '';
  } else {
    orderId = String(orderIdOrObj || '');
    // Search in umState.orders first
    if (umState && Array.isArray(umState.orders)) {
      order = umState.orders.find(function (o) {
        return o.orderId === orderId || o.orderNo === orderId || o.id === orderId;
      });
    }
    // If not found, search in payLinks
    if (!order) {
      var payLinks = getPayLinks();
      var pLink = payLinks.find(function (r) {
        return r.id === orderId || r.orderId === orderId;
      });
      if (pLink) {
        order = {
          orderId: pLink.id,
          orderNo: pLink.id,
          itemId: pLink.itemId || '',
          item: pLink.itemName || 'Catalog Order',
          customerName: pLink.customerName || 'Customer',
          phone: pLink.leadPhone || '',
          amount: Number(pLink.amount) || 0,
          currency: pLink.currency || defaultCurrency(),
          gateway: pLink.gateway || 'midtrans',
          status: pLink.status,
          createdAt: pLink.sentAt || new Date().toISOString(),
          rawPayload: pLink.rawPayload
        };
      }
    }
  }

  if (!order) {
    showToast('Order record #' + orderId + ' not found.', 'error');
    return;
  }

  // Find linked catalog item to get its refund policy
  var catItem = null;
  if (order.itemId && Array.isArray(catalogState)) {
    catItem = catalogState.find(function (it) { return it.id === order.itemId; });
  }
  if (!catItem && Array.isArray(catalogState)) {
    catItem = catalogState.find(function (it) {
      return catItemName(it).toLowerCase() === String(order.item || order.items || '').toLowerCase();
    });
  }

  var policy = (catItem && catItem.refundPolicy) || 'full';
  var windowHours = catItem && catItem.refundWindowHours != null ? Number(catItem.refundWindowHours) : 24;
  var feePercent = catItem && catItem.refundFeePercent != null ? Number(catItem.refundFeePercent) : (policy === 'partial' ? 15 : 0);
  var noticeText = (catItem && catItem.refundNoticeText) || '';

  // Calculate elapsed time
  var orderTime = new Date(order.createdAt || Date.now()).getTime();
  var elapsedHours = Math.max(0, (Date.now() - orderTime) / (1000 * 60 * 60));
  var isWithinWindow = windowHours === 0 || elapsedHours <= windowHours;

  // Parse rawPayload for fulfillment & courier metadata
  var parsedFulfillment = null;
  var parsedPayload = null;
  if (order.rawPayload) {
    try {
      parsedPayload = typeof order.rawPayload === 'string' ? JSON.parse(order.rawPayload) : order.rawPayload;
      if (parsedPayload && parsedPayload.fulfillment) parsedFulfillment = parsedPayload.fulfillment;
    } catch (_) {}
  }

  var rawShipping = Number(order.shippingFee) || (parsedPayload && Number(parsedPayload.shippingFee)) || (parsedFulfillment && Number(parsedFulfillment.shippingFee)) || 0;
  var isDispatched = order.status === 'shipped' ||
    order.status === 'completed' ||
    (order.fulfillmentStatus === 'in_transit' || order.fulfillmentStatus === 'shipped' || order.fulfillmentStatus === 'delivered') ||
    (parsedFulfillment && (parsedFulfillment.status === 'in_transit' || parsedFulfillment.status === 'shipped' || parsedFulfillment.status === 'delivered')) ||
    Boolean(order.trackingNumber && order.trackingNumber !== '-') ||
    Boolean(parsedFulfillment && parsedFulfillment.trackingNumber && parsedFulfillment.trackingNumber !== '-');

  var carrierName = order.carrier || (parsedFulfillment && parsedFulfillment.carrier) || (parsedPayload && parsedPayload.carrier) || 'Courier';
  var trackingNo = order.trackingNumber || (parsedFulfillment && parsedFulfillment.trackingNumber) || (parsedPayload && parsedPayload.trackingNumber) || '-';

  var grossPaid = Number(order.amount) || 0;
  var refundHistory = Array.isArray(order.refundHistory) ? order.refundHistory : [];
  if (!refundHistory.length && order.refundPayload) {
    refundHistory.push(order.refundPayload);
  }
  if (!refundHistory.length && parsedPayload) {
    if (Array.isArray(parsedPayload.refundHistory)) refundHistory = parsedPayload.refundHistory;
    else if (parsedPayload.refund) refundHistory = [parsedPayload.refund];
  }
  var previouslyRefunded = refundHistory.reduce(function (sum, r) { return sum + (Number(r.amount) || 0); }, 0);

  // Pre-dispatch vs Post-dispatch refundable balance calculation
  var remainingRefundable = Math.max(0, grossPaid - previouslyRefunded);
  if (isDispatched && rawShipping > 0) {
    // Freight postage is non-refundable; max refund is capped to merchandise subtotal
    remainingRefundable = Math.max(0, grossPaid - previouslyRefunded - rawShipping);
  }

  currentRefundContext = {
    order: order,
    catItem: catItem,
    policy: policy,
    windowHours: windowHours,
    feePercent: feePercent,
    elapsedHours: elapsedHours,
    isWithinWindow: isWithinWindow,
    currency: order.currency || (waAiConfig && waAiConfig.currency) || defaultCurrency(),
    grossAmount: grossPaid,
    rawShipping: rawShipping,
    isDispatched: isDispatched,
    carrierName: carrierName,
    trackingNo: trackingNo,
    previouslyRefunded: previouslyRefunded,
    remainingRefundable: remainingRefundable
  };

  // Populate UI
  $('refund-order-id').value = order.orderId || order.orderNo || order.id;
  $('refund-order-subdomain').value = waAiGetSubdomain();
  $('refund-gross-amount').value = String(currentRefundContext.grossAmount);
  $('refund-currency').value = currentRefundContext.currency;
  $('refund-item-id').value = (catItem && catItem.id) || order.itemId || '';
  $('refund-item-policy').value = policy;

  $('refund-diag-item').textContent = order.item || order.items || 'Catalog Order';
  $('refund-diag-orderno').textContent = order.orderNo || order.orderId;
  $('refund-diag-cust').textContent = order.customerName || order.customer || 'Customer';

  if (previouslyRefunded > 0) {
    $('refund-diag-amount').innerHTML = esc(fmtPrice(grossPaid, currentRefundContext.currency)) +
      '<div style="font-size:0.75rem;color:var(--text-muted);margin-top:0.25rem;">' +
      '<span class="text-amber">Prev. Refunded: ' + esc(fmtPrice(previouslyRefunded, currentRefundContext.currency)) + '</span> · ' +
      '<strong>Max Remaining: ' + esc(fmtPrice(remainingRefundable, currentRefundContext.currency)) + '</strong></div>';
  } else {
    $('refund-diag-amount').textContent = fmtPrice(grossPaid, currentRefundContext.currency);
  }

  var gwBadge = $('refund-diag-gateway-badge');
  if (gwBadge) {
    gwBadge.innerHTML = order.gateway === 'stripe'
      ? '<span class="badge" style="background:var(--status-blue-bg);color:var(--status-blue);font-size:0.6875rem;padding:0.15rem 0.45rem;border-radius:4px;"><i class="fa-brands fa-stripe"></i> Stripe</span>'
      : '<span class="badge" style="background:var(--status-green-bg);color:var(--status-green);font-size:0.6875rem;padding:0.15rem 0.45rem;border-radius:4px;"><i class="fa-solid fa-bolt"></i> Midtrans</span>';
  }

  // Policy Compliance Banner
  var banner = $('refund-policy-compliance-banner');
  var iconEl = $('refund-policy-icon');
  var titleEl = $('refund-policy-status-title');
  var descEl = $('refund-policy-status-desc');

  if (policy === 'none') {
    if (banner) { banner.style.borderColor = 'oklch(0.65 0.20 25 / 0.4)'; banner.style.background = 'oklch(0.65 0.20 25 / 0.08)'; }
    if (iconEl) iconEl.className = 'fa-solid fa-ban text-rose';
    if (titleEl) titleEl.textContent = 'Final Sale Offering (Policy: No Refund)';
    if (descEl) descEl.textContent = 'This item is designated as Final Sale. Operator override required for accounting record.' + (noticeText ? ' Notice: ' + noticeText : '');
  } else if (!isWithinWindow) {
    if (banner) { banner.style.borderColor = 'oklch(0.78 0.16 65 / 0.4)'; banner.style.background = 'oklch(0.78 0.16 65 / 0.08)'; }
    if (iconEl) iconEl.className = 'fa-solid fa-triangle-exclamation text-amber';
    if (titleEl) titleEl.textContent = 'Policy Window Expired (' + Math.round(elapsedHours) + 'h elapsed / ' + windowHours + 'h allowed)';
    if (descEl) descEl.textContent = 'Order is outside the standard refund window. Management discretion override.' + (noticeText ? ' Notice: ' + noticeText : '');
  } else {
    if (banner) { banner.style.borderColor = 'oklch(0.75 0.18 150 / 0.4)'; banner.style.background = 'oklch(0.75 0.18 150 / 0.08)'; }
    if (iconEl) iconEl.className = 'fa-solid fa-circle-check text-green';
    if (titleEl) titleEl.textContent = 'Eligible for Refund (' + policy.toUpperCase() + ' Policy)';
    if (descEl) descEl.textContent = 'Within ' + windowHours + '-hour eligible policy window (' + Math.round(elapsedHours) + 'h elapsed).' + (noticeText ? ' Notice: ' + noticeText : '');
  }

  // Progressive Shipping & Courier Dispatch Disclosure
  var shipWrap = $('refund-shipping-disclosure-wrap');
  var preCard = $('refund-pre-dispatch-card');
  var postCard = $('refund-post-dispatch-card');
  if (shipWrap) {
    if (rawShipping > 0) {
      shipWrap.style.display = 'block';
      if (!isDispatched) {
        if (preCard) preCard.style.display = 'block';
        if (postCard) postCard.style.display = 'none';
        var preFeeEl = $('refund-pre-shipping-fee');
        if (preFeeEl) preFeeEl.textContent = fmtPrice(rawShipping, currentRefundContext.currency);
      } else {
        if (preCard) preCard.style.display = 'none';
        if (postCard) postCard.style.display = 'block';
        var postCarrierEl = $('refund-post-carrier-name');
        if (postCarrierEl) postCarrierEl.textContent = carrierName;
        var postTrackEl = $('refund-post-tracking-no');
        if (postTrackEl) postTrackEl.textContent = trackingNo;
        var postFeeEl = $('refund-post-shipping-fee');
        if (postFeeEl) postFeeEl.textContent = fmtPrice(rawShipping, currentRefundContext.currency);
      }
    } else {
      shipWrap.style.display = 'none';
      if (preCard) preCard.style.display = 'none';
      if (postCard) postCard.style.display = 'none';
    }
  }

  // Physical Restock Option
  var isPhysical = (catItem && (catItem.type === 'product' || catItem.requiresDelivery)) || (order.fulfillmentType && order.fulfillmentType !== 'pickup');
  var restockGroup = $('refund-restock-group');
  if (restockGroup) {
    restockGroup.style.display = isPhysical ? 'block' : 'none';
    var restockDesc = $('refund-restock-desc');
    var qty = order.quantity || 1;
    if (restockDesc) restockDesc.textContent = 'Return ' + qty + ' unit' + (qty > 1 ? 's' : '') + ' back to catalog inventory count.';
  }

  // Gateway Rail-Aware Card
  var isCard = order.gateway === 'stripe' || (order.rawPayload && String(order.rawPayload).indexOf('credit_card') !== -1);
  var cardView = $('refund-rail-card-view');
  var vaView = $('refund-rail-va-view');
  var submitText = $('refund-submit-btn-text');

  if (isCard) {
    if (cardView) cardView.style.display = 'block';
    if (vaView) vaView.style.display = 'none';
    if (submitText) submitText.textContent = 'Process Gateway Reversal';
  } else {
    if (cardView) cardView.style.display = 'none';
    if (vaView) vaView.style.display = 'block';
    if (submitText) submitText.textContent = 'Confirm Bank Payout Dispatched';
  }

  // Initialize refund type
  var initialType = policy === 'partial' ? 'partial' : 'full';
  setRefundType(initialType);

  $('modal-order-refund').classList.add('open');
}
window.openRefundModal = openRefundModal;

function closeRefundModal() {
  var m = $('modal-order-refund');
  if (m) m.classList.remove('open');
  currentRefundContext = null;
}
window.closeRefundModal = closeRefundModal;

function setRefundType(type) {
  var hidden = $('refund-selected-type');
  if (hidden) hidden.value = type;
  document.querySelectorAll('#refund-type-pills .cat-type-pill').forEach(function (pill) {
    pill.classList.toggle('active', pill.getAttribute('data-refund-type') === type);
  });
  var feeRow = $('refund-calc-fee-row');
  var feeInput = $('refund-input-fee-pct');
  if (type === 'partial') {
    if (feeRow) feeRow.style.display = 'flex';
    if (feeInput) {
      var currentFee = Number(feeInput.value) || 0;
      if (currentFee === 0) {
        feeInput.value = (currentRefundContext && currentRefundContext.feePercent) || 15;
      }
    }
  } else {
    if (feeRow) feeRow.style.display = 'none';
    if (feeInput) feeInput.value = '0';
  }
  calculateRefundMath();
}
window.setRefundType = setRefundType;

function onRefundFeePctChange(val) {
  calculateRefundMath();
}
window.onRefundFeePctChange = onRefundFeePctChange;

function calculateRefundMath() {
  if (!currentRefundContext) return;
  var maxRefundable = currentRefundContext.remainingRefundable !== undefined ? currentRefundContext.remainingRefundable : currentRefundContext.grossAmount;
  var cur = currentRefundContext.currency;
  var rawShipping = currentRefundContext.rawShipping || 0;
  var isDispatched = currentRefundContext.isDispatched;
  var type = $('refund-selected-type') ? $('refund-selected-type').value : 'full';
  var feePct = 0;
  if (type === 'partial') {
    var inputVal = $('refund-input-fee-pct') ? $('refund-input-fee-pct').value : '15';
    feePct = Math.min(100, Math.max(0, parseFloat(inputVal) || 0));
  }
  var feeAmount = Math.round((maxRefundable * feePct) / 100);
  var netRefund = Math.max(0, maxRefundable - feeAmount);

  if ($('refund-calc-gross')) {
    if (isDispatched && rawShipping > 0) {
      $('refund-calc-gross').innerHTML = esc(fmtPrice(maxRefundable, cur)) +
        ' <span style="font-size:0.75rem;color:var(--text-muted);font-weight:400;">(Merchandise Only &middot; ' + esc(fmtPrice(rawShipping, cur)) + ' Courier Postage Retained)</span>';
    } else if (!isDispatched && rawShipping > 0) {
      $('refund-calc-gross').innerHTML = esc(fmtPrice(maxRefundable, cur)) +
        ' <span style="font-size:0.75rem;color:var(--text-muted);font-weight:400;">(Includes ' + esc(fmtPrice(rawShipping, cur)) + ' Courier Shipping)</span>';
    } else {
      $('refund-calc-gross').textContent = fmtPrice(maxRefundable, cur);
    }
  }
  if ($('refund-calc-fee')) $('refund-calc-fee').textContent = '-' + fmtPrice(feeAmount, cur) + ' (' + feePct + '%)';
  if ($('refund-calc-net')) $('refund-calc-net').textContent = fmtPrice(netRefund, cur);

  var submitBtn = $('btn-submit-refund');
  if (submitBtn) {
    if (maxRefundable <= 0) {
      submitBtn.disabled = true;
      submitBtn.title = 'Order has already been fully refunded.';
    } else {
      submitBtn.disabled = false;
      submitBtn.title = '';
    }
  }
}
window.calculateRefundMath = calculateRefundMath;

function executeOrderRefund() {
  if (!currentRefundContext) return;
  var order = currentRefundContext.order;
  var orderId = order.orderId || order.orderNo || order.id;
  var maxRefundable = currentRefundContext.remainingRefundable !== undefined ? currentRefundContext.remainingRefundable : currentRefundContext.grossAmount;
  if (maxRefundable <= 0) {
    showToast('This order has already been fully refunded.', 'amber');
    return;
  }
  var type = $('refund-selected-type') ? $('refund-selected-type').value : 'full';
  var feePct = $('refund-input-fee-pct') ? parseFloat($('refund-input-fee-pct').value) || 0 : 0;
  var feeAmount = Math.round((maxRefundable * feePct) / 100);
  var netAmount = Math.max(0, maxRefundable - feeAmount);
  var reason = $('refund-reason') ? $('refund-reason').value : 'customer_request';
  var note = $('refund-note') ? $('refund-note').value.trim() : '';
  var restockToggle = $('refund-restock-toggle');
  var restock = restockToggle ? restockToggle.classList.contains('on') : false;
  var notifyWa = $('refund-notify-wa') ? $('refund-notify-wa').checked : true;

  var bankDetails = {
    bankName: $('refund-bank-name') ? $('refund-bank-name').value.trim() : '',
    accountNumber: $('refund-account-number') ? $('refund-account-number').value.trim() : '',
    accountName: $('refund-account-name') ? $('refund-account-name').value.trim() : '',
    transferRef: $('refund-transfer-ref') ? $('refund-transfer-ref').value.trim() : ''
  };

  var payload = {
    subdomain: waAiGetSubdomain(),
    orderId: orderId,
    refundType: type,
    refundCategory: currentRefundContext.isDispatched ? 'post_dispatch_merchandise' : 'pre_dispatch_full',
    shippingDeducted: currentRefundContext.isDispatched ? (currentRefundContext.rawShipping || 0) : 0,
    grossAmount: currentRefundContext.grossAmount,
    previouslyRefunded: currentRefundContext.previouslyRefunded || 0,
    amount: netAmount,
    feeAmount: feeAmount,
    feePercent: feePct,
    currency: currentRefundContext.currency,
    reason: reason,
    note: note,
    restock: restock,
    notifyWa: notifyWa,
    bankDetails: bankDetails
  };

  var btn = $('btn-submit-refund');
  if (btn) btn.disabled = true;

  apiPost('/api/admin/client-payments/refund', payload)
    .then(function (res) {
      if (res && res.success) {
        showToast('Refund of ' + fmtPrice(netAmount, currentRefundContext.currency) + ' successfully recorded!', 'success');
        
        // Update local memory / state
        var newStatus = type === 'full' ? 'refunded' : 'partially_refunded';
        
        // Update payLinks store
        var allLinks = getPayLinks();
        allLinks.forEach(function (r) {
          if (r.id === orderId || r.orderId === orderId) {
            r.status = newStatus;
            r.refundPayload = {
              type: type,
              amount: netAmount,
              feeAmount: feeAmount,
              reason: reason,
              date: new Date().toISOString()
            };
          }
        });
        savePayLinks(allLinks);
        renderPayLinksTable();

        // Update umState.orders
        if (umState && Array.isArray(umState.orders)) {
          umState.orders.forEach(function (o) {
            if (o.orderId === orderId || o.orderNo === orderId || o.id === orderId) {
              o.status = newStatus;
              if (newStatus === 'refunded' && (!o.fulfillmentStatus || o.fulfillmentStatus === 'pending' || o.fulfillmentStatus === 'packing')) {
                o.fulfillmentStatus = 'cancelled';
              }
            }
          });
          renderOrdersPanel();
        }

        // Increment local stock if restock is active
        if (restock && currentRefundContext.catItem && currentRefundContext.catItem.stock != null) {
          var curStock = Number(currentRefundContext.catItem.stock) || 0;
          currentRefundContext.catItem.stock = curStock + (order.quantity || 1);
          waAiRenderCatalog();
        }

        closeRefundModal();
      } else {
        showToast((res && res.error) || 'Failed to process refund.', 'error');
      }
    })
    .catch(function (err) {
      showToast((err && err.message) || 'Network error processing refund.', 'error');
    })
    .then(function () {
      if (btn) btn.disabled = false;
    });
}
window.executeOrderRefund = executeOrderRefund;




/* ==========================================================================
   FRESH REVOLUTIONARY STATION DISPATCH & OPERATIONS BOARD
   ========================================================================== */

var stDispatchFilter = 'all';
var stDispatchSearch = '';

window.switchBookingsSubTab = function(subTabId, navEl) {
  if (subTabId !== 'stations' && subTabId !== 'schedule') subTabId = 'schedule';
  
  try {
    sessionStorage.setItem('codaxiom-dash-bk-subtab', subTabId);
  } catch (e) {}

  // Ensure bookings panel is active if another panel was showing
  var pBk = document.getElementById('panel-bookings');
  if (pBk && !pBk.classList.contains('active')) {
    switchPanel('bookings', null, true);
  }

  var viewStations = document.getElementById('bk-subview-stations');
  var viewSchedule = document.getElementById('bk-subview-schedule');
  var titleText = document.getElementById('bookings-title-text');
  var subtitleText = document.getElementById('bookings-subtitle-text');
  var scheduleActions = document.getElementById('bk-schedule-header-actions');
  var stationsActions = document.getElementById('bk-stations-header-actions');
  var topbarTitle = document.getElementById('topbar-title');

  if (viewStations) viewStations.style.display = subTabId === 'stations' ? 'block' : 'none';
  if (viewSchedule) viewSchedule.style.display = subTabId === 'schedule' ? 'block' : 'none';

  // Toggle dynamic header actions cleanly
  if (scheduleActions) scheduleActions.style.display = subTabId === 'schedule' ? 'flex' : 'none';
  if (stationsActions) stationsActions.style.display = subTabId === 'stations' ? 'flex' : 'none';

  // Synchronize topbar title
  if (topbarTitle) {
    topbarTitle.textContent = subTabId === 'stations' ? 'Stations' : 'Schedule';
  }

  // Synchronize sidebar sub-item active state
  var navSubStations = document.getElementById('nav-sub-bk-stations');
  var navSubSchedule = document.getElementById('nav-sub-bk-schedule');
  if (navSubStations) navSubStations.classList.toggle('active', subTabId === 'stations');
  if (navSubSchedule) navSubSchedule.classList.toggle('active', subTabId === 'schedule');

  // Synchronize in-panel cockpit tabs
  var inPanelStations = document.getElementById('bk-tab-stations');
  var inPanelSchedule = document.getElementById('bk-tab-schedule');
  if (inPanelStations) {
    inPanelStations.classList.toggle('active', subTabId === 'stations');
    inPanelStations.setAttribute('aria-selected', subTabId === 'stations' ? 'true' : 'false');
  }
  if (inPanelSchedule) {
    inPanelSchedule.classList.toggle('active', subTabId === 'schedule');
    inPanelSchedule.setAttribute('aria-selected', subTabId === 'schedule' ? 'true' : 'false');
  }

  // Update dynamic count micro-badges
  var badgeStations = document.getElementById('bk-tab-badge-stations');
  var badgeSchedule = document.getElementById('bk-tab-badge-schedule');
  if (badgeStations) {
    var stCount = (stationsState && Array.isArray(stationsState.stations)) ? stationsState.stations.length : 0;
    badgeStations.textContent = String(stCount);
  }
  if (badgeSchedule) {
    var bkCount = (typeof bkGetBookingsCount === 'function')
      ? bkGetBookingsCount()
      : ((typeof allBookings !== 'undefined' && Array.isArray(allBookings)) ? allBookings.length : 0);
    badgeSchedule.textContent = String(bkCount);
  }

  if (subTabId === 'stations') {
    if (titleText) titleText.textContent = 'Station Operations';
    if (subtitleText) subtitleText.textContent = 'Live unit capacity, visual dispatch, operating schedule, and WhatsApp AI.';
    if (typeof initStationsPanel === 'function') initStationsPanel();
  } else {
    if (titleText) titleText.textContent = 'Operating Schedule';
    if (subtitleText) {
      subtitleText.textContent = 'Calendar appointments, time slots, customer bookings, and blocked windows.';
    }

    renderActiveBlocksShelf();
    if (typeof bkInitBookingsPanel === 'function') bkInitBookingsPanel();
    if (typeof bkRenderAll === 'function') bkRenderAll();
    if (typeof populateBlockTargetDropdown === 'function') populateBlockTargetDropdown();
  }
};

window.bkRefreshActiveSubView = function() {
  var savedSubTab = 'schedule';
  try { savedSubTab = sessionStorage.getItem('codaxiom-dash-bk-subtab') || 'schedule'; } catch(e) {}
  if (savedSubTab === 'stations') {
    if (typeof loadStationsData === 'function') loadStationsData();
  } else {
    renderActiveBlocksShelf();
    if (typeof bkInitBookingsPanel === 'function') bkInitBookingsPanel();
    if (typeof bkRenderAll === 'function') bkRenderAll();
  }
  showToast('Operational data refreshed.', 'info');
};

function ensureStationsDataLoaded() {
  if (stationsState && Array.isArray(stationsState.stations) && stationsState.stations.length > 0) {
    return Promise.resolve(stationsState.stations);
  }

  return apiGet('/api/admin/facility-stations?subdomain=' + encodeURIComponent(waAiGetSubdomain()))
    .then(function(res) {
      if (res && res.success && Array.isArray(res.stations)) {
        stationsState.unitLabel = res.unitLabel || 'Station';
        stationsState.stations = res.stations;
        calculateStationsSummary();
      }
      return stationsState.stations;
    }).catch(function() {
      return stationsState.stations || [];
    });
}
window.ensureStationsDataLoaded = ensureStationsDataLoaded;

window.filterDispatchStations = function(filter, el) {
  stDispatchFilter = filter || 'all';
  if (el) {
    document.querySelectorAll('#bk-dispatch-filter-pills .spaces-filter-chip').forEach(function(c) {
      c.classList.remove('active');
    });
    el.classList.add('active');
  }
  renderDispatchMatrix();
};

window.searchDispatchStations = function(query) {
  stDispatchSearch = (query || '').toLowerCase().trim();
  renderDispatchMatrix();
};

window.renderDispatchMatrix = function() {
  var dispatchCard = document.getElementById('bk-dispatch-card') || document.querySelector('.bk-dispatch-card');
  var isSpacesActive = false;
  if (waAiConfig && waAiConfig.spacesEnabled !== undefined) {
    isSpacesActive = Boolean(waAiConfig.spacesEnabled);
  } else if (window.waAiState && window.waAiState.config && window.waAiState.config.spaces_enabled !== undefined) {
    isSpacesActive = Boolean(window.waAiState.config.spaces_enabled);
  }

  if (dispatchCard && !isSpacesActive) {
    dispatchCard.style.display = 'none';
    return;
  }

  var container = document.getElementById('bk-dispatch-container');
  if (!container) return;

  var stations = (stationsState && Array.isArray(stationsState.stations)) ? stationsState.stations : [];
  var countAll = stations.length;

  // Zero units configured empty state (Clean Neo Kinpaku Craft)
  if (countAll === 0) {
    var uLbl = (stationsState && stationsState.unitLabel) || 'Station';
    container.innerHTML = '<div style="text-align:center;padding:2.75rem 1.5rem;background:var(--bg-card-sub, rgba(255,255,255,0.02));border:1px dashed var(--border-color);border-radius:var(--radius-md);margin-top:0.25rem;">' +
      '<div style="width:48px;height:48px;border-radius:50%;background:rgba(20,184,166,0.1);display:inline-flex;align-items:center;justify-content:center;color:var(--color-teal);font-size:1.25rem;margin:0 auto 0.75rem;">' +
        '<i class="fa-solid fa-table-cells-large"></i>' +
      '</div>' +
      '<div style="font-weight:700;font-size:0.9375rem;color:var(--text-main);margin-bottom:0.25rem;">No ' + escapeHtml(uLbl) + ' Units Configured Yet</div>' +
      '<div style="font-size:0.8125rem;color:var(--text-secondary);max-width:440px;margin:0 auto 1.25rem;line-height:1.5;">' +
        'Set up physical units, tables, chairs, or service bays in the Stations tab to enable visual dispatch operations and live tracking.' +
      '</div>' +
      '<button type="button" class="btn-dash btn-accent btn-sm" onclick="switchBookingsSubTab(\'stations\')">' +
        '<i class="fa-solid fa-sliders"></i> Configure ' + escapeHtml(uLbl) + ' Units' +
      '</button>' +
    '</div>';

    var cAll0 = document.getElementById('st-df-count-all');
    var cAvail0 = document.getElementById('st-df-count-available');
    var cOcc0 = document.getElementById('st-df-count-occupied');
    var cBlk0 = document.getElementById('st-df-count-blocked');
    var cOff0 = document.getElementById('st-df-count-off');
    var cTotalBadge0 = document.getElementById('bk-dispatch-total-badge');
    if (cAll0) cAll0.textContent = '0';
    if (cAvail0) cAvail0.textContent = '0';
    if (cOcc0) cOcc0.textContent = '0';
    if (cBlk0) cBlk0.textContent = '0';
    if (cOff0) cOff0.textContent = '0';
    if (cTotalBadge0) cTotalBadge0.textContent = '0 Units';
    return;
  }

  var blockedSlots = (umState && Array.isArray(umState.blockedSlots)) ? umState.blockedSlots : [];
  var todayStr = typeof bkDateKey === 'function' ? bkDateKey(new Date()) : new Date().toISOString().split('T')[0];

  // Count states
  var countAvail = 0;
  var countOcc = 0;
  var countBlk = 0;
  var countOff = 0;

  var enriched = stations.map(function(st) {
    var isOff = (st.status === 'maintenance' || st.active === false);
    var isOcc = (st.status === 'occupied');
    var isPaid = (st.status === 'paid');

    var activeBlock = blockedSlots.find(function(b) {
      var matchTarget = (!b.targetStationId || b.targetStationId === 'all' || b.targetStationId === st.id || b.targetStationId === ('cat:' + (st.area || st.category)));
      if (!matchTarget) return false;
      if (b.type === 'indefinite') return true;
      if (b.date === todayStr || (b.startDate && b.endDate && todayStr >= b.startDate && todayStr <= b.endDate)) return true;
      return false;
    });

    var state = 'available';
    if (isOff) {
      state = 'off';
      countOff++;
    } else if (isOcc || isPaid) {
      state = 'occupied';
      countOcc++;
    } else if (activeBlock) {
      state = 'blocked';
      countBlk++;
    } else {
      state = 'available';
      countAvail++;
    }

    var parentCat = (stationsState && Array.isArray(stationsState.categories))
      ? stationsState.categories.find(function (c) {
          return (c.name || '').trim().toLowerCase() === (st.area || st.category || 'Main Area').trim().toLowerCase();
        })
      : null;
    var resolvedSessionModel = st.sessionModel || (parentCat && parentCat.sessionModel) || 'open_ended';
    var resolvedFixedDur = parseInt(st.fixedDuration, 10) || (parentCat && parseInt(parentCat.fixedDuration, 10)) || 90;

    return {
      raw: st,
      id: st.id,
      name: st.name || ('Unit ' + (st.unitNumber || '')),
      unitNumber: st.unitNumber || '',
      category: (st.area || st.category || 'Main Area').trim(),
      capacity: st.capacity || (parentCat && parentCat.capacity) || 1,
      duration: st.slotDuration || 30,
      sessionModel: resolvedSessionModel,
      fixedDuration: resolvedFixedDur,
      state: state,
      activeBlock: activeBlock,
      occupiedSince: st.occupiedSince,
      customerName: st.customerName,
      serviceName: st.serviceName
    };
  });

  // Update badge & filter pill counts
  var cAll = document.getElementById('st-df-count-all');
  var cAvail = document.getElementById('st-df-count-available');
  var cOcc = document.getElementById('st-df-count-occupied');
  var cBlk = document.getElementById('st-df-count-blocked');
  var cOff = document.getElementById('st-df-count-off');
  var cTotalBadge = document.getElementById('bk-dispatch-total-badge');

  if (cAll) cAll.textContent = countAll;
  if (cAvail) cAvail.textContent = countAvail;
  if (cOcc) cOcc.textContent = countOcc;
  if (cBlk) cBlk.textContent = countBlk;
  if (cOff) cOff.textContent = countOff;
  if (cTotalBadge) cTotalBadge.textContent = countAll + ' Units';

  // Filter items
  var filtered = enriched.filter(function(st) {
    if (stDispatchFilter !== 'all' && st.state !== stDispatchFilter) return false;
    if (stDispatchSearch) {
      var hay = (st.name + ' ' + st.unitNumber + ' ' + st.category + ' ' + (st.customerName || '')).toLowerCase();
      if (hay.indexOf(stDispatchSearch) === -1) return false;
    }
    return true;
  });

  if (filtered.length === 0) {
    container.innerHTML = '<div style="text-align:center;padding:2.5rem 1rem;color:var(--text-muted);font-size:0.875rem;">' +
      '<i class="fa-solid fa-filter-circle-xmark" style="font-size:1.5rem;opacity:0.4;margin-bottom:0.5rem;display:block;"></i>' +
      'No stations match the selected filter or search query.' +
    '</div>';
    return;
  }

  // Group by category
  var groups = {};
  filtered.forEach(function(st) {
    if (!groups[st.category]) groups[st.category] = [];
    groups[st.category].push(st);
  });

  var html = '';
  var now = Date.now();

  Object.keys(groups).forEach(function(catName) {
    var items = groups[catName];
    var readyCount = items.filter(function(x) { return x.state === 'available'; }).length;

    html += '<div class="bk-dispatch-swimlane">' +
      '<div class="bk-dispatch-swimlane-head">' +
        '<div style="display:flex;align-items:center;gap:0.5rem;">' +
          '<i class="fa-solid fa-layer-group text-teal"></i>' +
          '<span class="bk-dispatch-swimlane-title">' + escapeHtml(catName) + '</span>' +
          '<span class="badge badge-outline font-mono" style="font-size:0.6875rem;">' + readyCount + ' / ' + items.length + ' Ready</span>' +
        '</div>' +
        '<div style="display:flex;align-items:center;gap:0.35rem;">' +
          '<button type="button" class="btn-dash btn-outline btn-xs" onclick="openCategoryQuickBlock(\'' + escapeHtml(catName) + '\')" title="Block all units in this category"><i class="fa-solid fa-ban"></i> Block Category</button>' +
        '</div>' +
      '</div>' +
      '<div class="bk-dispatch-grid">';

    items.forEach(function(st) {
      var cardClass = 'bk-dispatch-card-item state-' + st.state;
      var dotClass = 'st-live-dot dot-' + st.state;

      html += '<div class="' + cardClass + '" id="dispatch-node-' + escapeHtml(st.id) + '">' +
        '<div class="bk-dispatch-item-top">' +
          '<div style="display:flex;align-items:center;gap:0.4rem;overflow:hidden;">' +
            '<span class="' + dotClass + '"></span>' +
            '<span class="bk-dispatch-item-name">' + escapeHtml(st.name) + '</span>' +
          '</div>' +
          '<span class="font-mono text-muted" style="font-size:0.6875rem;font-weight:700;">#' + escapeHtml(st.unitNumber) + '</span>' +
        '</div>';

      if (st.state === 'occupied') {
        var elapsedMin = st.occupiedSince ? Math.max(0, Math.floor((now - new Date(st.occupiedSince).getTime()) / 60000)) : 0;
        if (st.sessionModel === 'fixed_limit' && elapsedMin >= st.fixedDuration) {
          // Autonomous session conclusion: session duration reached, unit auto-released
          setTimeout(function() {
            stationFinishAndMakeAvailable(st.id);
          }, 50);
          return;
        }
        var timerHtml = '';
        if (st.sessionModel === 'fixed_limit') {
          var leftMin = Math.max(0, st.fixedDuration - elapsedMin);
          timerHtml = '<span class="pill pill-amber font-mono" style="font-size:0.6875rem;"><i class="fa-solid fa-stopwatch"></i> ' + leftMin + 'm left (' + elapsedMin + 'm / ' + st.fixedDuration + 'm)</span>';
        } else {
          timerHtml = '<span class="pill pill-amber font-mono" style="font-size:0.6875rem;"><i class="fa-solid fa-clock"></i> ' + elapsedMin + 'm (Open Visit)</span>';
        }

        html += '<div style="margin-bottom:0.625rem;">' +
          '<div style="display:flex;align-items:center;justify-content:space-between;gap:0.35rem;margin-bottom:0.25rem;">' +
            timerHtml +
            '<span style="font-size:0.6875rem;color:var(--text-muted);"><i class="fa-solid fa-user"></i> ' + escapeHtml(st.customerName || 'Walk-In') + '</span>' +
          '</div>' +
          (st.serviceName ? ('<div style="font-size:0.75rem;color:var(--text-secondary);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(st.serviceName) + '</div>') : '') +
        '</div>' +
        '<button type="button" class="btn-dash btn-emerald btn-sm w-100" style="background:#10b981;color:#ffffff;border-color:#10b981;font-weight:700;" onclick="stationFinishAndMakeAvailable(\'' + escapeHtml(st.id) + '\')" title="1-click release unit and make available immediately"><i class="fa-solid fa-check"></i> Finish &amp; Make Available</button>';

      } else if (st.state === 'blocked') {
        var rsn = (st.activeBlock && st.activeBlock.reason) ? st.activeBlock.reason : 'Scheduled Break';
        html += '<div style="margin-bottom:0.625rem;">' +
          '<div class="pill pill-purple" style="font-size:0.6875rem;display:inline-flex;align-items:center;gap:0.3rem;margin-bottom:0.25rem;"><i class="fa-solid fa-ban"></i> Blocked</div>' +
          '<div style="font-size:0.75rem;color:var(--text-secondary);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(rsn) + '</div>' +
        '</div>' +
        '<button type="button" class="btn-dash btn-outline btn-sm w-100" onclick="unblockStationTarget(\'' + escapeHtml(st.id) + '\')" title="Lift schedule block"><i class="fa-solid fa-unlock"></i> Unblock &amp; Open</button>';

      } else if (st.state === 'off') {
        html += '<div style="margin-bottom:0.625rem;">' +
          '<div class="pill pill-outline" style="font-size:0.6875rem;display:inline-flex;align-items:center;gap:0.3rem;margin-bottom:0.25rem;"><i class="fa-solid fa-wrench"></i> Maintenance</div>' +
          '<div style="font-size:0.75rem;color:var(--text-muted);">Station Offline</div>' +
        '</div>' +
        '<button type="button" class="btn-dash btn-outline btn-sm w-100" onclick="stationToggleOnline(\'' + escapeHtml(st.id) + '\')" title="Turn station online"><i class="fa-solid fa-power-off"></i> Turn Online</button>';

      } else {
        // Available
        var modeDesc = '';
        if (st.sessionModel === 'fixed_limit') {
          modeDesc = '<i class="fa-solid fa-hourglass-half text-teal"></i> ' + st.fixedDuration + 'm Session Limit';
        } else {
          modeDesc = '<i class="fa-solid fa-infinity text-teal"></i> No Time Limit';
        }

        html += '<div style="margin-bottom:0.625rem;">' +
          '<div style="display:flex;align-items:center;justify-content:space-between;gap:0.35rem;margin-bottom:0.25rem;">' +
            '<span class="pill pill-green" style="font-size:0.6875rem;"><i class="fa-solid fa-circle-check"></i> Ready</span>' +
            '<span style="font-size:0.6875rem;color:var(--text-muted);font-weight:600;"><i class="fa-solid fa-users"></i> ' + st.capacity + ' Pax</span>' +
          '</div>' +
          '<div style="font-size:0.6875rem;color:var(--text-muted);">' + modeDesc + '</div>' +
        '</div>' +
        '<div style="display:flex;gap:0.35rem;">' +
          '<button type="button" class="btn-dash btn-accent btn-sm" style="flex:1;font-weight:700;" onclick="stationQuickStartService(\'' + escapeHtml(st.id) + '\')" title="Client arrived: 1-click start service"><i class="fa-solid fa-play"></i> Start Service</button>' +
          '<button type="button" class="btn-dash btn-outline btn-sm icon-btn" onclick="openStationQuickBlock(\'' + escapeHtml(st.id) + '\')" title="Block time/date"><i class="fa-solid fa-ban"></i></button>' +
          '<button type="button" class="btn-dash btn-outline btn-sm icon-btn" onclick="stationToggleOnline(\'' + escapeHtml(st.id) + '\')" title="Turn Offline"><i class="fa-solid fa-power-off"></i></button>' +
        '</div>';
      }

      html += '</div>';
    });

    html += '</div></div>';
  });

  container.innerHTML = html;
};

// 1-Click Immediate Start Service
window.stationQuickStartService = function(stationId) {
  var stations = (stationsState && stationsState.stations) || [];
  var st = stations.find(function(x) { return x.id === stationId; });
  if (!st) return;

  st.status = 'occupied';
  st.walkIn = true;
  st.occupiedSince = Date.now();
  st.customerName = 'Walk-In Guest';

  showToast((st.name || 'Station') + ' is now In Service. Live timer active.', 'success');

  renderDispatchMatrix();
  if (typeof renderStationFloorMatrix === 'function') renderStationFloorMatrix();
  if (typeof updateBookingCapacityState === 'function') updateBookingCapacityState();

  // Persist to backend
  if (!isSandboxedDemoCockpit()) {
    apiPost('/api/admin/facility-stations/status', {
      subdomain: typeof waAiGetSubdomain === 'function' ? waAiGetSubdomain() : 'demo',
      stationId: stationId,
      action: 'seat_walkin',
      walkIn: {
        customerName: 'Walk-In Guest',
        partySize: st.capacity || 1,
        occupiedSince: st.occupiedSince
      }
    }).catch(function() {});
  }
};

// 1-Click Finish and Clear
window.stationFinishAndMakeAvailable = function(stationId) {
  var stations = (stationsState && stationsState.stations) || [];
  var st = stations.find(function(x) { return x.id === stationId; });
  if (!st) return;

  var custPhone = (st.activeOrder && st.activeOrder.customerPhone) || (st.upcomingBooking && st.upcomingBooking.customerPhone) || st.customerPhone || '';
  var custName = st.customerName || (st.activeOrder && st.activeOrder.customerName) || (st.upcomingBooking && st.upcomingBooking.customerName) || '';
  var ordId = (st.activeOrder && st.activeOrder.orderId) || '';
  var stName = st.name || ('Unit ' + (st.unitNumber || ''));
  var occSince = st.occupiedSince || null;
  var parentCat = (stationsState && Array.isArray(stationsState.categories)) ? stationsState.categories.find(function(c) {
    return c && (c.name || '').trim().toLowerCase() === (st.area || st.category || '').trim().toLowerCase();
  }) : null;
  var opMode = st.operationalMode || (parentCat && parentCat.operationalMode) || '';
  var elapsedMs = occSince ? (Date.now() - occSince) : 0;
  var isStaffOnly = (opMode === 'staff_only');
  var isRapidToggle = (elapsedMs > 0 && elapsedMs < 60000 && !ordId);

  st.status = 'available';
  delete st.walkIn;
  delete st.occupiedSince;
  delete st.customerName;
  delete st.serviceName;
  delete st.notes;
  delete st.activeOrder;

  var toastMsg = (custPhone && !isStaffOnly && !isRapidToggle)
    ? stName + ' finished service. Unit is now Available. Post-session review request dispatched.'
    : stName + ' finished service. Unit is now Available for bookings.';
  showToast(toastMsg, 'success');

  renderDispatchMatrix();
  if (typeof renderStationFloorMatrix === 'function') renderStationFloorMatrix();
  if (typeof updateBookingCapacityState === 'function') updateBookingCapacityState();

  if (!isSandboxedDemoCockpit()) {
    apiPost('/api/admin/facility-stations/status', {
      subdomain: typeof waAiGetSubdomain === 'function' ? waAiGetSubdomain() : 'demo',
      stationId: stationId,
      action: 'clear',
      orderId: ordId,
      customerPhone: custPhone,
      customerName: custName,
      occupiedSince: occSince,
      operationalMode: opMode
    }).catch(function() {});
  } else {
    // Sandbox / mock mode: if customer was present, not staff_only and not rapid toggle, simulate review
    if ((custName || custPhone) && !isStaffOnly && !isRapidToggle) {
      setTimeout(function() {
        if (typeof reviewsLoad === 'function') reviewsLoad();
      }, 600);
    }
  }
};

window.stationMakeAllAvailable = function() {
  var stations = (stationsState && stationsState.stations) || [];
  stations.forEach(function(st) {
    st.status = 'available';
    delete st.walkIn;
    delete st.occupiedSince;
    delete st.customerName;
    delete st.serviceName;
    delete st.activeOrder;
  });

  showToast('All configured stations are now Available.', 'success');
  renderDispatchMatrix();
  if (typeof renderStationFloorMatrix === 'function') renderStationFloorMatrix();
  if (typeof updateBookingCapacityState === 'function') updateBookingCapacityState();
};

window.stationToggleOnline = function(stationId) {
  var stations = stationsState.stations || [];
  var st = stations.find(function(x) { return x.id === stationId; });
  if (!st) return;

  var newStatus = (st.status === 'maintenance' || st.active === false) ? 'available' : 'maintenance';
  st.status = newStatus;
  st.active = (newStatus !== 'maintenance');

  var statusMsg = (newStatus === 'available')
    ? (st.name || 'Station') + ' is now Online and ready for bookings.'
    : (st.name || 'Station') + ' set to Offline (Maintenance).';

  showToast(statusMsg, newStatus === 'available' ? 'success' : 'info');

  renderDispatchMatrix();
  if (typeof renderStationFloorMatrix === 'function') renderStationFloorMatrix();
  if (typeof updateBookingCapacityState === 'function') updateBookingCapacityState();

  if (!isSandboxedDemoCockpit()) {
    apiPost('/api/admin/facility-stations/status', {
      subdomain: typeof waAiGetSubdomain === 'function' ? waAiGetSubdomain() : 'demo',
      stationId: stationId,
      action: 'toggle_online',
      status: newStatus
    }).catch(function() {});
  }
};

// Fast Schedule Block Presets delegated to unified quickBlockPreset
// (Defined below with full validation, target scope inheritance, and audit logging)

window.renderActiveBlocksShelf = function() {
  var tray = document.getElementById('bk-active-blocks-tray');
  var countBadge = document.getElementById('bk-active-blocks-count-badge');
  if (!tray) return;

  var blocks = (umState && Array.isArray(umState.blockedSlots)) ? umState.blockedSlots : [];
  if (countBadge) {
    countBadge.textContent = blocks.length + (blocks.length === 1 ? ' Override' : ' Overrides');
  }

  if (blocks.length === 0) {
    tray.innerHTML = '<div style="padding:1.25rem 1rem;text-align:center;background:var(--bg-card-sub);border:1px dashed var(--border-color);border-radius:var(--radius-sm);color:var(--text-muted);font-size:0.8125rem;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0.35rem;">' +
      '<div style="width:36px;height:36px;border-radius:var(--radius-xs,4px);background:var(--bg-input);border:1px solid var(--border-color);display:flex;align-items:center;justify-content:center;color:var(--text-muted);font-size:1rem;margin-bottom:0.15rem;">' +
        '<i class="fa-solid fa-calendar-check"></i>' +
      '</div>' +
      '<div style="font-weight:600;color:var(--text-main);font-size:0.8125rem;">Standard Timetable Active</div>' +
      '<div style="font-size:0.75rem;color:var(--text-muted);max-width:420px;line-height:1.4;">' +
        'Standard hours active. No booking exceptions or overrides currently in place.' +
      '</div>' +
    '</div>';
    return;
  }

  var html = '<div style="display:grid;grid-template-columns:repeat(auto-fill, minmax(min(100%, 250px), 1fr));gap:0.75rem;">';
  blocks.forEach(function(b) {
    var targetBadge = '<span class="badge badge-purple" style="font-size:0.625rem;"><i class="fa-solid fa-globe me-1"></i>All Units</span>';
    var targetLabel = 'Entire Venue';
    if (b.targetStationId && b.targetStationId !== 'all') {
      if (b.targetStationId.startsWith('cat:')) {
        var catName = b.targetStationId.replace('cat:', '');
        targetLabel = 'Category: ' + catName;
        targetBadge = '<span class="badge badge-indigo" style="font-size:0.625rem;"><i class="fa-solid fa-layer-group me-1"></i>' + escapeHtml(catName) + '</span>';
      } else {
        var st = (stationsState.stations || []).find(function(x) { return x.id === b.targetStationId; });
        var stName = st ? (st.name || ('Unit ' + st.unitNumber)) : b.targetStationId;
        targetLabel = stName;
        targetBadge = '<span class="badge badge-teal" style="font-size:0.625rem;"><i class="fa-solid fa-chair me-1"></i>' + escapeHtml(stName) + '</span>';
      }
    }

    var typePill = '';
    if (b.type === 'indefinite') {
      typePill = '<span class="pill pill-outline" style="font-size:0.625rem;border-color:rgba(239,68,68,0.4);color:var(--status-red,#ef4444);"><i class="fa-solid fa-power-off me-1"></i>Offline</span>';
    } else if (b.repeatWeekly) {
      typePill = '<span class="pill pill-outline" style="font-size:0.625rem;border-color:rgba(20,184,166,0.4);color:var(--color-teal);"><i class="fa-solid fa-arrows-rotate me-1"></i>Weekly</span>';
    } else {
      typePill = '<span class="pill pill-outline" style="font-size:0.625rem;color:var(--text-muted);">One-Time</span>';
    }

    var timeDisplay = '';
    if (b.type === 'indefinite') {
      timeDisplay = 'Indefinite Maintenance';
    } else if (b.isFullDay || b.type === 'fullday') {
      timeDisplay = (b.date || '') + ' · Full Day';
    } else {
      timeDisplay = (b.date || '') + ' · ' + (b.timeSlot || (b.time + (b.durationMin ? ' (' + b.durationMin + 'm)' : '')));
    }

    html += '<div style="padding:0.75rem 0.875rem;background:var(--bg-input);border:1px solid var(--border-color);border-radius:var(--radius-sm);display:flex;flex-direction:column;justify-content:space-between;gap:0.625rem;transition:border-color 0.15s ease;">' +
      '<div>' +
        '<div style="display:flex;align-items:center;justify-content:space-between;gap:0.5rem;margin-bottom:0.35rem;">' +
          '<div style="display:flex;align-items:center;gap:0.35rem;overflow:hidden;">' +
            targetBadge +
            typePill +
          '</div>' +
          '<button type="button" class="btn-dash btn-outline btn-xs" onclick="removeBlockById(\'' + escapeHtml(b.id) + '\')" title="Lift this schedule block" style="padding:2px 6px;height:24px;font-size:0.6875rem;"><i class="fa-solid fa-trash-can text-red"></i> Lift</button>' +
        '</div>' +
        '<div style="font-size:0.8125rem;font-weight:700;color:var(--text-main);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' +
          escapeHtml(b.reason || 'Schedule Block') +
        '</div>' +
      '</div>' +
      '<div style="font-size:0.6875rem;color:var(--text-muted);display:flex;align-items:center;gap:0.35rem;border-top:1px dashed var(--border-color);padding-top:0.35rem;margin-top:auto;">' +
        '<i class="fa-solid fa-clock text-purple"></i>' +
        '<span class="font-mono" style="color:var(--text-main);font-weight:600;">' + escapeHtml(timeDisplay) + '</span>' +
      '</div>' +
    '</div>';
  });
  html += '</div>';

  tray.innerHTML = html;
};

window.removeBlockById = function(blockId) {
  if (!umState.blockedSlots) return;
  umState.blockedSlots = umState.blockedSlots.filter(function(b) { return b.id !== blockId; });
  if (typeof bkLogAuditEvent === 'function') {
    bkLogAuditEvent('Block', 'Schedule block lifted', 'Override lifted for block ' + blockId, 'Staff');
  }
  showToast('Schedule block removed.', 'success');
  renderActiveBlocksShelf();
  renderDispatchMatrix();
  var isCapsule = (typeof isClientCapsuleHost === 'function' && isClientCapsuleHost());
  var isDemo = !isCapsule && (typeof isSandboxedDemoCockpit === 'function' ? isSandboxedDemoCockpit() : true);
  if (!isDemo && typeof apiPost === 'function') {
    apiPost('/api/admin/time-blocks/' + encodeURIComponent(blockId), {}, 'DELETE').catch(function() {});
  }
};

window.renderTodayBookingsStream = function() {
  var list = document.getElementById('bk-today-bookings-list');
  var countBadge = document.getElementById('bk-stream-count-badge');
  if (!list) return;

  var appts = (typeof bkAppointments !== 'undefined' && Array.isArray(bkAppointments))
    ? bkAppointments
    : ((bkState && Array.isArray(bkState.appointments)) ? bkState.appointments : []);
  var todayKey = typeof bkDateKey === 'function' ? bkDateKey(new Date()) : new Date().toISOString().split('T')[0];

  var todayAppts = appts.filter(function(a) {
    return a.date === todayKey && a.status !== 'cancelled';
  });

  if (countBadge) countBadge.textContent = todayAppts.length + ' Bookings';

  if (todayAppts.length === 0) {
    list.innerHTML = '<div style="padding:1.5rem;text-align:center;background:var(--bg-card-sub);border:1px dashed var(--border-color);border-radius:var(--radius-sm);color:var(--text-muted);font-size:0.8125rem;">No appointments booked for today yet. WhatsApp AI is active and monitoring customer inquiries.</div>';
    return;
  }

  var html = '<div style="display:flex;flex-direction:column;gap:0.5rem;">';
  todayAppts.forEach(function(a) {
    var statusPill = (a.status === 'confirmed')
      ? '<span class="pill pill-green">Confirmed</span>'
      : (a.status === 'pending' ? '<span class="pill pill-amber">Pending</span>' : '<span class="pill pill-outline">' + escapeHtml(a.status || 'Active') + '</span>');

    var custName = a.customer || a.customerName || 'Customer';
    var svcName = a.service || a.serviceName || 'General Service';
    var ph = a.phone || a.customerPhone || '';
    var dur = a.durationMin || a.duration || 30;

    html += '<div style="padding:0.75rem 1rem;background:var(--bg-input);border:1px solid var(--border-color);border-radius:var(--radius-sm);display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:0.75rem;">' +
      '<div style="display:flex;align-items:center;gap:1rem;">' +
        '<div class="font-mono font-bold text-teal" style="font-size:0.9375rem;width:55px;">' + escapeHtml(a.time || '10:00') + '</div>' +
        '<div>' +
          '<div style="font-size:0.8125rem;font-weight:700;color:var(--text-main);">' + escapeHtml(custName) + '</div>' +
          '<div style="font-size:0.6875rem;color:var(--text-muted);">' + escapeHtml(svcName) + ' (' + dur + 'm)' + (ph ? ' &bull; ' + escapeHtml(ph) : '') + '</div>' +
        '</div>' +
      '</div>' +
      '<div style="display:flex;align-items:center;gap:0.5rem;">' +
        statusPill +
        '<button type="button" class="btn-dash btn-outline btn-xs" onclick="bkOpenApptDetail(\'' + escapeHtml(a.id || '') + '\')"><i class="fa-solid fa-eye"></i> View</button>' +
      '</div>' +
    '</div>';
  });
  html += '</div>';

  list.innerHTML = html;
};

window.openStationQuickBlock = function(stationId) {
  umOpenBlockSlotModal({ target: stationId });
};

window.openCategoryQuickBlock = function(catName) {
  umOpenBlockSlotModal({ target: 'cat:' + catName });
};

window.unblockStationTarget = function(stationId) {
  if (!umState.blockedSlots) return;
  umState.blockedSlots = umState.blockedSlots.filter(function(b) {
    return b.targetStationId !== stationId;
  });

  var st = (stationsState.stations || []).find(function(x) { return x.id === stationId; });
  if (st && st.status === 'maintenance') {
    st.status = 'available';
    st.active = true;
  }

  showToast('Block lifted for unit.', 'success');
  renderDispatchMatrix();
  renderActiveBlocksShelf();
  if (typeof renderStationFloorMatrix === 'function') renderStationFloorMatrix();
};

window.populateBlockTargetDropdown = function(preselectedTarget) {
  var targetSelect = document.getElementById('block-slot-target');
  var cardSelect = document.getElementById('bk-card-block-scope');
  var cardMenu = document.getElementById('bk-card-block-scope-menu');
  var cardDisplay = document.getElementById('bk-card-block-scope-display');

  var stations = (stationsState && Array.isArray(stationsState.stations)) ? stationsState.stations : [];
  var html = '<option value="all">All Stations (Entire Venue)</option>';
  var isAllSel = !preselectedTarget || preselectedTarget === 'all';
  var customMenuHtml = '<button type="button" class="cat-select-option' + (isAllSel ? ' active' : '') + '" data-val="all" onclick="bkSelectCardScopeOption(\'all\', \'All Stations (Entire Venue)\', \'fa-bullseye text-teal\', this)">' +
    '<span class="cat-option-label"><i class="fa-solid fa-bullseye text-teal"></i> All Stations (Entire Venue)</span>' +
    '<i class="fa-solid fa-check cat-option-check"></i>' +
  '</button>';

  var selectedLabel = 'All Stations (Entire Venue)';
  var selectedIcon = 'fa-bullseye text-teal';

  var categories = {};
  stations.forEach(function(st) {
    var cat = (st.area || st.category || 'General Units').trim();
    if (!categories[cat]) categories[cat] = [];
    categories[cat].push(st);
  });

  var catKeys = Object.keys(categories);
  if (catKeys.length > 0) {
    html += '<optgroup label="By Category">';
    customMenuHtml += '<div style="font-size:0.625rem;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.06em;padding:0.35rem 0.6rem 0.2rem;border-top:1px solid var(--border-color);margin-top:2px;">By Category</div>';
    catKeys.forEach(function(cat) {
      var catVal = 'cat:' + cat;
      var catLabel = 'Category: ' + cat + ' (' + categories[cat].length + ' units)';
      var isCatSel = preselectedTarget === catVal;
      if (isCatSel) {
        selectedLabel = catLabel;
        selectedIcon = 'fa-layer-group text-teal';
      }
      html += '<option value="' + escapeHtml(catVal) + '">' + escapeHtml(catLabel) + '</option>';
      customMenuHtml += '<button type="button" class="cat-select-option' + (isCatSel ? ' active' : '') + '" data-val="' + escapeHtml(catVal) + '" onclick="bkSelectCardScopeOption(\'' + escapeHtml(catVal) + '\', \'' + escapeHtml(catLabel) + '\', \'fa-layer-group text-teal\', this)">' +
        '<span class="cat-option-label"><i class="fa-solid fa-layer-group text-teal"></i> ' + escapeHtml(catLabel) + '</span>' +
        '<i class="fa-solid fa-check cat-option-check"></i>' +
      '</button>';
    });
    html += '</optgroup>';

    html += '<optgroup label="Individual Stations">';
    customMenuHtml += '<div style="font-size:0.625rem;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:0.06em;padding:0.35rem 0.6rem 0.2rem;border-top:1px solid var(--border-color);margin-top:2px;">Individual Stations</div>';
    stations.forEach(function(st) {
      var sName = st.name || ('Unit ' + (st.unitNumber || ''));
      var stLabel = sName + ' (#' + (st.unitNumber || '') + ')';
      var isStSel = preselectedTarget === String(st.id);
      if (isStSel) {
        selectedLabel = stLabel;
        selectedIcon = 'fa-chair text-teal';
      }
      html += '<option value="' + escapeHtml(st.id) + '">' + escapeHtml(stLabel) + '</option>';
      customMenuHtml += '<button type="button" class="cat-select-option' + (isStSel ? ' active' : '') + '" data-val="' + escapeHtml(st.id) + '" onclick="bkSelectCardScopeOption(\'' + escapeHtml(st.id) + '\', \'' + escapeHtml(stLabel) + '\', \'fa-chair text-teal\', this)">' +
        '<span class="cat-option-label"><i class="fa-solid fa-chair text-teal"></i> ' + escapeHtml(stLabel) + '</span>' +
        '<i class="fa-solid fa-check cat-option-check"></i>' +
      '</button>';
    });
    html += '</optgroup>';
  }

  if (targetSelect) {
    targetSelect.innerHTML = html;
    if (preselectedTarget) targetSelect.value = preselectedTarget;
  }
  if (cardSelect) {
    if (cardSelect.tagName === 'SELECT') {
      cardSelect.innerHTML = html;
    }
    if (preselectedTarget) cardSelect.value = preselectedTarget;
  }
  if (cardMenu) {
    cardMenu.innerHTML = customMenuHtml;
  }
  if (cardDisplay) {
    cardDisplay.innerHTML = '<i class="fa-solid ' + selectedIcon + '"></i><span>' + escapeHtml(selectedLabel) + '</span>';
  }
};

// Category Inheritance in Manage Stations Modal
window.stationManageCategoryChanged = function(idx, categoryValue) {
  categoryValue = (categoryValue || '').trim();
  if (!categoryValue) return;

  var draft = stationsState.manageDraftStations || [];
  var currentSt = draft[idx];
  if (!currentSt) return;
  currentSt.area = categoryValue;
  currentSt.category = categoryValue;

  var templateSt = draft.find(function(st, i) {
    if (i === idx) return false;
    var cat = (st.area || st.category || '').trim().toLowerCase();
    return cat === categoryValue.toLowerCase();
  });

  if (templateSt) {
    currentSt.capacity = templateSt.capacity || 2;
    currentSt.slotDuration = templateSt.slotDuration || 30;
    currentSt.turnaroundMinutes = templateSt.turnaroundMinutes || 0;
    currentSt.payPolicy = templateSt.payPolicy || 'arrival';
    if (templateSt.services) currentSt.services = templateSt.services.slice();

    var capInput = document.getElementById('st-m-cap-' + idx);
    var turnaroundInput = document.getElementById('st-m-turnaround-' + idx);

    if (capInput) capInput.value = currentSt.capacity;
    if (turnaroundInput) turnaroundInput.value = currentSt.turnaroundMinutes;

    showToast('Inherited configuration from category: ' + categoryValue, 'info');
  }
};

// =========================================================================
// SECTION BOOKINGS: QUICK PRESETS & OPERATIONAL AUDIT LOG ENGINE
// =========================================================================

function quickBlockPreset(presetKey) {
  var now = new Date();
  var todayKey = bkDateKey(now);
  var curHour = now.getHours();
  var curMin = now.getMinutes();

  var cardScope = $('bk-card-block-scope') ? $('bk-card-block-scope').value : 'all';
  var targetScope = cardScope || 'all';

  function pad2(n) { return (n < 10 ? '0' : '') + n; }

  if (presetKey === '1hour') {
    var startH = curHour;
    var startM = Math.ceil(curMin / 5) * 5;
    if (startM >= 60) { startH++; startM = 0; }
    var sTime = pad2(startH % 24) + ':' + pad2(startM);

    var endMinTotal = startH * 60 + startM + 60;
    var endH = Math.floor(endMinTotal / 60) % 24;
    var endM = endMinTotal % 60;
    var eTime = pad2(endH) + ':' + pad2(endM);

    umOpenBlockSlotModal({
      type: 'timespan',
      target: targetScope,
      date: todayKey,
      time: sTime,
      endTime: eTime,
      duration: 60,
      reason: 'Quick Block: Next 1 Hour'
    });
  } else if (presetKey === 'rest_of_day') {
    var startH = curHour;
    var startM = Math.ceil(curMin / 5) * 5;
    if (startM >= 60) { startH++; startM = 0; }
    var sTime = pad2(startH % 24) + ':' + pad2(startM);

    var bounds = (typeof bkTimelineBounds === 'function') ? bkTimelineBounds(now) : null;
    var endH = (bounds && bounds.endH) ? bounds.endH : 23;
    var eTime = (endH <= startH) ? '23:59' : (pad2(endH) + ':00');

    umOpenBlockSlotModal({
      type: 'timespan',
      target: targetScope,
      date: todayKey,
      time: sTime,
      endTime: eTime,
      reason: 'Quick Block: Rest of Today'
    });
  } else if (presetKey === 'tomorrow') {
    var tomorrow = new Date(now.getTime() + 24 * 60 * 60 * 1000);
    var tomorrowKey = bkDateKey(tomorrow);

    umOpenBlockSlotModal({
      type: 'fullday',
      target: targetScope,
      date: tomorrowKey,
      reason: 'Quick Block: Full Day Tomorrow'
    });
  } else if (presetKey === 'weekend') {
    var dayOfWeek = now.getDay();
    var satOffset = (6 - dayOfWeek + 7) % 7;
    if (satOffset === 0 && now.getHours() >= 18) satOffset = 7;
    var sat = new Date(now.getTime() + satOffset * 24 * 60 * 60 * 1000);
    var sun = new Date(sat.getTime() + 24 * 60 * 60 * 1000);

    umOpenBlockSlotModal({
      type: 'daterange',
      target: targetScope,
      startDate: bkDateKey(sat),
      endDate: bkDateKey(sun),
      reason: 'Quick Block: Weekend Closure'
    });
  } else if (presetKey === 'custom') {
    umOpenBlockSlotModal({
      type: 'timespan',
      target: targetScope,
      date: todayKey
    });
  }
}
window.quickBlockPreset = quickBlockPreset;

function bkGetAuditLogs() {
  if (umState && Array.isArray(umState.auditLogs) && umState.auditLogs.length > 0) {
    return umState.auditLogs;
  }
  try {
    var cached = localStorage.getItem('bk_audit_logs');
    if (cached) {
      var parsed = JSON.parse(cached);
      if (Array.isArray(parsed) && parsed.length > 0) {
        if (!umState) umState = {};
        umState.auditLogs = parsed;
        return parsed;
      }
    }
  } catch (e) {}

  var isDemo = Boolean(window.__SANDBOXED_DEMO__) || (typeof DEMO_MODE !== 'undefined' && DEMO_MODE);
  if (!isDemo) {
    if (!umState) umState = {};
    umState.auditLogs = [];
    return [];
  }

  var now = new Date();
  var seeds = [
    {
      id: 'audit-seed-1',
      timestamp: new Date(now.getTime() - 12 * 60000).toISOString(),
      timeFormatted: new Date(now.getTime() - 12 * 60000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      dateFormatted: bkDateKey(now),
      category: 'Station',
      action: 'Station status verified',
      detail: 'All designated stations and spaces active for reservations',
      actor: 'Front Desk'
    },
    {
      id: 'audit-seed-2',
      timestamp: new Date(now.getTime() - 40 * 60000).toISOString(),
      timeFormatted: new Date(now.getTime() - 40 * 60000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      dateFormatted: bkDateKey(now),
      category: 'AI',
      action: 'Autonomous booking dispatch',
      detail: 'WhatsApp AI synchronized with weekly operating timetable',
      actor: 'AI Engine'
    },
    {
      id: 'audit-seed-3',
      timestamp: new Date(now.getTime() - 95 * 60000).toISOString(),
      timeFormatted: new Date(now.getTime() - 95 * 60000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      dateFormatted: bkDateKey(now),
      category: 'Hours',
      action: 'Weekly schedule initialized',
      detail: 'Operating hours verified for online reservations',
      actor: 'Manager'
    }
  ];
  if (!umState) umState = {};
  umState.auditLogs = seeds;
  try { localStorage.setItem('bk_audit_logs', JSON.stringify(seeds)); } catch (e) {}
  return seeds;
}

function bkLogAuditEvent(category, action, detail, actor) {
  var logs = bkGetAuditLogs();
  var now = new Date();
  var entry = {
    id: 'audit-' + Date.now() + '-' + Math.random().toString(36).substr(2, 4),
    timestamp: now.toISOString(),
    timeFormatted: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    dateFormatted: bkDateKey(now),
    category: category || 'Schedule',
    action: action || 'Action recorded',
    detail: detail || '',
    actor: actor || 'Staff'
  };
  logs.unshift(entry);
  if (logs.length > 50) logs = logs.slice(0, 50);
  if (umState) umState.auditLogs = logs;
  try { localStorage.setItem('bk_audit_logs', JSON.stringify(logs)); } catch (e) {}
  bkRenderAuditLogs();
}
window.bkLogAuditEvent = bkLogAuditEvent;

function bkClearAuditLogs() {
  if (umState) umState.auditLogs = [];
  try { localStorage.removeItem('bk_audit_logs'); } catch (e) {}
  bkRenderAuditLogs();
  showToast('Audit log feed cleared.', 'info');
}
window.bkClearAuditLogs = bkClearAuditLogs;

function bkRenderAuditLogs() {
  var container = document.getElementById('bk-audit-logs-container');
  var badge = document.getElementById('bk-audit-count-badge');
  if (!container) return;

  var logs = bkGetAuditLogs();
  if (badge) {
    badge.textContent = logs.length + (logs.length === 1 ? ' Event' : ' Events');
  }

  if (logs.length === 0) {
    container.innerHTML = '<div style="padding:1.5rem;text-align:center;color:var(--bk-text-muted);font-size:0.8125rem;background:var(--bk-row-bg);border:1px dashed var(--bk-row-border);border-radius:var(--radius-sm);">' +
      '<i class="fa-solid fa-clock-rotate-left" style="font-size:1.25rem;margin-bottom:0.35rem;display:block;opacity:0.4;"></i>No recent operational activities recorded.' +
    '</div>';
    return;
  }

  var html = logs.map(function(item) {
    var catBadge = '';
    if (item.category === 'Station') {
      catBadge = '<span class="dash-tag"><i class="fa-solid fa-chair text-teal me-1"></i>Station</span>';
    } else if (item.category === 'Block') {
      catBadge = '<span class="dash-tag"><i class="fa-solid fa-ban text-red me-1"></i>Block</span>';
    } else if (item.category === 'Hours') {
      catBadge = '<span class="dash-tag"><i class="fa-solid fa-business-time text-amber me-1"></i>Hours</span>';
    } else if (item.category === 'AI') {
      catBadge = '<span class="dash-tag"><i class="fa-solid fa-robot text-teal me-1"></i>AI</span>';
    } else if (item.category === 'Reminder') {
      catBadge = '<span class="dash-tag"><i class="fa-solid fa-bell text-teal me-1"></i>Reminder</span>';
    } else {
      catBadge = '<span class="dash-tag"><i class="fa-solid fa-circle-info text-teal me-1"></i>' + escapeHtml(item.category) + '</span>';
    }

    return '<div class="bk-audit-log-item">' +
      '<div class="bk-audit-log-main">' +
        catBadge +
        '<span class="bk-audit-log-action">' + escapeHtml(item.action) + ':</span>' +
        '<span class="bk-audit-log-detail">' + escapeHtml(item.detail) + '</span>' +
      '</div>' +
      '<div class="bk-audit-log-meta">' +
        '<span class="bk-audit-log-actor"><i class="fa-solid fa-user-shield text-teal"></i> ' + escapeHtml(item.actor) + '</span>' +
        '<span class="bk-audit-log-time">' + escapeHtml(item.timeFormatted || '') + '</span>' +
      '</div>' +
    '</div>';
  }).join('');

  container.innerHTML = html;
}
window.bkRenderAuditLogs = bkRenderAuditLogs;
